function masterVolume() {
  return Number.isFinite(state.sound.masterVolume) ? clamp(state.sound.masterVolume, 0, 1) : 1;
}

function musicVolume() {
  return state.sound.muted ? 0 : clamp(state.sound.musicVolume * SOUNDTRACK_LEVEL * masterVolume(), 0, 1);
}

function sfxVolume(baseVolume) {
  return state.sound.muted ? 0 : clamp(baseVolume * state.sound.sfxVolume * masterVolume(), 0, 1);
}

function applySoundSettings() {
  if (soundtrackAudio) soundtrackAudio.volume = musicVolume();
  if (sealPurchaseSfx) sealPurchaseSfx.volume = sfxVolume(SEAL_PURCHASE_SFX_VOLUME);
  if (guessSfx) guessSfx.volume = sfxVolume(GUESS_SFX_VOLUME);
  if (readySfx) readySfx.volume = sfxVolume(READY_SFX_VOLUME);
  if (nextRoundSfx) nextRoundSfx.volume = sfxVolume(NEXT_ROUND_SFX_VOLUME);
  clockTickSfx.forEach((audio) => {
    if (audio) audio.volume = sfxVolume(CLOCK_TICK_SFX_VOLUME);
  });
  Object.entries(artifactSfx).forEach(([id, audio]) => {
    if (audio) audio.volume = artifactSfxVolume(id);
  });
  if (pentakillSfx) pentakillSfx.volume = pentakillSfxVolume();
}

function loadSoundSettings() {
  try {
    const raw = window.localStorage?.getItem(SOUND_SETTINGS_STORAGE_KEY);
    if (!raw) return;
    const saved = JSON.parse(raw);
    if (Number.isFinite(saved.masterVolume)) state.sound.masterVolume = clamp(saved.masterVolume, 0, 1);
    if (Number.isFinite(saved.musicVolume)) state.sound.musicVolume = clamp(saved.musicVolume, 0, 1);
    if (Number.isFinite(saved.sfxVolume)) state.sound.sfxVolume = clamp(saved.sfxVolume, 0, 1);
    if (typeof saved.muted === "boolean") state.sound.muted = saved.muted;
    if (typeof saved.muteInBackground === "boolean") state.sound.muteInBackground = saved.muteInBackground;
  } catch (error) {}
}

// Display settings: trembling (line-boil) outlines. Off by default for players who ask their system to reduce motion.
function loadDisplaySettings() {
  const prefersReducedMotion = Boolean(window.matchMedia?.("(prefers-reduced-motion: reduce)").matches);
  state.display.outlineBoil = prefersReducedMotion ? 0 : 2;
  state.display.screenShake = prefersReducedMotion ? 0 : 2;
  try {
    const raw = window.localStorage?.getItem(DISPLAY_SETTINGS_STORAGE_KEY);
    if (raw) {
      const saved = JSON.parse(raw);
      if (typeof saved.outlineBoil === "boolean") state.display.outlineBoil = saved.outlineBoil ? 2 : 0;
      else if (Number.isFinite(saved.outlineBoil)) state.display.outlineBoil = clamp(Math.round(saved.outlineBoil), 0, 3);
      if (ANIM_SPEED_VALUES.includes(saved.animSpeed)) state.display.animSpeed = saved.animSpeed;
      if (Number.isFinite(saved.screenShake)) state.display.screenShake = clamp(Math.round(saved.screenShake), 0, 2);
      if (Number.isFinite(saved.flashes)) state.display.flashes = clamp(Math.round(saved.flashes), 0, 1);
      if (Number.isFinite(saved.textSize)) state.display.textSize = clamp(Math.round(saved.textSize), 0, 1);
    }
  } catch (error) {}
  applyDisplaySettings();
}

function saveDisplaySettings() {
  try {
    window.localStorage?.setItem(DISPLAY_SETTINGS_STORAGE_KEY, JSON.stringify(state.display));
  } catch (error) {}
}

function applyDisplaySettings() {
  if (typeof document === "undefined" || !document.body) return;
  const level = clamp(Math.round(Number(state.display.outlineBoil) || 0), 0, 3);
  document.body.classList.toggle("outline-boil", level > 0);
  if (level > 0) document.body.style.setProperty("--boil-duration", `${OUTLINE_BOIL_DURATIONS_MS[level]}ms`);
  else document.body.style.removeProperty("--boil-duration");
  document.body.classList.toggle("reduce-flashes", !state.display.flashes);
  document.body.classList.toggle("text-large", Boolean(state.display.textSize));
  document.body.dataset.animSpeed = String(animSpeed());
}

// ---------- iPhone: the hand-drawn lines tremble like the outlines ----------
// Safari mis-draws lines whose picture is animated through a CSS variable, so on iPhone the
// picture is stepped from here instead (body[data-line-frame] = 0/1/2, read by styles.css).
let iosLineBoilFrame = 0;
function stepIosLineBoil() {
  const body = document.body;
  if (body?.classList.contains("outline-boil") && !document.hidden) {
    iosLineBoilFrame = (iosLineBoilFrame + 1) % 3;
    body.dataset.lineFrame = String(iosLineBoilFrame);
  }
  const duration = body ? parseFloat(getComputedStyle(body).getPropertyValue("--boil-duration")) : NaN;
  setTimeout(stepIosLineBoil, (Number.isFinite(duration) && duration > 0 ? duration : 375) / 3);
}
if (NATIVE_IOS_APP) setTimeout(stepIosLineBoil, 0);

// ---------- iPhone audio: Web Audio instead of <audio> for the short sounds ----------
// On iPhone, <audio> ignores .volume (everything plays at full volume), starting one is slow
// enough to stutter taps and hit animations, and a playing <audio> makes iOS treat the game as a
// media player (lock screen / Now Playing controls). So on iPhone every sound, the looping music
// included, is decoded once and played through Web Audio with its own gain. The rest of the game
// code is unchanged: this swaps play/pause/load/volume/paused on <audio> elements, on iPhone only.
const iosAudio = NATIVE_IOS_APP ? setupIosAudio() : null;

function setupIosAudio() {
  const AudioCtx = window.AudioContext || window.webkitAudioContext;
  if (!AudioCtx || typeof HTMLMediaElement === "undefined" || typeof fetch !== "function") return null;
  let ctx;
  try {
    ctx = new AudioCtx();
  } catch (error) {
    return null;
  }
  const proto = HTMLMediaElement.prototype;
  const nativePause = proto.pause;
  const buffers = new Map(); // url -> AudioBuffer, or a pending Promise, or null when it failed
  const urlOf = (el) => el.currentSrc || el.src || "";
  const isMusic = (el) => Boolean(el.loop);
  const resume = () => {
    if (ctx.state !== "running") ctx.resume().catch(() => {});
  };

  // the music is minutes long: decode it at a lower rate so it does not take ~90 MB of memory
  const OfflineCtx = window.OfflineAudioContext || window.webkitOfflineAudioContext;
  function decoderFor(lowRate) {
    if (!lowRate || !OfflineCtx) return ctx;
    try {
      return new OfflineCtx(2, 1, 32000);
    } catch (error) {
      return ctx;
    }
  }

  function loadBuffer(url, lowRate = false) {
    if (!url || buffers.has(url)) return;
    const decoder = decoderFor(lowRate);
    const pending = fetch(url)
      .then((response) => response.arrayBuffer())
      .then((data) => new Promise((resolve, reject) => decoder.decodeAudioData(data, resolve, reject)))
      .then((buffer) => {
        buffers.set(url, buffer);
        return buffer;
      })
      .catch(() => {
        buffers.set(url, null);
        return null;
      });
    buffers.set(url, pending);
  }

  function stopSources(el) {
    if (!el.__iosSources) return;
    el.__iosSources.forEach((source) => {
      try {
        source.onended = null;
        source.stop();
        source.disconnect();
        source.__gain?.disconnect();
      } catch (error) {}
    });
    el.__iosSources.clear();
  }

  Object.defineProperty(proto, "volume", {
    configurable: true,
    get() {
      return this.__iosVolume ?? 1;
    },
    set(value) {
      const volume = Math.min(1, Math.max(0, Number(value) || 0));
      this.__iosVolume = volume;
      if (this.__iosGain) this.__iosGain.gain.value = volume;
    }
  });

  // ---- looping music: one buffer source at a time, remembers where it was paused ----
  function musicState(el) {
    if (!el.__iosMusic) el.__iosMusic = { source: null, wanted: false, offset: 0, startedAt: 0 };
    return el.__iosMusic;
  }

  const musicEls = new Set();
  let needsRebuild = false;

  function startMusic(el) {
    musicEls.add(el);
    const music = musicState(el);
    if (!music.wanted || music.source) return;
    const buffer = buffers.get(urlOf(el));
    if (!buffer || typeof buffer.then === "function") return; // starts when decoding finishes
    try {
      if (!el.__iosGain) {
        el.__iosGain = ctx.createGain();
        el.__iosGain.connect(ctx.destination);
      }
      el.__iosGain.gain.value = el.__iosVolume ?? 1;
      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.loop = true;
      source.connect(el.__iosGain);
      music.offset %= buffer.duration;
      source.start(0, music.offset);
      music.startedAt = ctx.currentTime;
      music.source = source;
    } catch (error) {}
  }

  function stopMusic(el) {
    const music = el.__iosMusic;
    if (!music) return;
    music.wanted = false;
    if (!music.source) return;
    const duration = music.source.buffer?.duration || 0;
    if (duration) music.offset = (music.offset + ctx.currentTime - music.startedAt) % duration;
    try {
      music.source.stop();
    } catch (error) {}
    music.source = null;
  }

  const nativePaused = Object.getOwnPropertyDescriptor(proto, "paused");
  Object.defineProperty(proto, "paused", {
    configurable: true,
    get() {
      if (this.__iosMusic) return !this.__iosMusic.wanted;
      return nativePaused?.get ? nativePaused.get.call(this) : true;
    }
  });

  proto.load = function () {
    const url = urlOf(this);
    if (!isMusic(this)) {
      loadBuffer(url);
      return;
    }
    loadBuffer(url, true);
    const pending = buffers.get(url);
    if (pending && typeof pending.then === "function") pending.then(() => startMusic(this));
  };

  proto.play = function () {
    resume();
    if (isMusic(this)) {
      const music = musicState(this);
      music.wanted = true;
      if (!buffers.has(urlOf(this))) this.load();
      startMusic(this);
      return Promise.resolve();
    }
    const url = urlOf(this);
    const buffer = buffers.get(url);
    const ended = () => setTimeout(() => this.dispatchEvent(new Event("ended")), 0);
    // still decoding (only in the first moments after launch): skip it rather than blast it
    if (this.muted || !buffer || typeof buffer.then === "function") {
      loadBuffer(url);
      ended();
      return Promise.resolve();
    }
    stopSources(this); // replaying the same element restarts it, as <audio> does
    try {
      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.playbackRate.value = this.playbackRate || 1;
      const gain = ctx.createGain();
      gain.gain.value = this.__iosVolume ?? 1;
      source.connect(gain);
      gain.connect(ctx.destination);
      source.__gain = gain;
      if (!this.__iosSources) this.__iosSources = new Set();
      this.__iosSources.add(source);
      source.onended = () => {
        this.__iosSources?.delete(source);
        // let the finished sound go; otherwise every sound ever played stays wired to the speakers
        try {
          source.disconnect();
          gain.disconnect();
        } catch (error) {}
        this.dispatchEvent(new Event("ended"));
      };
      const offset = Math.max(0, Number(this.__iosStartOffset ?? this.currentTime) || 0);
      source.start(0, Math.min(offset, Math.max(0, buffer.duration - 0.01)));
    } catch (error) {
      ended();
    }
    return Promise.resolve();
  };

  proto.pause = function () {
    stopSources(this);
    stopMusic(this);
    return nativePause.call(this);
  };

  // After the app has been in the background, iOS can leave the audio context stuck
  // ("interrupted", or "running" but silent), and resume() does not bring it back. So on the way
  // back a fresh context is made; the decoded sounds carry over, and the music restarts where it
  // was. iPhone only lets audio start from a touch, so the first tap after returning wakes it.
  function rebuild() {
    let fresh;
    try {
      fresh = new AudioCtx();
    } catch (error) {
      return;
    }
    const old = ctx;
    const playing = [];
    musicEls.forEach((el) => {
      if (el.__iosMusic?.source) {
        stopMusic(el);
        playing.push(el);
      }
    });
    ctx = fresh;
    musicEls.forEach((el) => {
      el.__iosGain = null;
    });
    try {
      old.close().catch(() => {});
    } catch (error) {}
    playing.forEach((el) => {
      el.__iosMusic.wanted = true;
      startMusic(el);
    });
  }

  // Telling that the app was away is unreliable on iPhone (page events don't always fire), so
  // several signs are watched: the page hiding, the app's pause/resume events, timers that
  // stopped running for a while, and an audio clock that says "running" but stands still.
  document.addEventListener("visibilitychange", () => {
    if (document.hidden) needsRebuild = true;
  });
  ["pause", "resume"].forEach((type) => document.addEventListener(type, () => (needsRebuild = true)));
  window.addEventListener("pagehide", () => (needsRebuild = true));
  let lastTick = Date.now();
  let lastAudioTime = ctx.currentTime;
  let lastCtx = ctx;
  setInterval(() => {
    const now = Date.now();
    if (ctx !== lastCtx) {
      // a fresh context starts its clock at 0: begin measuring again
      lastCtx = ctx;
      lastTick = now;
      lastAudioTime = ctx.currentTime;
      return;
    }
    const wall = (now - lastTick) / 1000;
    if (wall > 2.5) needsRebuild = true;
    else if (!document.hidden && ctx.state === "running" && wall > 0.8 && ctx.currentTime - lastAudioTime < 0.2) {
      needsRebuild = true;
    }
    lastTick = now;
    lastAudioTime = ctx.currentTime;
  }, 1000);

  function wake() {
    if (ctx.state === "interrupted" || ctx.state === "closed") needsRebuild = true;
    if (needsRebuild) {
      needsRebuild = false;
      rebuild();
    }
    resume();
  }

  ["touchend", "click", "keydown"].forEach((type) => document.addEventListener(type, wake, true));

  return {
    get ctx() {
      return ctx;
    },
    suspend: () => {
      needsRebuild = true;
      ctx.suspend().catch(() => {});
    },
    resume: wake
  };
}

// ---------- animation speed (Settings > Gameplay): x1, x2, x4 ----------
// Game animations (SEAL triggers, the READY reveal steps, hits, pops) run this many times faster.
function animSpeed() {
  const value = Number(state.display?.animSpeed);
  return ANIM_SPEED_VALUES.includes(value) ? value : 1;
}

// a duration in ms at the chosen speed
function gameMs(ms) {
  return Math.max(0, Math.round(ms / animSpeed()));
}

// CSS animations of the game itself are sped up as they start (menu, intro and the trembling
// outlines keep their own pace)
const SPEED_SCALED_ANIMATIONS = /^(seal-|slam-wave|hit-|hud-pop|damage-pop|health-ghost|ko-pop|death-pulse|pentakill-fade)/;

function installAnimationSpeed() {
  if (typeof document === "undefined") return;
  document.addEventListener(
    "animationstart",
    (event) => {
      const speed = animSpeed();
      if (speed === 1 || !SPEED_SCALED_ANIMATIONS.test(event.animationName || "")) return;
      const target = event.target;
      if (typeof document.getAnimations !== "function") return;
      // includes the element's ::before / ::after animations (their effect target is the element)
      document.getAnimations().forEach((animation) => {
        if (animation.animationName !== event.animationName || animation.effect?.target !== target) return;
        if (animation.playbackRate !== speed) animation.playbackRate = speed;
      });
    },
    true
  );
}

function saveSoundSettings() {
  try {
    window.localStorage?.setItem(SOUND_SETTINGS_STORAGE_KEY, JSON.stringify(state.sound));
  } catch (error) {}
}

function isNativeArcadeApp() {
  return NATIVE_ARCADE_APP || Boolean(typeof document !== "undefined" && document.body?.classList.contains("native-arcade"));
}

function hasSavedArcadeRun() {
  try {
    return readArcadeRunSlots().length > 0;
  } catch (error) {
    return false;
  }
}

function markNativeArcadeResumeOnForeground() {
  if (!isNativeArcadeApp() || state.mode !== "arcade") return;
  try {
    window.sessionStorage?.setItem(ARCADE_RUN_SESSION_RESUME_KEY, "1");
  } catch (error) {}
}

function clearNativeArcadeResumeOnForeground() {
  if (!isNativeArcadeApp()) return;
  try {
    window.sessionStorage?.removeItem(ARCADE_RUN_SESSION_RESUME_KEY);
  } catch (error) {}
}

function shouldResumeNativeArcadeOnForeground() {
  if (!isNativeArcadeApp() || !hasSavedArcadeRun()) return false;
  try {
    return window.sessionStorage?.getItem(ARCADE_RUN_SESSION_RESUME_KEY) === "1";
  } catch (error) {
    return false;
  }
}

function resumeNativeArcadeOnForeground() {
  if (!shouldResumeNativeArcadeOnForeground()) return false;
  if (loadArcadeRun()) {
    render();
    return true;
  }
  clearNativeArcadeResumeOnForeground();
  return false;
}

function encodeArcadeSaveValue(key, value) {
  if (value instanceof Map) {
    return { __dearthType: "Map", entries: Array.from(value.entries()) };
  }
  if (value instanceof Set) {
    return { __dearthType: "Set", values: Array.from(value.values()) };
  }
  if (typeof value === "number" && !Number.isFinite(value)) {
    return {
      __dearthType: "Number",
      value: value === Infinity ? "Infinity" : value === -Infinity ? "-Infinity" : "NaN"
    };
  }
  return value;
}

function decodeArcadeSaveValue(key, value) {
  if (!value || typeof value !== "object" || !value.__dearthType) return value;
  if (value.__dearthType === "Map") return new Map(Array.isArray(value.entries) ? value.entries : []);
  if (value.__dearthType === "Set") return new Set(Array.isArray(value.values) ? value.values : []);
  if (value.__dearthType === "Number") {
    if (value.value === "Infinity") return Infinity;
    if (value.value === "-Infinity") return -Infinity;
    return NaN;
  }
  return value;
}

function arcadeRunSaveSnapshot() {
  const snapshot = {};
  Object.keys(state).forEach((key) => {
    if (key === "sound" || key === "pvp" || key === "roundRevealAnimation") return;
    snapshot[key] = state[key];
  });
  snapshot.mode = "arcade";
  snapshot.pauseOpen = false;
  snapshot.pauseScreen = "main";
  snapshot.menuCollectionOpen = false;
  snapshot.menuGiftsOpen = false;
  snapshot.pauseDevOpen = false;
  snapshot.mobileOfferingsOpen = false;
  return snapshot;
}

function createArcadeRunSlotId() {
  return `run-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

function normalizeArcadeRunPayload(payload) {
  if (!payload || payload.version !== ARCADE_RUN_SAVE_VERSION || !payload.state || payload.state.mode !== "arcade") return null;
  const slotId = payload.slotId || payload.state.currentRunSlotId || createArcadeRunSlotId();
  const startedAt = Number(payload.startedAt || payload.state.runStartedAt || payload.savedAt || Date.now());
  const lastPlayedAt = Number(payload.lastPlayedAt || payload.savedAt || startedAt);
  return {
    version: ARCADE_RUN_SAVE_VERSION,
    slotId,
    startedAt,
    lastPlayedAt,
    state: payload.state
  };
}

function sortArcadeRunSlots(slots) {
  return slots
    .map(normalizeArcadeRunPayload)
    .filter(Boolean)
    .sort((a, b) => (b.lastPlayedAt || 0) - (a.lastPlayedAt || 0))
    .slice(0, ARCADE_RUN_SLOT_COUNT);
}

function readLegacyArcadeRunSlot() {
  try {
    const raw = window.localStorage?.getItem(ARCADE_RUN_STORAGE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw, decodeArcadeSaveValue);
    const normalized = normalizeArcadeRunPayload(parsed);
    if (normalized && !parsed.slotId && !parsed.state?.currentRunSlotId) normalized.slotId = "legacy-run";
    return normalized;
  } catch (error) {
    return null;
  }
}

function readArcadeRunSlots() {
  try {
    const raw = window.localStorage?.getItem(ARCADE_RUN_SLOTS_STORAGE_KEY);
    if (!raw) {
      const legacy = readLegacyArcadeRunSlot();
      return legacy ? [legacy] : [];
    }
    const parsed = JSON.parse(raw, decodeArcadeSaveValue);
    const slots = Array.isArray(parsed?.slots) ? parsed.slots : Array.isArray(parsed) ? parsed : [];
    const normalized = sortArcadeRunSlots(slots);
    if (!normalized.length) {
      const legacy = readLegacyArcadeRunSlot();
      return legacy ? [legacy] : [];
    }
    return normalized;
  } catch (error) {
    const legacy = readLegacyArcadeRunSlot();
    return legacy ? [legacy] : [];
  }
}

function writeArcadeRunSlots(slots) {
  const normalized = sortArcadeRunSlots(slots);
  try {
    window.localStorage?.setItem(
      ARCADE_RUN_SLOTS_STORAGE_KEY,
      JSON.stringify({ version: ARCADE_RUN_SAVE_VERSION, slots: normalized }, encodeArcadeSaveValue)
    );
  } catch (error) {}
  return normalized;
}

function upsertArcadeRunPayload(payload) {
  const normalizedPayload = normalizeArcadeRunPayload(payload);
  if (!normalizedPayload) return;
  const slots = readArcadeRunSlots().filter((slot) => slot.slotId !== normalizedPayload.slotId);
  slots.unshift(normalizedPayload);
  writeArcadeRunSlots(slots);
}

function removeArcadeRunSlot(slotId) {
  if (!slotId) return;
  writeArcadeRunSlots(readArcadeRunSlots().filter((slot) => slot.slotId !== slotId));
}

// Saving copies the whole run into localStorage, and the run grows (MEMORY, game memory) the
// longer you play. render() used to save on every redraw, which made long runs stutter, most
// of all on iPhone. Redraws now ask for a save at most once a second; leaving the table, the
// app going to the background and the other explicit saves still write straight away.
let arcadeRunSaveTimer = null;
function scheduleArcadeRunSave() {
  if (arcadeRunSaveTimer) return;
  arcadeRunSaveTimer = setTimeout(() => {
    arcadeRunSaveTimer = null;
    saveArcadeRun();
  }, 1000);
}

function saveArcadeRun() {
  if (arcadeRunSaveTimer) {
    clearTimeout(arcadeRunSaveTimer);
    arcadeRunSaveTimer = null;
  }
  if (state.mode !== "arcade") return;
  // the story's two tutorial rounds are not a saved run until the pact is made
  if (typeof introBlocksRunSave === "function" && introBlocksRunSave()) return;
  if (state.gameOver) {
    removeArcadeRunSlot(state.currentRunSlotId);
    return;
  }
  try {
    if (!state.currentRunSlotId) state.currentRunSlotId = createArcadeRunSlotId();
    if (!Number.isFinite(state.runStartedAt)) state.runStartedAt = Date.now();
    updateArcadeRecordsFromCurrentRun();
    const payload = {
      version: ARCADE_RUN_SAVE_VERSION,
      slotId: state.currentRunSlotId,
      startedAt: state.runStartedAt,
      savedAt: Date.now(),
      lastPlayedAt: Date.now(),
      state: arcadeRunSaveSnapshot()
    };
    upsertArcadeRunPayload(payload);
  } catch (error) {}
}

function removeCorruptArcadeRunSave(slotId = "") {
  try {
    if (slotId) removeArcadeRunSlot(slotId);
    else {
      window.localStorage?.removeItem(ARCADE_RUN_SLOTS_STORAGE_KEY);
      window.localStorage?.removeItem(ARCADE_RUN_STORAGE_KEY);
    }
  } catch (error) {}
}

function ensureMap(value) {
  if (value instanceof Map) return value;
  return new Map(Array.isArray(value) ? value : []);
}

function ensureSet(value) {
  if (value instanceof Set) return value;
  return new Set(Array.isArray(value) ? value : []);
}

function normalizeLoadedRoundState(round) {
  if (!round || typeof round !== "object") return null;
  [
    "botSubmittedGuesses",
    "botEffectiveGuesses",
    "activeUseItemCounts",
    "artifactTargetCountsByBotId",
    "botDamageTotals",
    "targetDifferenceDamageByBotId",
    "unmultipliedDamageByBotId"
  ].forEach((key) => {
    round[key] = ensureMap(round[key]);
  });
  [
    "removedBotIds",
    "twinDetonatorTriggeredIds",
    "highDamageSinBotIds",
    "revealedBotIds",
    "amonRewardKeys",
    "bossRevealPunishedKeys",
    "bossAbilityNullifiedBotIds",
    "belethTriggeredBotIds",
    "kalhaSuppressedPassiveIds",
    "devTemporaryActiveUids",
    "padmaVulnerableBotIds",
    "triggeredPassiveIds",
    "animatedPassiveIds",
    "aliveIdsAtStart",
    "criticalHitKeys"
  ].forEach((key) => {
    round[key] = ensureSet(round[key]);
  });
  if (!Array.isArray(round.extraAverageGuesses)) round.extraAverageGuesses = [];
  if (!Array.isArray(round.temporaryBotSinBonuses)) round.temporaryBotSinBonuses = [];
  if (!Array.isArray(round.eliminationCreditRecords)) round.eliminationCreditRecords = [];
  if (!Array.isArray(round.eliminatedPersonalities)) round.eliminatedPersonalities = [];
  if (!Array.isArray(round.pendingEndOfRoundBotDamages)) round.pendingEndOfRoundBotDamages = [];
  if (!Array.isArray(round.moonCrossBotIds)) round.moonCrossBotIds = [];
  if (!Array.isArray(round.roundEvents)) round.roundEvents = [];
  if (!round.selfStackingConditionCounts || typeof round.selfStackingConditionCounts !== "object") {
    round.selfStackingConditionCounts = {};
  }
  Object.values(SELF_STACKING_SEAL_SPECS).forEach((spec) => {
    if (!Number.isFinite(round.selfStackingConditionCounts[spec.key])) round.selfStackingConditionCounts[spec.key] = 0;
  });
  if (!Number.isFinite(round.selfStackingCriticalDamage)) round.selfStackingCriticalDamage = 0;
  round.resolvingEndOfRoundPassives = false;
  return round;
}

function normalizeLoadedArcadeRun() {
  state.mode = "arcade";
  state.menuScreen = "main";
  state.pauseOpen = false;
  state.pauseDevOpen = false;
  state.mobileOfferingsOpen = false;
  state.pvp = null;
  if (!state.player || typeof state.player !== "object") {
    state.player = { hp: PLAYER_MAX_HP, maxHp: PLAYER_MAX_HP, credits: STARTING_CREDITS, passives: [], actives: [] };
  }
  if (!Array.isArray(state.player.passives)) state.player.passives = [];
  if (!Array.isArray(state.player.actives)) state.player.actives = [];
  if (!Array.isArray(state.bots)) state.bots = [];
  if (!Array.isArray(state.shop)) state.shop = [];
  if (!Array.isArray(state.log)) state.log = [];
  if (!Array.isArray(state.gameMemory)) state.gameMemory = [];
  if (!Array.isArray(state.playerDamageSources)) state.playerDamageSources = [];
  if (!Array.isArray(state.playerHealSources)) state.playerHealSources = [];
  if (!Array.isArray(state.playerCreditSources)) state.playerCreditSources = [];
  if (!Number.isFinite(state.critMomentumBonus)) state.critMomentumBonus = 0;
  if (typeof state.playerCritLastRound !== "boolean") state.playerCritLastRound = false;
  if (!Number.isFinite(state.freeRerolls)) state.freeRerolls = 0;
  if (!Number.isFinite(state.freeRerollsUntilRound)) state.freeRerollsUntilRound = 0;
  if (!Number.isFinite(state.trinityRevealsNextRound)) state.trinityRevealsNextRound = 0;
  state.trinityEliteNextShop = Boolean(state.trinityEliteNextShop);
  if (!Array.isArray(state.trinityShopSealsNextShop)) state.trinityShopSealsNextShop = [];
  state.exactGuessCritCharged = Boolean(state.exactGuessCritCharged);
  // SEALS keep their current name and text after a rename (older saves hold a copy of both)
  [...state.player.passives, ...state.shop.map((slot) => slot?.item)].forEach((item) => {
    if (item?.type === "passive" && ITEMS[item.id]) {
      item.name = ITEMS[item.id].name;
      item.description = ITEMS[item.id].description;
    }
  });
  if (!Number.isFinite(state.totalArtifactsUsed)) state.totalArtifactsUsed = 0;
  if (state.boundDemon && !GOETIC_BOSS_BY_KEY[state.boundDemon] && !ARCHANGEL_BY_KEY[state.boundDemon]) state.boundDemon = null;
  state.archangelQueue = Array.isArray(state.archangelQueue) ? state.archangelQueue.filter((key) => ARCHANGEL_BY_KEY[key]) : [];
  if (!Number.isFinite(state.pendingSelfStackingPentakillDamage)) state.pendingSelfStackingPentakillDamage = 0;
  if (!Number.isFinite(state.pendingSelfStackingPentakillRound)) state.pendingSelfStackingPentakillRound = 0;
  state.runStats = normalizeRunStats(state.runStats);
  if (!state.currentRunSlotId) state.currentRunSlotId = createArcadeRunSlotId();
  if (!Number.isFinite(state.runStartedAt)) state.runStartedAt = Date.now();
  selfStackingGameConditionCounts();
  if (!state.lastUsedArtifact || typeof state.lastUsedArtifact !== "object" || !ACTIVE_IDS.includes(state.lastUsedArtifact.id)) {
    state.lastUsedArtifact = null;
  }
  if (!state.sealStats || typeof state.sealStats !== "object") state.sealStats = {};
  // older saves have no snapshot; the records as they are now are the closest guess
  if (!state.recordsAtRunStart || typeof state.recordsAtRunStart !== "object") snapshotRecordsAtRunStart();
  state.roundState = normalizeLoadedRoundState(state.roundState);
  if (!state.finalBossPhase && !state.finalBossQueued) ensureBossKillInterval();
  [...state.player.actives, ...state.shop.map((slot) => slot?.item), state.lastUsedArtifact].forEach((item) => {
    if (item?.type === "active" && ACTIVE_IDS.includes(item.id)) item.price = ITEMS[item.id].price;
  });
  state.bots.forEach((bot) => {
    if (!Array.isArray(bot.passiveKeys)) bot.passiveKeys = [];
    bot.passiveKeys = bot.passiveKeys.filter((key) => BOSS_PASSIVES[key]);
    if (bot.isBoss && !bot.uniqueKey && !bot.finalKey && !bot.archangelKey && !bot.passiveKeys.length) {
      bot.passiveKeys = randomBossPassiveKeys(1);
    }
    if (bot.buffPassiveKey && !PYROS_GIFT_PASSIVES[bot.buffPassiveKey]) bot.buffPassiveKey = null;
    bot.poisonCounters = Number.isFinite(bot.poisonCounters) ? Math.max(0, Math.ceil(bot.poisonCounters)) : 0;
    bot.poisonSources = Object.fromEntries(
      Object.entries(bot.poisonSources && typeof bot.poisonSources === "object" ? bot.poisonSources : {}).filter(
        ([id, count]) => PASSIVE_IDS.includes(id) && Number.isFinite(count) && count > 0
      )
    );
    bot.poisonDamageTaken = Number.isFinite(bot.poisonDamageTaken) ? Math.max(0, Math.ceil(bot.poisonDamageTaken)) : 0;
    // a Goetic BOSS suppresses its demon's current SEAL (Amy's moved from p70 to p134)
    const goeticSpec = bot.goeticKey ? GOETIC_BOSS_BY_KEY[bot.goeticKey] : null;
    if (goeticSpec?.passiveId && ITEMS[goeticSpec.passiveId]) {
      bot.goeticPassiveId = goeticSpec.passiveId;
      bot.goeticSealName = ITEMS[goeticSpec.passiveId].name;
    }
    if (!Array.isArray(bot.memory)) bot.memory = [];
    if (!Array.isArray(bot.damageSources)) bot.damageSources = [];
    if (!Array.isArray(bot.healSources)) bot.healSources = [];
    if (!Array.isArray(bot.sinSources)) bot.sinSources = [];
    trimBotMemoryToLimit(bot);
  });
}

function loadArcadeRun(slotId = "") {
  try {
    const slots = readArcadeRunSlots();
    const payload = normalizeArcadeRunPayload(slotId ? slots.find((slot) => slot.slotId === slotId) : slots[0]);
    if (!payload) return false;
    if (!payload.state || payload.state.mode !== "arcade") {
      removeCorruptArcadeRunSave(slotId);
      return false;
    }
    // saves from before the Ars Goetia binding have none; saves from before the Archangels get all seven
    state.boundDemon = null;
    state.archangelQueue = ARCHANGEL_KEYS.slice();
    Object.keys(payload.state).forEach((key) => {
      if (key === "sound" || key === "pvp" || !(key in state)) return;
      state[key] = payload.state[key];
    });
    state.currentRunSlotId = payload.slotId;
    state.runStartedAt = payload.startedAt;
    normalizeLoadedArcadeRun();
    saveArcadeRun();
    return true;
  } catch (error) {
    removeCorruptArcadeRunSave(slotId);
    return false;
  }
}

function loadAudioElement(audio) {
  try {
    audio.load();
  } catch (error) {}
  return audio;
}

function ensureSoundtrack() {
  if (soundtrackAudio) return soundtrackAudio;
  soundtrackAudio = new Audio(SOUNDTRACK_SRC);
  soundtrackAudio.loop = true;
  soundtrackAudio.preload = "auto";
  soundtrackAudio.volume = musicVolume();
  return loadAudioElement(soundtrackAudio);
}

function playSoundtrack() {
  // the first-launch story keeps the music off until Satan's pact is sealed
  if (typeof introHoldsMusic === "function" && introHoldsMusic()) return;
  const audio = ensureSoundtrack();
  audio.play().catch(() => {});
}

function primeSfxAudio() {
  if (sfxPrimed) return;
  sfxPrimed = true;
  // iPhone decodes every sound up front (iosAudio), so there is nothing to warm up
  if (iosAudio) return;
  [
    ensureSealPurchaseSfx(),
    ensureButtonSfx("guess"),
    ensureButtonSfx("ready"),
    ensureNextRoundSfx(),
    ...CLOCK_TICK_SFX_SRCS.map((_, index) => ensureClockTickSfx(index)),
    ...Object.keys(ARTIFACT_SFX).map((id) => ensureArtifactSfx(id)),
    ensurePentakillSfx()
  ].forEach((audio) => {
    if (!audio) return;
    try {
      const primer = audio.cloneNode(true);
      primer.volume = 0;
      const attempt = primer.play();
      const reset = () => {
        try {
          primer.pause();
          primer.currentTime = 0;
        } catch (error) {}
      };
      if (attempt && typeof attempt.then === "function") {
        attempt.then(reset).catch(() => {});
      } else {
        reset();
      }
    } catch (error) {}
  });
}

function unlockSoundtrack() {
  playSoundtrack();
  primeSfxAudio();
  document.removeEventListener("pointerdown", unlockSoundtrack);
  document.removeEventListener("keydown", unlockSoundtrack);
}

function resumeSoundtrack() {
  playSoundtrack();
}

function pauseAudioElement(audio) {
  if (!audio) return;
  try {
    audio.pause();
  } catch (error) {}
}

function pauseGameAudioForBackground() {
  // leaving the app fires more than one of blur / visibilitychange / pagehide: the second call
  // must not forget that the music was playing before the first one paused it
  soundtrackPausedByAppBackground =
    soundtrackPausedByAppBackground || Boolean(soundtrackAudio && !soundtrackAudio.paused);
  [
    soundtrackAudio,
    sealPurchaseSfx,
    guessSfx,
    readySfx,
    nextRoundSfx,
    ...clockTickSfx,
    ...Object.values(artifactSfx),
    pentakillSfx,
    ...activeOneShotSfxInstances
  ].forEach(pauseAudioElement);
  activeOneShotSfxInstances.clear();
  iosAudio?.suspend();
}

function resumeGameAudioAfterForeground() {
  iosAudio?.resume();
  if (!soundtrackPausedByAppBackground) return;
  soundtrackPausedByAppBackground = false;
  resumeSoundtrack();
}

function ensureSealPurchaseSfx() {
  if (sealPurchaseSfx) return sealPurchaseSfx;
  sealPurchaseSfx = new Audio(SEAL_PURCHASE_SFX_SRC);
  sealPurchaseSfx.preload = "auto";
  sealPurchaseSfx.volume = sfxVolume(SEAL_PURCHASE_SFX_VOLUME);
  return loadAudioElement(sealPurchaseSfx);
}

function ensureButtonSfx(kind) {
  if (kind === "guess") {
    if (!guessSfx) {
      guessSfx = new Audio(GUESS_SFX_SRC);
      guessSfx.preload = "auto";
      guessSfx.volume = sfxVolume(GUESS_SFX_VOLUME);
      loadAudioElement(guessSfx);
    }
    return guessSfx;
  }

  if (!readySfx) {
    readySfx = new Audio(READY_SFX_SRC);
    readySfx.preload = "auto";
    readySfx.volume = sfxVolume(READY_SFX_VOLUME);
    loadAudioElement(readySfx);
  }
  return readySfx;
}

function ensureNextRoundSfx() {
  if (nextRoundSfx) return nextRoundSfx;
  nextRoundSfx = new Audio(NEXT_ROUND_SFX_SRC);
  nextRoundSfx.preload = "auto";
  nextRoundSfx.volume = sfxVolume(NEXT_ROUND_SFX_VOLUME);
  return loadAudioElement(nextRoundSfx);
}

function ensureClockTickSfx(index) {
  if (!clockTickSfx[index]) {
    const audio = new Audio(CLOCK_TICK_SFX_SRCS[index]);
    audio.preload = "auto";
    audio.volume = sfxVolume(CLOCK_TICK_SFX_VOLUME);
    clockTickSfx[index] = loadAudioElement(audio);
  }
  return clockTickSfx[index];
}

function artifactSfxConfig(id) {
  return ARTIFACT_SFX[id] || null;
}

function artifactSfxVolume(id) {
  const config = artifactSfxConfig(id);
  return sfxVolume(config?.volume ?? DEFAULT_ARTIFACT_SFX_VOLUME);
}

function pentakillSfxVolume() {
  return sfxVolume(PENTAKILL_SFX.volume);
}

function ensureArtifactSfx(id) {
  const config = artifactSfxConfig(id);
  if (!config?.src) return null;
  if (!artifactSfx[id]) {
    const audio = new Audio(config.src);
    audio.preload = "auto";
    audio.volume = artifactSfxVolume(id);
    artifactSfx[id] = loadAudioElement(audio);
  }
  return artifactSfx[id];
}

function ensurePentakillSfx() {
  if (!PENTAKILL_SFX.src) return null;
  if (!pentakillSfx) {
    pentakillSfx = new Audio(PENTAKILL_SFX.src);
    pentakillSfx.preload = "auto";
    pentakillSfx.volume = pentakillSfxVolume();
    loadAudioElement(pentakillSfx);
  }
  return pentakillSfx;
}

function playOneShot(audio, startOffset = 0) {
  try {
    audio.__iosStartOffset = startOffset;
    audio.currentTime = Math.max(0, startOffset);
    audio.play().catch(() => {});
  } catch (error) {}
}

function playClonedOneShot(audio, volume, startOffset = 0) {
  try {
    const instance = audio.cloneNode(true);
    instance.volume = volume;
    activeOneShotSfxInstances.add(instance);
    const cleanup = () => activeOneShotSfxInstances.delete(instance);
    instance.addEventListener("ended", cleanup, { once: true });
    instance.addEventListener("error", cleanup, { once: true });
    instance.currentTime = Math.max(0, startOffset || 0);
    instance.__iosStartOffset = startOffset;
    instance.play().catch(cleanup);
  } catch (error) {}
}

function playSealPurchaseSfx() {
  playOneShot(ensureSealPurchaseSfx());
}

function playGuessSfx() {
  playOneShot(ensureButtonSfx("guess"), GUESS_SFX_START_OFFSET);
}

function playReadySfx() {
  playOneShot(ensureButtonSfx("ready"));
}

function playNextRoundSfx() {
  playOneShot(ensureNextRoundSfx());
}

function playClockTickSfx() {
  const tickIndex = nextClockTickIndex % CLOCK_TICK_SFX_SRCS.length;
  nextClockTickIndex = (nextClockTickIndex + 1) % CLOCK_TICK_SFX_SRCS.length;
  playClonedOneShot(ensureClockTickSfx(tickIndex), sfxVolume(CLOCK_TICK_SFX_VOLUME));
}

function playArtifactSfx(id) {
  const config = artifactSfxConfig(id);
  const audio = ensureArtifactSfx(id);
  if (!audio || !config) return;
  playClonedOneShot(audio, artifactSfxVolume(id), config.startOffset || 0);
}

function playPentakillSfx() {
  const audio = ensurePentakillSfx();
  if (!audio) return;
  playClonedOneShot(audio, pentakillSfxVolume(), PENTAKILL_SFX.startOffset || 0);
}

// ---------- moment sounds (GAME_SFX) ----------
const gameSfxCache = {};
let musicDuckTimer = null;

function ensureGameSfx(key) {
  const config = GAME_SFX[key];
  if (!config?.srcs?.length) return [];
  if (!gameSfxCache[key]) {
    gameSfxCache[key] = config.srcs.map((src) => {
      const audio = new Audio(src);
      audio.preload = "auto";
      return loadAudioElement(audio);
    });
  }
  return gameSfxCache[key];
}

function duckMusic(ms) {
  if (!soundtrackAudio || !(ms > 0)) return;
  soundtrackAudio.volume = musicVolume() * 0.35;
  clearTimeout(musicDuckTimer);
  musicDuckTimer = setTimeout(() => {
    if (soundtrackAudio) soundtrackAudio.volume = musicVolume();
  }, ms);
}

function playGameSfx(key) {
  const config = GAME_SFX[key];
  const pool = ensureGameSfx(key);
  if (!config || !pool.length || state.sound.muted) return;
  const audio = pool[Math.floor(Math.random() * pool.length)];
  if (!audio) return;
  try {
    const instance = audio.cloneNode(true);
    instance.volume = sfxVolume(config.volume ?? 0.4);
    if (config.pitch || config.rate) {
      instance.preservesPitch = false;
      instance.playbackRate = (config.rate || 1) * (1 + (Math.random() * 2 - 1) * (config.pitch || 0));
    }
    activeOneShotSfxInstances.add(instance);
    const cleanup = () => activeOneShotSfxInstances.delete(instance);
    instance.addEventListener("ended", cleanup, { once: true });
    instance.addEventListener("error", cleanup, { once: true });
    instance.play().catch(cleanup);
  } catch (error) {}
  if (config.duck) duckMusic(config.duck);
}

// a faint chalk tick when the pointer moves onto a menu button
function installMenuHoverSfx() {
  let lastHovered = null;
  document.addEventListener("pointerover", (event) => {
    if (event.pointerType && event.pointerType !== "mouse") return;
    const button = event.target?.closest?.(".menu-button, .run-slot-button");
    if (button === lastHovered) return;
    lastHovered = button;
    if (button && !button.disabled) playGameSfx("uiHover");
  });
}

function installGameButtonTickSfx() {
  if (gameButtonTickInstalled) return;
  gameButtonTickInstalled = true;
  installMenuHoverSfx();
  document.addEventListener(
    "click",
    (event) => {
      const button = event.target?.closest?.("button");
      if (!button || button.disabled) return;
      playClockTickSfx();
    },
    true
  );
}

function installSoundtrack() {
  ensureSoundtrack();
  ensureSealPurchaseSfx();
  ensureButtonSfx("guess");
  ensureButtonSfx("ready");
  ensureNextRoundSfx();
  CLOCK_TICK_SFX_SRCS.forEach((_, index) => ensureClockTickSfx(index));
  Object.keys(ARTIFACT_SFX).forEach((id) => ensureArtifactSfx(id));
  ensurePentakillSfx();
  Object.keys(GAME_SFX).forEach((key) => ensureGameSfx(key));
  installGameButtonTickSfx();
  document.addEventListener("pointerdown", unlockSoundtrack);
  document.addEventListener("keydown", unlockSoundtrack);
}

"use strict";

/* ---------- Records ----------
   Two stores, both shown on the Records screen (the Relic Wall, renderRecordsMenu in 09-rendering):
   - best values of one run: localStorage ARCADE_RECORDS_STORAGE_KEY (defaultArcadeRecords), raised by
     updateArcadeRecordsFromCurrentRun on every save and at game over;
   - lifetime numbers: localStorage RECORDS_LIFETIME_STORAGE_KEY (defaultLifetimeRecords): Guess quality,
     how often each SEAL / ARTIFACT / build was played, who killed you, SIN earned, pacts, runs.
   Lifetime counters the Collection already keeps (games beaten, DAMNED / demons / Yannis eliminated,
   CRITICALS in a row, most SIN held...) are read from there (loadCollectionProgress).

   Guess quality: every resolved round scores your final guess against the final TARGET:
   a CRITICAL scores 100, anything else 100 x GUESS_QUALITY_STEP ^ distance (at most 99).
   The shown number is the average, rounded down, so 100 means every guess was a CRITICAL. */

const RECORDS_LIFETIME_STORAGE_KEY = "dearthRecordsLifetimeV1";
const GUESS_QUALITY_STEP = 0.9; // each step away from the TARGET keeps 90% of the score
const GUESS_QUALITY_RECENT = 100; // "last 100 guesses"
const GUESS_QUALITY_MIN_RUN_GUESSES = 10; // a run needs this many guesses to set Best run Guess quality
const DEEPEST_DESCENT_ROUND_SPAN = 1000; // deepestDescent.value = depth x 1000 + round

function emptyRecord(extra = {}) {
  return { value: 0, ...extra };
}

function defaultRunStats() {
  return {
    overallDamage: 0,
    currentRoundDamage: 0,
    singleRoundDamage: 0,
    pentakills: 0,
    // the most DAMNED knocked out in one round
    roundKOs: 0,
    criticals: 0,
    guessSum: 0,
    guessRounds: 0,
    currentRoundSealDamage: {},
    maxSealRoundDamage: emptyRecord({ id: "", name: "" }),
    highestEliteLevel: emptyRecord({ id: "", name: "" }),
    sealPlays: {},
    artifactPlays: {},
    // SEALS that have been in a slot this run (each counts once per run for Most played SEAL)
    sealsSeen: {}
  };
}

function normalizeRunStats(stats) {
  const base = defaultRunStats();
  const source = stats && typeof stats === "object" ? stats : {};
  const count = (value) => Math.max(0, Math.floor(Number(value) || 0));
  const object = (value) => (value && typeof value === "object" && !Array.isArray(value) ? value : {});
  return {
    ...base,
    ...source,
    overallDamage: Math.max(0, Math.ceil(Number(source.overallDamage) || 0)),
    currentRoundDamage: Math.max(0, Math.ceil(Number(source.currentRoundDamage) || 0)),
    singleRoundDamage: Math.max(0, Math.ceil(Number(source.singleRoundDamage) || 0)),
    pentakills: count(source.pentakills),
    roundKOs: count(source.roundKOs),
    criticals: count(source.criticals),
    guessSum: count(source.guessSum),
    guessRounds: count(source.guessRounds),
    currentRoundSealDamage: object(source.currentRoundSealDamage),
    maxSealRoundDamage:
      source.maxSealRoundDamage && typeof source.maxSealRoundDamage === "object"
        ? { ...emptyRecord({ id: "", name: "" }), ...source.maxSealRoundDamage }
        : base.maxSealRoundDamage,
    highestEliteLevel:
      source.highestEliteLevel && typeof source.highestEliteLevel === "object"
        ? { ...emptyRecord({ id: "", name: "" }), ...source.highestEliteLevel }
        : base.highestEliteLevel,
    sealPlays: object(source.sealPlays),
    artifactPlays: object(source.artifactPlays),
    sealsSeen: object(source.sealsSeen)
  };
}

function ensureRunStats() {
  state.runStats = normalizeRunStats(state.runStats);
  return state.runStats;
}

/* ---------- best values of one run ---------- */
function defaultArcadeRecords() {
  return {
    // how far a run went (deepestDescentDepth) and the build you had when you got there
    deepestDescent: emptyRecord({ depth: 0, demons: 0, bosses: 0, round: 0, build: [], artifacts: [] }),
    mostEliminations: emptyRecord(),
    mostBossEliminations: emptyRecord(),
    mostOverallDamage: emptyRecord(),
    mostSingleRoundDamage: emptyRecord(),
    highestRoundReached: emptyRecord(),
    mostPentakills: emptyRecord(),
    mostRoundEliminations: emptyRecord(),
    mostCriticals: emptyRecord(),
    bestRunGuessQuality: emptyRecord({ guesses: 0 }),
    // lower is better (RECORD_LOWER_IS_BETTER): the round the 8th BOSS fell
    fastestWin: emptyRecord(),
    mostOverallSealDamage: emptyRecord({ id: "", name: "" }),
    mostRoundSealDamage: emptyRecord({ id: "", name: "" }),
    highestEliteLevel: emptyRecord({ id: "", name: "" })
  };
}

const RECORD_LOWER_IS_BETTER = new Set(["fastestWin"]);

function normalizeRecord(record, fallback) {
  const source = record && typeof record === "object" ? record : {};
  return { ...fallback, ...source, value: Math.max(0, Math.ceil(Number(source.value) || 0)) };
}

function normalizeArcadeRecords(records) {
  const defaults = defaultArcadeRecords();
  const source = records && typeof records === "object" ? records : {};
  return Object.fromEntries(Object.entries(defaults).map(([key, fallback]) => [key, normalizeRecord(source[key], fallback)]));
}

function loadArcadeRecords() {
  try {
    const raw = window.localStorage?.getItem(ARCADE_RECORDS_STORAGE_KEY);
    return normalizeArcadeRecords(raw ? JSON.parse(raw) : null);
  } catch (error) {
    return defaultArcadeRecords();
  }
}

function saveArcadeRecords(records) {
  try {
    window.localStorage?.setItem(ARCADE_RECORDS_STORAGE_KEY, JSON.stringify(normalizeArcadeRecords(records)));
  } catch (error) {}
}

function bestOverallSealDamageEntry() {
  const stats = state.sealStats && typeof state.sealStats === "object" ? state.sealStats : {};
  return Object.entries(stats).reduce(
    (best, [id, sealStats]) => {
      const value = Math.max(0, Math.ceil(Number(sealStats?.damage) || 0));
      if (value <= best.value) return best;
      return { value, id, name: ITEMS[id]?.name || id || "SEAL" };
    },
    emptyRecord({ id: "", name: "" })
  );
}

function recordBeats(key, value, current) {
  if (value <= 0) return false;
  if (RECORD_LOWER_IS_BETTER.has(key)) return current <= 0 || value < current;
  return value > current;
}

function updateRecordIfHigher(records, key, candidate) {
  const current = records[key] || emptyRecord();
  const value = Math.max(0, Math.ceil(Number(candidate?.value) || 0));
  if (!recordBeats(key, value, Math.max(0, Math.ceil(Number(current.value) || 0)))) return;
  records[key] = { ...current, ...candidate, value };
}

// the unique BOSSES beaten this run (Petros counts once both twins are down)
function uniqueBossesBeatenThisRun() {
  const kills = Array.isArray(state.collectionRun?.uniqueKills) ? state.collectionRun.uniqueKills : [];
  return UNIQUE_BOSS_KEYS.filter((key) => (key === "petros" ? kills.includes("petros") && kills.includes("pavlos") : kills.includes(key))).length;
}

// depth: the unique BOSSES beaten (0-8), then +1 for every Goetic demon slain after them
function deepestDescentDepth() {
  return uniqueBossesBeatenThisRun() + Math.max(0, Math.floor(Number(state.goeticBossKills) || 0));
}

// the SEALS (with ELITE level) and ARTIFACTS held right now
function currentBuildSnapshot() {
  const build = (state.player?.passives || [])
    .filter((item) => item?.id)
    .map((item) => ({ id: item.id, elite: isSelfStackingSeal(item) ? 0 : Math.max(0, (item.stack || 1) - 1) }));
  const artifacts = (state.player?.actives || []).filter((item) => item?.id).map((item) => item.id);
  return { build, artifacts };
}

function runGuessQuality(stats = ensureRunStats()) {
  return guessQualityValue(stats.guessSum, stats.guessRounds);
}

// what this run has reached for each record. Best run Guess quality only counts a finished run.
function currentRunRecordCandidates({ final = Boolean(state.gameOver) } = {}) {
  const stats = ensureRunStats();
  const depth = deepestDescentDepth();
  const round = Math.max(0, Math.floor(Number(state.round) || 0));
  const runQuality = runGuessQuality(stats);
  return {
    deepestDescent: {
      value: depth * DEEPEST_DESCENT_ROUND_SPAN + Math.min(round, DEEPEST_DESCENT_ROUND_SPAN - 1),
      depth,
      demons: Math.max(0, Math.floor(Number(state.goeticBossKills) || 0)),
      bosses: uniqueBossesBeatenThisRun(),
      round,
      ...currentBuildSnapshot()
    },
    mostEliminations: { value: state.eliminations || 0 },
    mostBossEliminations: { value: state.bossKills || 0 },
    mostOverallDamage: { value: stats.overallDamage || 0 },
    mostSingleRoundDamage: { value: stats.singleRoundDamage || 0 },
    highestRoundReached: { value: round },
    mostPentakills: { value: stats.pentakills || 0 },
    mostRoundEliminations: { value: stats.roundKOs || 0 },
    mostCriticals: { value: stats.criticals || 0 },
    bestRunGuessQuality:
      final && stats.guessRounds >= GUESS_QUALITY_MIN_RUN_GUESSES && runQuality !== null
        ? { value: runQuality, guesses: stats.guessRounds }
        : { value: 0 },
    fastestWin: { value: Math.max(0, Math.floor(Number(state.collectionRun?.beatenRound) || 0)) },
    mostOverallSealDamage: bestOverallSealDamageEntry(),
    mostRoundSealDamage: stats.maxSealRoundDamage || emptyRecord({ id: "", name: "" }),
    highestEliteLevel: stats.highestEliteLevel || emptyRecord({ id: "", name: "" })
  };
}

function updateArcadeRecordsFromCurrentRun(options = {}) {
  if (state.mode !== "arcade") return;
  const records = loadArcadeRecords();
  Object.entries(currentRunRecordCandidates(options)).forEach(([key, candidate]) => updateRecordIfHigher(records, key, candidate));
  saveArcadeRecords(records);
}

// the records as they stood when this run began (kept in the run's save), so the death card can say
// which ones this run broke
function snapshotRecordsAtRunStart() {
  state.recordsAtRunStart = loadArcadeRecords();
}

// short names for the death card, in the order they are listed there
const NEW_RECORD_LABELS = {
  deepestDescent: "Deepest descent",
  highestRoundReached: "Highest round",
  fastestWin: "Fastest win",
  bestRunGuessQuality: "Guess quality",
  mostCriticals: "Most CRITICALS",
  mostEliminations: "Most KOs",
  mostBossEliminations: "Most BOSS kills",
  mostOverallDamage: "Most damage dealt",
  mostSingleRoundDamage: "Most damage in one round",
  mostPentakills: "Most PENTAKILLS",
  mostRoundEliminations: "Most KOs in one round",
  mostOverallSealDamage: "Most damage by one SEAL",
  mostRoundSealDamage: "Most SEAL damage in one round",
  highestEliteLevel: "Highest ELITE level"
};

// a record's value as the player reads it
function recordValueDisplay(key, record) {
  const value = Math.max(0, Math.ceil(Number(record?.value) || 0));
  if (value <= 0) return "None";
  if (key === "deepestDescent") return deepestDescentText(record);
  if (key === "highestEliteLevel") return eliteLevelText(value);
  if (key === "fastestWin") return `Round ${formatNumber(value)}`;
  return formatNumber(value);
}

// "5 of 8 BOSSES" until the main game is beaten, then "Demon 12" (the 12th demon slain)
function deepestDescentText(record) {
  const depth = Math.max(0, Math.floor(Number(record?.depth) || 0));
  const demons = Math.max(0, Math.floor(Number(record?.demons) || 0));
  if (demons > 0) return `Demon ${formatNumber(demons)}`;
  return `${formatNumber(Math.min(depth, UNIQUE_BOSS_KEYS.length))} of ${UNIQUE_BOSS_KEYS.length} BOSSES`;
}

// records this run beat. A record that was still 0 before the run (a first run) does not count;
// Deepest descent counts only when the run went deeper, not when it lasted longer at the same depth.
function newRecordsThisRun() {
  if (state.mode !== "arcade") return [];
  const before = normalizeArcadeRecords(state.recordsAtRunStart || loadArcadeRecords());
  const reached = currentRunRecordCandidates();
  return Object.keys(NEW_RECORD_LABELS)
    .map((key) => {
      const previousRecord = before[key] || emptyRecord();
      const previous = Math.max(0, Math.ceil(Number(previousRecord.value) || 0));
      const value = Math.max(0, Math.ceil(Number(reached[key]?.value) || 0));
      if (previous <= 0 || !recordBeats(key, value, previous)) return null;
      if (key === "deepestDescent" && (reached[key].depth || 0) <= (previousRecord.depth || 0)) return null;
      return {
        key,
        label: NEW_RECORD_LABELS[key],
        value,
        previous,
        text: recordValueDisplay(key, reached[key]),
        previousText: recordValueDisplay(key, previousRecord),
        name: reached[key]?.name || ""
      };
    })
    .filter(Boolean);
}

function beginRunRoundStats() {
  const stats = ensureRunStats();
  stats.currentRoundDamage = 0;
  stats.currentRoundSealDamage = {};
}

function recordRunDamage(amount) {
  const damage = Math.max(0, Math.ceil(Number(amount) || 0));
  if (damage <= 0 || state.mode !== "arcade") return;
  const stats = ensureRunStats();
  stats.overallDamage += damage;
  stats.currentRoundDamage += damage;
  if (stats.currentRoundDamage > stats.singleRoundDamage) stats.singleRoundDamage = stats.currentRoundDamage;
}

function recordRunSealDamage(id, amount) {
  const damage = Math.max(0, Math.ceil(Number(amount) || 0));
  if (!id || damage <= 0 || state.mode !== "arcade") return;
  const stats = ensureRunStats();
  const next = (Number(stats.currentRoundSealDamage[id]) || 0) + damage;
  stats.currentRoundSealDamage[id] = next;
  if (next > (stats.maxSealRoundDamage?.value || 0)) {
    stats.maxSealRoundDamage = { value: next, id, name: ITEMS[id]?.name || id };
  }
}

// after every KO: the most KOs in one round
function recordRunRoundEliminations(count) {
  if (state.mode !== "arcade") return;
  const stats = ensureRunStats();
  stats.roundKOs = Math.max(stats.roundKOs || 0, Math.floor(Number(count) || 0));
}

function recordRunPentakill() {
  if (state.mode !== "arcade") return;
  ensureRunStats().pentakills += 1;
  collectionNotePentakill();
}

function recordPlayedSeal(id) {
  if (!id || state.mode !== "arcade") return;
  const stats = ensureRunStats();
  stats.sealPlays[id] = (Number(stats.sealPlays[id]) || 0) + 1;
}

function recordPlayedArtifact(id) {
  if (!id || state.mode !== "arcade") return;
  const stats = ensureRunStats();
  stats.artifactPlays[id] = (Number(stats.artifactPlays[id]) || 0) + 1;
  if (!lifetimeRecordsCount()) return;
  const lifetime = loadLifetimeRecords();
  lifetime.artifactUses[id] = (lifetime.artifactUses[id] || 0) + 1;
  saveLifetimeRecords();
}

function recordEliteLevelBought(id, stack) {
  if (!id || state.mode !== "arcade") return;
  const eliteLevel = Math.max(0, Math.floor(Number(stack) || 1) - 1);
  const stats = ensureRunStats();
  if (eliteLevel > (stats.highestEliteLevel?.value || 0)) {
    stats.highestEliteLevel = { value: eliteLevel, id, name: ITEMS[id]?.name || id };
  }
}

/* ---------- Guess quality ---------- */
function guessQualityScore(distance, critical) {
  if (critical) return 100;
  const steps = Math.max(0, Math.ceil(Number(distance) || 0));
  return Math.min(99, Math.round(100 * Math.pow(GUESS_QUALITY_STEP, steps)));
}

// the average score, rounded down (100 only when every guess was a CRITICAL); null with no guesses
function guessQualityValue(sum, rounds) {
  const count = Math.max(0, Math.floor(Number(rounds) || 0));
  if (count <= 0) return null;
  return Math.max(0, Math.min(100, Math.floor((Number(sum) || 0) / count)));
}

// once per resolved round (applyPenalties): your final guess against the final TARGET
function recordRoundGuess(distance, critical) {
  if (state.mode !== "arcade" || !Number.isFinite(Number(distance))) return;
  const score = guessQualityScore(distance, critical);
  const stats = ensureRunStats();
  stats.guessSum += score;
  stats.guessRounds += 1;
  if (critical) stats.criticals += 1;
  if (!lifetimeRecordsCount()) return;
  const lifetime = loadLifetimeRecords();
  lifetime.guessSum += score;
  lifetime.guessRounds += 1;
  lifetime.recentGuesses.push(score);
  if (lifetime.recentGuesses.length > GUESS_QUALITY_RECENT) lifetime.recentGuesses.splice(0, lifetime.recentGuesses.length - GUESS_QUALITY_RECENT);
  saveLifetimeRecords();
}

/* ---------- lifetime records ---------- */
let lifetimeRecordsCache = null;

function defaultLifetimeRecords() {
  return {
    version: 1,
    guessSum: 0,
    guessRounds: 0,
    recentGuesses: [],
    runs: 0,
    sinEarned: 0,
    pacts: 0,
    // runs each SEAL was in a slot (once per run), uses of each ARTIFACT
    sealRuns: {},
    artifactUses: {},
    // by build key (SEAL_BUILDS): { runs, depth } where depth is the deepest of those runs
    builds: {},
    // who was on the table when you fell: { key: { count, name, image } }
    deaths: {},
    // records broken in the last run that the Records screen has not shown yet
    unseen: []
  };
}

function loadLifetimeRecords() {
  if (lifetimeRecordsCache) return lifetimeRecordsCache;
  const records = defaultLifetimeRecords();
  try {
    const raw = window.localStorage?.getItem(RECORDS_LIFETIME_STORAGE_KEY);
    const saved = raw ? JSON.parse(raw) : null;
    if (saved && typeof saved === "object") {
      const count = (value) => Math.max(0, Math.floor(Number(value) || 0));
      ["guessSum", "guessRounds", "runs", "sinEarned", "pacts"].forEach((key) => { records[key] = count(saved[key]); });
      if (Array.isArray(saved.recentGuesses)) {
        records.recentGuesses = saved.recentGuesses.map((score) => Math.max(0, Math.min(100, count(score)))).slice(-GUESS_QUALITY_RECENT);
      }
      ["sealRuns", "artifactUses"].forEach((group) => {
        const source = saved[group] && typeof saved[group] === "object" ? saved[group] : {};
        Object.entries(source).forEach(([id, value]) => { if (ITEMS[id] && count(value) > 0) records[group][id] = count(value); });
      });
      if (saved.builds && typeof saved.builds === "object") {
        Object.entries(saved.builds).forEach(([key, value]) => {
          if (value && typeof value === "object" && count(value.runs) > 0) records.builds[key] = { runs: count(value.runs), depth: count(value.depth) };
        });
      }
      if (saved.deaths && typeof saved.deaths === "object") {
        Object.entries(saved.deaths).forEach(([key, value]) => {
          if (value && typeof value === "object" && count(value.count) > 0) {
            records.deaths[key] = { count: count(value.count), name: String(value.name || key), image: typeof value.image === "string" ? value.image : "" };
          }
        });
      }
      if (Array.isArray(saved.unseen)) records.unseen = saved.unseen.filter((key) => typeof key === "string");
    }
  } catch (error) {}
  lifetimeRecordsCache = records;
  return records;
}

function saveLifetimeRecords() {
  if (!lifetimeRecordsCache) return;
  try {
    window.localStorage?.setItem(RECORDS_LIFETIME_STORAGE_KEY, JSON.stringify(lifetimeRecordsCache));
  } catch (error) {}
}

// same rule as the Collection: real arcade runs only (no PvP, no story tutorial, no infinite SIN)
function lifetimeRecordsCount() {
  return typeof collectionCounts === "function" ? collectionCounts() : state.mode === "arcade";
}

// after every render of a run: a SEAL that is new in a slot this run counts one run for it
function recordsNoteSlots() {
  if (state.mode !== "arcade" || !lifetimeRecordsCount()) return;
  const stats = ensureRunStats();
  let changed = false;
  (state.player?.passives || []).forEach((item) => {
    const id = item?.id;
    if (!id || !ITEMS[id] || stats.sealsSeen[id]) return;
    stats.sealsSeen[id] = true;
    const lifetime = loadLifetimeRecords();
    lifetime.sealRuns[id] = (lifetime.sealRuns[id] || 0) + 1;
    changed = true;
  });
  if (changed) saveLifetimeRecords();
}

function recordSinEarned(amount) {
  const gained = Math.max(0, Math.floor(Number(amount) || 0));
  if (gained <= 0 || !lifetimeRecordsCount()) return;
  loadLifetimeRecords().sinEarned += gained;
  saveLifetimeRecords();
}

function recordPactSigned() {
  if (!lifetimeRecordsCount()) return;
  loadLifetimeRecords().pacts += 1;
  saveLifetimeRecords();
}

// the build a run was played as: the build tag most SEALS in your slots share ("general" only when
// nothing else is there); a tie goes to the build with more ELITE levels, then to SEAL_BUILDS order
function runBuildKey(passives = state.player?.passives || []) {
  const counts = {};
  const elites = {};
  passives.forEach((item) => {
    if (!item?.id) return;
    const tags = typeof sealBuilds === "function" ? sealBuilds(item.id) : ["general"];
    tags.forEach((tag) => {
      counts[tag] = (counts[tag] || 0) + 1;
      elites[tag] = (elites[tag] || 0) + Math.max(0, (item.stack || 1) - 1);
    });
  });
  const order = (typeof SEAL_BUILDS !== "undefined" ? SEAL_BUILDS : []).map((build) => build.key);
  const candidates = Object.keys(counts).filter((key) => key !== "general");
  if (!candidates.length) return counts.general ? "general" : "";
  candidates.sort((a, b) => counts[b] - counts[a] || elites[b] - elites[a] || order.indexOf(a) - order.indexOf(b));
  return candidates[0];
}

// who was on the table when you fell: the newest BOSS still standing, or the DAMNED
function runNemesis() {
  const bosses = (state.bots || []).filter((bot) => bot?.isBoss && !bot.eliminated && bot.hp > 0);
  const boss = bosses.sort((a, b) => (b.id || 0) - (a.id || 0))[0];
  if (!boss) return { key: "damned", name: "The DAMNED", image: "" };
  const key = boss.shadowOf ? "you" : boss.uniqueKey || boss.goeticKey || boss.archangelKey || boss.name || "boss";
  return { key, name: boss.name || "A BOSS", image: typeof boss.image === "string" ? boss.image : "" };
}

// at game over, after the run's records are written
function recordRunEnded() {
  if (state.mode !== "arcade") return;
  const broken = newRecordsThisRun().map((record) => record.key);
  if (!lifetimeRecordsCount()) return;
  const lifetime = loadLifetimeRecords();
  lifetime.runs += 1;
  const depth = deepestDescentDepth();
  const build = runBuildKey();
  if (build) {
    const entry = lifetime.builds[build] || { runs: 0, depth: 0 };
    entry.runs += 1;
    entry.depth = Math.max(entry.depth || 0, depth);
    lifetime.builds[build] = entry;
  }
  const nemesis = runNemesis();
  const death = lifetime.deaths[nemesis.key] || { count: 0, name: nemesis.name, image: nemesis.image };
  death.count += 1;
  death.name = nemesis.name;
  if (nemesis.image) death.image = nemesis.image;
  lifetime.deaths[nemesis.key] = death;
  lifetime.unseen = broken;
  saveLifetimeRecords();
}

// the Records screen was left: its NEW marks are seen
function recordsMarkSeen() {
  const lifetime = loadLifetimeRecords();
  if (!lifetime.unseen.length) return;
  lifetime.unseen = [];
  saveLifetimeRecords();
}

// the entry with the most of something ({ id: count }), or null
function topEntry(counts) {
  return Object.entries(counts || {}).reduce((best, [key, value]) => (value > (best?.value || 0) ? { key, value } : best), null);
}
function randomInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

function randomFrom(values) {
  return values[randomInt(0, values.length - 1)];
}

function pvpRollModifier(currentModifier = null) {
  let choices = PVP_MODIFIERS.slice();
  if (Number.isFinite(currentModifier)) {
    choices =
      currentModifier >= 1
        ? choices.filter((modifier) => modifier < 1)
        : choices.filter((modifier) => modifier > currentModifier);
  }
  if (!choices.length) choices = PVP_MODIFIERS.slice();
  return randomFrom(choices);
}

function shuffled(values) {
  const result = values.slice();
  for (let index = result.length - 1; index > 0; index -= 1) {
    const swapIndex = randomInt(0, index);
    [result[index], result[swapIndex]] = [result[swapIndex], result[index]];
  }
  return result;
}

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function average(values) {
  if (!values.length) return 0;
  return values.reduce((sum, value) => sum + value, 0) / values.length;
}

function nearestMultiple(value, divisor) {
  const number = Number(value);
  const step = Math.max(1, Math.ceil(divisor));
  if (!Number.isFinite(number)) return 0;
  return Math.ceil(Math.round(number / step) * step);
}

function nearestMultipleFromDivisors(value, divisors) {
  const number = Number(value);
  if (!Number.isFinite(number)) return { value: 0, divisor: 1 };
  const forceDifferent = divisors.some((divisor) => {
    const step = Math.max(1, Math.ceil(divisor));
    return number % step === 0;
  });
  return divisors
    .flatMap((divisor) => {
      const step = Math.max(1, Math.ceil(divisor));
      const lower = Math.floor(number / step) * step;
      const upper = Math.ceil(number / step) * step;
      const values = new Set([lower, upper]);
      if (forceDifferent && values.has(number)) {
        values.delete(number);
        values.add(lower - step);
        values.add(upper + step);
      }
      return [...values].map((snapped) => ({ divisor, value: Math.ceil(snapped), distance: Math.abs(snapped - number) }));
    })
    .sort((left, right) => left.distance - right.distance || left.value - right.value || left.divisor - right.divisor)[0];
}

function hasPassive(id) {
  return passiveStack(id) > 0;
}

function passiveEntry(id) {
  return state.player.passives.find((item) => item.id === id) || null;
}

function directPassiveStack(id) {
  return passiveEntry(id)?.stack || 0;
}

function sealSlotCost(idOrItem) {
  const id = typeof idOrItem === "string" ? idOrItem : idOrItem?.id;
  if (TRINITY_SEAL_IDS.has(id)) {
    // the first Trinity SEAL owned holds the slot; the others (owned or offered) merge into it
    const host = trinityHostSeal();
    if (!host) return 1;
    return idOrItem === host ? 1 : 0;
  }
  return SATAN_SEAL_IDS.has(id) ? 2 : 1;
}

// ---------- Trinity SEALS: one shared slot ----------
function isTrinitySeal(idOrItem) {
  const id = typeof idOrItem === "string" ? idOrItem : idOrItem?.id;
  return TRINITY_SEAL_IDS.has(id);
}

function ownedTrinitySeals() {
  return (state.player.passives || []).filter((item) => item && isTrinitySeal(item) && !REMOVED_PASSIVE_IDS.has(item.id));
}

// the Trinity SEAL that holds the shared slot (the first one in slot order)
function trinityHostSeal() {
  return ownedTrinitySeals()[0] || null;
}

function trinitySetKey(ids) {
  const owned = new Set(ids);
  return TRINITY_SEAL_ORDER.filter((id) => owned.has(id)).join("+");
}

// art for the shared slot: one ring per Trinity SEAL owned
function trinitySlotArtPath(ids = ownedTrinitySeals().map((item) => item.id)) {
  const file = TRINITY_SEAL_ART[trinitySetKey(ids)];
  return file ? `assets/seals/${file}` : "";
}

// two or three Trinity SEALS together are called the Seal of God
const TRINITY_COMBINED_NAME = "Seal of God";

function trinitySlotName(pieces = ownedTrinitySeals()) {
  return pieces.length > 1 ? TRINITY_COMBINED_NAME : pieces[0]?.name || TRINITY_COMBINED_NAME;
}

function missingTrinitySealIds() {
  const owned = new Set(ownedTrinitySeals().map((item) => item.id));
  return TRINITY_SEAL_ORDER.filter((id) => !owned.has(id));
}

// the active (not suppressed) entry of a Trinity SEAL, or null
function trinityEntry(id) {
  return orderedPassiveEffectEntries(id)[0] || null;
}

function ownedSealSlotCount() {
  return state.player.passives
    .filter((item) => item && !REMOVED_PASSIVE_IDS.has(item.id))
    .reduce((sum, item) => sum + sealSlotCost(item), 0);
}

function hasSealSlotRoomFor(item) {
  return ownedSealSlotCount() + sealSlotCost(item) <= passiveLimit();
}

function pruneRemovedPassives() {
  const before = state.player.passives.length;
  state.player.passives = state.player.passives.filter((item) => item && !REMOVED_PASSIVE_IDS.has(item.id));
  if (state.player.passives.length !== before) refreshMimicTarget();
}

function suppressingBossForSeal(id) {
  if (!id || !state.bots?.length) return null;
  const sealName = ITEMS[id]?.name || "";
  return (
    state.bots.find(
      (bot) =>
        bot.isBoss &&
        bot.hp > 0 &&
        !bot.eliminated &&
        (bot.goeticPassiveId === id || (sealName && bot.goeticSealName === sealName))
    ) || null
  );
}

function kalhaSuppressionForSeal(id) {
  const round = state.roundState;
  if (!id || !round || !round.kalhaSuppressedPassiveIds?.has(id)) return null;
  return state.bots.find((bot) => bot.id === round.kalhaSuppressedById && bot.hp > 0 && !bot.eliminated) || {
    name: "Kalha"
  };
}

function isSealSuppressed(id) {
  return Boolean(suppressingBossForSeal(id) || kalhaSuppressionForSeal(id));
}

function sealSuppressionNotice(id) {
  const goeticBoss = suppressingBossForSeal(id);
  if (goeticBoss) return `Disabled while ${goeticBoss.name} is alive.\n`;
  const kalhaBoss = kalhaSuppressionForSeal(id);
  if (kalhaBoss) return `Disabled by ${kalhaBoss.name} this round.\n`;
  return "";
}

function mimicEntry() {
  return passiveEntry("p28");
}

function availableMimicTargets() {
  return state.player.passives.filter(
    (item) => item && item.id !== "p28" && !REMOVED_PASSIVE_IDS.has(item.id) && !isNonUpgradableSeal(item.id)
  );
}

function chooseMimicTarget(mimic = mimicEntry()) {
  if (!mimic) return null;
  const choices = availableMimicTargets();
  if (!choices.length) {
    delete mimic.copiedPassiveId;
    return null;
  }
  const target = randomFrom(choices);
  mimic.copiedPassiveId = target.id;
  return target;
}

function mimicTargetEntry() {
  const mimic = mimicEntry();
  if (!mimic) return null;
  const target = mimic.copiedPassiveId
    ? state.player.passives.find(
        (item) =>
          item &&
          item.id === mimic.copiedPassiveId &&
          item.id !== "p28" &&
          !REMOVED_PASSIVE_IDS.has(item.id) &&
          !isNonUpgradableSeal(item.id)
      )
    : null;
  return target || chooseMimicTarget(mimic);
}

function refreshMimicTarget() {
  const mimic = mimicEntry();
  if (!mimic) return null;
  return mimicTargetEntry();
}

function mimicContributionFor(id) {
  if (id === "p28") return 0;
  if (isSealSuppressed("p28") || isSealSuppressed(id)) return 0;
  const mimic = mimicEntry();
  const target = mimicTargetEntry();
  return target?.id === id ? mimic?.stack || 0 : 0;
}

// ---------- Seal of Amy: a random Goetic SEAL each round ----------
// At the start of every round Amy rolls one Player (Goetic) SEAL and acts as it until the round ends, as an ELITE
// SEAL two levels stronger per Amy ELITE level (Amy x1 copies at stack 2, ELITE Amy at stack 4, ELITE +2 at stack 6).
// The roll is kept on Amy's item (amyCopiedId / amyCopiedRound) so a saved run keeps it.
function amyItem() {
  return passiveEntry(AMY_SEAL_ID);
}

function amyCopiedStack(item = amyItem()) {
  return 2 * Math.max(1, Math.ceil(item?.stack || 1));
}

function amyCopyPool() {
  return GOETIC_BOSS_PASSIVE_IDS.filter((id) => id !== AMY_SEAL_ID && ITEMS[id] && !isSealSuppressed(id));
}

// the Goetic SEAL Amy copies this round, or null
function amyCopyThisRound(item = amyItem()) {
  if (!item || item.amyCopiedRound !== state.round) return null;
  const id = item.amyCopiedId;
  return id && ITEMS[id] && !REMOVED_PASSIVE_IDS.has(id) && id !== AMY_SEAL_ID ? id : null;
}

function rollAmyCopy() {
  const item = amyItem();
  if (!item) return null;
  const pool = amyCopyPool();
  item.amyCopiedId = pool.length ? randomFrom(pool) : null;
  item.amyCopiedRound = state.round;
  if (item.amyCopiedId && state.roundState && !isSealSuppressed(AMY_SEAL_ID)) {
    addRoundEvent(`${ITEMS[AMY_SEAL_ID].name} took the power of ${passiveDisplayName({ ...ITEMS[item.amyCopiedId], stack: amyCopiedStack(item) })} for this round.`);
  }
  return item.amyCopiedId;
}

// the stacks Amy adds to a SEAL this round (0 when it is not the copied one, or either one is suppressed)
function amyContributionFor(id) {
  if (id === AMY_SEAL_ID || isSealSuppressed(AMY_SEAL_ID) || isSealSuppressed(id)) return 0;
  const item = amyItem();
  return item && amyCopyThisRound(item) === id ? amyCopiedStack(item) : 0;
}

function passiveStack(id) {
  if (REMOVED_PASSIVE_IDS.has(id)) return 0;
  if (isSealSuppressed(id)) return 0;
  return directPassiveStack(id) + mimicContributionFor(id) + amyContributionFor(id);
}

// ---------- POISON (Poison SEALS, the Pentacles of Mars) ----------
// A DAMNED's POISON stacks live on bot.poisonCounters. They stay until it dies (the 7th Pentacle removes one at a
// time) and deal poisonDamagePerStack() damage each at the end of every round, even after the SEALS are sold.
function botPoison(bot) {
  return Math.max(0, Math.ceil(bot?.poisonCounters || 0));
}

function canPoisonBot(bot) {
  return Boolean(bot && !bot.immortal && bot.hp > 0 && !bot.eliminated);
}

// give a DAMNED POISON (the caller marks its SEAL as triggered, once per action). sealId is the SEAL
// that gave it: bot.poisonSources counts each SEAL's stacks, so the damage POISON deals can be credited
// to the SEAL that gave it (shown with Shift on the SEAL: "POISON damage dealt").
function addBotPoison(bot, amount, sealId = null) {
  const added = Math.max(0, Math.ceil(amount || 0));
  if (!added || !canPoisonBot(bot)) return 0;
  bot.poisonCounters = botPoison(bot) + added;
  const creditId = poisonCreditSealId(sealId);
  if (creditId) {
    if (!bot.poisonSources || typeof bot.poisonSources !== "object") bot.poisonSources = {};
    bot.poisonSources[creditId] = (bot.poisonSources[creditId] || 0) + added;
  }
  return added;
}

// Seal of Amy copying a Poison SEAL you do not own: its POISON is Amy's work (like every other SEAL stat)
function poisonCreditSealId(sealId) {
  if (!sealId) return null;
  if (typeof amyContributionFor === "function" && !directPassiveStack(sealId) && amyContributionFor(sealId)) return AMY_SEAL_ID;
  return sealId;
}

// take POISON away (7th Pentacle of Mars), from the SEAL that gave the most first
function removeBotPoison(bot, amount) {
  let left = Math.min(botPoison(bot), Math.max(0, Math.ceil(amount || 0)));
  bot.poisonCounters = botPoison(bot) - left;
  const sources = bot.poisonSources && typeof bot.poisonSources === "object" ? bot.poisonSources : {};
  // POISON nobody is credited for (given before tracking existed) goes first
  const tracked = Object.values(sources).reduce((sum, count) => sum + count, 0);
  left -= Math.max(0, Math.min(left, bot.poisonCounters + left - tracked));
  while (left > 0) {
    const top = Object.keys(sources).sort((a, b) => sources[b] - sources[a])[0];
    if (!top) break;
    sources[top] -= 1;
    if (sources[top] <= 0) delete sources[top];
    left -= 1;
  }
}

// how many of a DAMNED's POISON stacks each SEAL gave: [[sealId, stacks], ...] (never more than it has)
function botPoisonShares(bot) {
  const sources = bot?.poisonSources && typeof bot.poisonSources === "object" ? bot.poisonSources : {};
  const stacks = botPoison(bot);
  const entries = Object.entries(sources).filter(([, count]) => count > 0);
  const tracked = entries.reduce((sum, [, count]) => sum + count, 0);
  if (tracked <= stacks) return entries;
  return entries.map(([id, count]) => [id, (count * stacks) / tracked]);
}

// split the damage a DAMNED's POISON dealt between the SEALS that gave it, by their share of its stacks
function creditPoisonDamage(bot, dealt, stacks) {
  const total = Math.max(0, Math.ceil(dealt || 0));
  if (!total || !stacks) return;
  const parts = botPoisonShares(bot).map(([id, count]) => {
    const exact = (total * count) / stacks;
    return { id, value: Math.floor(exact), rest: exact - Math.floor(exact) };
  });
  // hand out what rounding left over (only up to the tracked share), biggest remainder first
  const trackedExact = parts.reduce((sum, part) => sum + part.value + part.rest, 0);
  let leftover = Math.round(trackedExact) - parts.reduce((sum, part) => sum + part.value, 0);
  [...parts].sort((a, b) => b.rest - a.rest).forEach((part) => {
    if (leftover <= 0) return;
    part.value += 1;
    leftover -= 1;
  });
  parts.forEach((part) => {
    if (part.value <= 0) return;
    const stats = sealStatsFor(part.id);
    if (stats) stats.poisonDamage = (stats.poisonDamage || 0) + part.value;
  });
}

function poisonSealEntry(id) {
  return orderedPassiveEffectEntries(id)[0] || null;
}

// ELITE 4th (+2), 5th (+1) and 6th (+1) Pentacles of Mars raise every POISON's damage, per ELITE level
function poisonDamageBonusEntries() {
  return [
    ["p143", 2],
    ["p144", 1],
    ["p145", 1]
  ]
    .map(([id, perLevel]) => {
      const entry = poisonSealEntry(id);
      const levels = entry ? passiveEntryEliteLevels(entry) : 0;
      return { entry, bonus: levels * perLevel };
    })
    .filter((part) => part.entry && part.bonus > 0);
}

function poisonDamagePerStack() {
  return POISON_DAMAGE_PER_STACK + poisonDamageBonusEntries().reduce((sum, part) => sum + part.bonus, 0);
}

// 1st Pentacle of Mars: max SOUL per POISON (80, ELITE -25% each level, never below 1)
function marsHealthPerPoison(entry) {
  return Math.max(1, Math.round(80 * Math.pow(0.75, entry ? passiveEntryEliteLevels(entry) : 0)));
}

// 5th Pentacle of Mars: a DAMNED that gains BOUNTY gets 1 POISON
function applyBountyPoison(bot) {
  const entry = poisonSealEntry("p144");
  if (!entry || !state.roundState) return;
  if (!addBotPoison(bot, 1, entry.id)) return;
  markPassiveEntryTriggered(entry);
  addRoundEvent(`${ITEMS.p144.name} gave ${bot.name} 1 POISON for its BOUNTY.`);
}

// ---------- Artifact SEALS (Pentacles of the Moon) ----------
// the active entry of the Artifact SEAL that strengthens this ARTIFACT, or null
function artifactSealEntry(artifactId) {
  const sealId = ARTIFACT_SEAL_BY_ARTIFACT[artifactId];
  return sealId ? orderedPassiveEffectEntries(sealId)[0] || null : null;
}

function artifactSealLevels(artifactId) {
  const entry = artifactSealEntry(artifactId);
  return entry ? passiveEntryEliteLevels(entry) : 0;
}

function eliteLevels(idOrItem) {
  const stack = typeof idOrItem === "string" ? passiveStack(idOrItem) : idOrItem?.stack || 0;
  return Math.max(0, stack - 1);
}

function passivePower(idOrItem, eliteStep = 0.2) {
  const stack = typeof idOrItem === "string" ? passiveStack(idOrItem) : idOrItem?.stack || 0;
  if (!stack) return 0;
  return 1 + eliteLevels(idOrItem) * eliteStep;
}

function scaledPassiveValue(id, baseValue, eliteStep = 0.2) {
  const power = passivePower(id, eliteStep);
  return power ? Math.ceil(baseValue * power) : 0;
}

function scaledPassiveValueForItem(item, baseValue, eliteStep = 0.2) {
  const power = passivePower(item, eliteStep);
  return power ? Math.ceil(baseValue * power) : 0;
}

function flatDamagePower(idOrItem) {
  const stack = simpleStackCount(idOrItem);
  return stack ? Math.pow(1.5, Math.max(0, stack - 1)) : 0;
}

function flatDamageValue(idOrItem, baseValue) {
  const stack = simpleStackCount(idOrItem);
  if (!stack) return 0;
  let value = Math.max(0, Math.ceil(baseValue || 0));
  for (let level = 1; level < stack; level += 1) {
    value = Math.ceil(value * 1.5);
  }
  return value;
}

function passiveEntryFlatDamage(entry, baseValue) {
  return flatDamageValue(entry, baseValue);
}

function passiveEntryEliteLevels(entry) {
  return Math.max(0, (entry?.stack || 1) - 1);
}

function doubledStackPower(idOrItem) {
  const stack = simpleStackCount(idOrItem);
  return stack ? Math.pow(2, Math.max(0, stack - 1)) : 0;
}

function doubledStackValue(idOrItem, baseValue) {
  const power = doubledStackPower(idOrItem);
  return power ? Math.ceil((baseValue || 0) * power) : 0;
}

function rollScaledPassiveCount(id, baseCount = 1) {
  const power = passivePower(id);
  if (!power) return 0;
  const raw = baseCount * power;
  const guaranteed = Math.floor(raw);
  const chance = raw - guaranteed;
  return guaranteed + (Math.random() < chance ? 1 : 0);
}

function botSin(bot) {
  const reward = Math.ceil(bot?.reward || 0);
  return Number.isFinite(reward) ? Math.max(0, reward) : 0;
}

function scalingBonus(progress, earlyStep, lateStep, endlessStep = lateStep) {
  const count = Math.max(0, Math.ceil(progress || 0));
  const early = Math.min(count, SCALING_BREAKPOINT_BOSSES);
  const mid = Math.min(
    Math.max(0, count - SCALING_BREAKPOINT_BOSSES),
    ENDLESS_SCALING_BREAKPOINT_BOSSES - SCALING_BREAKPOINT_BOSSES
  );
  const endless = Math.max(0, count - ENDLESS_SCALING_BREAKPOINT_BOSSES);
  return early * earlyStep + mid * lateStep + endless * endlessStep;
}

function artifactScaleFactor() {
  return 1;
}

function artifactValue(baseValue) {
  const sign = Math.sign(baseValue || 0);
  const scaled = Math.floor(Math.abs(baseValue || 0) * artifactScaleFactor());
  return sign * scaled;
}

function artifactPercentValue(basePercent) {
  return clamp(artifactValue(basePercent), 0, 100);
}

function artifactPercent(basePercent) {
  return artifactPercentValue(basePercent) / 100;
}

function artifactCount(baseValue) {
  return Math.max(1, artifactValue(baseValue));
}

function artifactMultiplier(baseValue) {
  return Math.max(0, Math.floor((baseValue || 0) * artifactScaleFactor() * 10) / 10);
}

function formatArtifactMultiplier(value) {
  return Number.isInteger(value) ? value.toFixed(0) : value.toFixed(1);
}

function botBossBounty(bot) {
  // Jesus and Satan: their BOSS BOUNTY is infinite (only shown, botSinDisplay), so nothing can change it
  if (!bot?.isBoss || bot?.immortal) return 0;
  const factor = Number.isFinite(bot.bossBountyFactor) ? bot.bossBountyFactor : 1;
  const bonus = Math.max(0, Math.ceil(bot.bossBountyBonus || 0));
  // Seal of Zilon already turned part of it into BOUNTY (bossBountyConverted)
  const converted = Math.max(0, Math.ceil(bot.bossBountyConverted || 0));
  return Math.max(0, Math.ceil((20 + state.bossKills) * factor) + bonus - converted);
}

// Jesus and Satan included: their regular BOUNTY starts at 0 and SEALS can change it like anyone's
function botRegularBounty(bot) {
  return botSin(bot);
}

function botRegularBountyPayout(bot, markTriggers = false) {
  return botRegularBountyPayoutDetails(bot, markTriggers).payout;
}

function botRegularBountyPayoutDetails(bot, markTriggers = false) {
  if (!bot || bot.immortal) return { payout: 0, baseReward: 0, modifierEntries: [] };
  const baseReward = botRegularBounty(bot);
  let exactReward = baseReward;
  let roundedReward = baseReward;
  const modifierEntries = [];
  const applyMultiplier = (multiplier, source, triggerId) => {
    if (!Number.isFinite(multiplier) || multiplier <= 1 || roundedReward <= 0) return;
    const before = roundedReward;
    exactReward *= multiplier;
    roundedReward = Math.ceil(exactReward);
    const extra = Math.max(0, roundedReward - before);
    if (extra <= 0) return;
    modifierEntries.push({ amount: extra, source });
    if (triggerId && markTriggers) markPassiveTriggered(triggerId);
  };

  if (hasPassive("p36")) {
    applyMultiplier(1.5 * passivePower("p36"), ITEMS.p36?.name || "Seal of Asmoday", "p36");
  }
  applyMultiplier(bountyOathMultiplier(), ITEMS.p24?.name || "Seal of Orobas", passiveStack("p24") ? "p24" : "");
  if (botHasLowSin(bot, 3) && passiveStack("p45")) {
    applyMultiplier(2 * passivePower("p45"), ITEMS.p45?.name || "Seal of Crocell", "p45");
  }
  if (bot.revealedByPassive && passiveStack("p64")) {
    for (let stack = 0; stack < revealMultiplicity(bot); stack += 1) {
      applyMultiplier(revealedBountyMultiplier("p64"), ITEMS.p64?.name || "Seal of Vine", "p64");
    }
  }
  if ((bot.memory?.length || 0) >= 8 && passiveStack("p67")) {
    applyMultiplier(memoryBountyMultiplier("p67"), ITEMS.p67?.name || "Seal of Caim", "p67");
  }

  return { payout: roundedReward, baseReward, modifierEntries };
}

function botHasLowSin(bot, limit = 3) {
  if (bot?.immortal) return false;
  return botSin(bot) <= limit;
}

function andromaliusBountyLimit(idOrItem) {
  return 2 + eliteLevels(idOrItem);
}

function wealthWeightBonus() {
  return 0;
}

function passiveShopDiscount() {
  return 0;
}

function sinPricePressureMultiplier() {
  const credits = Number.isFinite(state.player.credits) ? Math.max(0, state.player.credits) : 0;
  if (credits <= SIN_PRICE_PRESSURE_INTERVAL) return 1;
  return 2 ** Math.ceil((credits - SIN_PRICE_PRESSURE_INTERVAL) / SIN_PRICE_PRESSURE_INTERVAL);
}

function memoryEntryForBot(bot) {
  const round = state.roundState;
  const fallbackGuess = bot?.plannedGuess ?? bot?.anchor ?? 50;
  const ownGuess = round?.botEffectiveGuesses?.get(bot.id) ?? fallbackGuess;
  const tableAverage = Number.isFinite(round?.tableAverage) ? round.tableAverage : ownGuess;
  return {
    ownGuess,
    playerGuess: round?.playerEffectiveGuess ?? ownGuess,
    target: round?.target ?? state.previousTarget ?? ownGuess,
    targetModifier: round?.targetModifier ?? currentTargetModifier(),
    targetOffset: round?.targetOffset ?? 0,
    tableAverage,
    botAverage: tableAverage
  };
}

function bathinMemoryDamage(entry) {
  return passiveEntryFlatDamage(entry, 3);
}

function applyBathinMemoryDamage(bot, entries) {
  if (!state.roundState || !bot || bot.eliminated || !entries?.length) return;
  entries.forEach((entry) => {
    if (bot.eliminated) return;
    const damage = bathinMemoryDamage(entry);
    if (damage <= 0) return;
    markPassiveEntryTriggered(entry);
    queueEndOfRoundBotDamage(bot, damage, `Seal of Bathin dealt ${damage} damage to ${bot.name} for gaining MEMORY.`, "Seal of Bathin");
  });
}

function reduceBotMemoryRecord(bot, amount) {
  let remaining = Math.max(0, Math.ceil(amount));
  if (!bot || remaining <= 0) return;
  bot.lastMemoryDelta = Math.max(0, (bot.lastMemoryDelta || 0) - remaining);
  if (!Array.isArray(bot.memorySources)) return;
  for (let index = bot.memorySources.length - 1; index >= 0 && remaining > 0; index -= 1) {
    const source = bot.memorySources[index];
    const sourceAmount = Math.max(0, Math.ceil(source?.amount || 0));
    const removed = Math.min(sourceAmount, remaining);
    source.amount = sourceAmount - removed;
    remaining -= removed;
  }
  bot.memorySources = bot.memorySources.filter((source) => Math.max(0, Math.ceil(source?.amount || 0)) > 0);
}

function applyMemoryToBountyMirror(bot, amount, options = {}) {
  const memoriesAdded = Math.max(0, Math.ceil(amount));
  if (options.triggerMemoryBountyMirror === false || !state.roundState || !bot || bot.eliminated || memoriesAdded <= 0) return;
  const entry = orderedPassiveEffectEntries("p125")[0];
  if (!entry) return;
  const converted = Math.min(memoriesAdded, Math.floor(memoriesAdded / 2));
  if (converted <= 0) return;
  // ELITE: every conversion also gives +1 free BOUNTY per level (it is not taken from MEMORY)
  const free = passiveEntryEliteLevels(entry);
  bot.memory.splice(Math.max(0, bot.memory.length - converted), converted);
  reduceBotMemoryRecord(bot, converted);
  recordBotMemoryLoss(bot, converted, ITEMS.p125.name);
  markPassiveEntryTriggered(entry);
  changeBotSin(
    bot,
    converted + free,
    `${ITEMS.p125.name} converted ${converted} MEMORY from ${bot.name} into ${converted + free} BOUNTY.`,
    {
      source: ITEMS.p125.name,
      triggerMemoryBountyMirror: false
    }
  );
}

function applyBountyToMemoryMirror(bot, amount, options = {}) {
  const bountyGained = Math.max(0, Math.ceil(amount));
  if (options.triggerMemoryBountyMirror === false || !state.roundState || !bot || bot.eliminated || bountyGained <= 0) return;
  const entry = orderedPassiveEffectEntries("p125")[0];
  if (!entry) return;
  const converted = Math.min(bountyGained, Math.floor(bountyGained / 2));
  if (converted <= 0) return;
  markPassiveEntryTriggered(entry);
  const result = changeBotSin(bot, -converted, "", {
    source: ITEMS.p125.name,
    triggerMemoryBountyMirror: false,
    triggerLossDamage: false
  });
  if (result.lost <= 0) return;
  // ELITE: every conversion also gives +1 free MEMORY per level (it is not taken from BOUNTY)
  const free = passiveEntryEliteLevels(entry);
  const added = addBotMemory(bot, result.lost + free, "", {
    source: ITEMS.p125.name,
    triggerMemoryBountyMirror: false
  });
  addRoundEvent(`${ITEMS.p125.name} converted ${result.lost} BOUNTY from ${bot.name} into ${added} MEMORY.`);
}

// MEMORY can never exceed the rounds actually finished (what a BOSS remembers). The round in play only counts
// once it is recorded at the end of the round (rememberRound); MEMORY gained before that is excess.
function memoryRoundLimit() {
  const finished = Math.max(0, Math.ceil(state.round || 0) - 1);
  return finished + (state.roundState?.memoryRecorded ? 1 : 0);
}

function botMemoryLimit(bot) {
  return memoryRoundLimit();
}

function trimBotMemoryToLimit(bot) {
  if (!bot?.memory) return 0;
  const limit = botMemoryLimit(bot);
  const before = bot.memory.length;
  bot.memory = limit > 0 ? bot.memory.slice(-limit) : [];
  return Math.max(0, before - bot.memory.length);
}

function sitriExcessMemoryDamage(entry) {
  return doubledStackValue(entry, 4);
}

// Seal of Threon: MEMORY beyond the limit is kept on the DAMNED as visible overflow (bot.memoryOverflow, shown
// past the limit in its MEMORY line). At end of round the overflow is removed and each point deals damage; excess gained
// when the round is recorded (after that) carries over to the next round.
function applyExcessMemoryDamage(bot, excessMemory) {
  const excess = Math.max(0, Math.ceil(excessMemory));
  if (!state.roundState || !bot || bot.eliminated || excess <= 0) return;
  const entries = orderedPassiveEffectEntries("p127");
  if (!entries.length) return;
  bot.memoryOverflow = Math.max(0, Math.ceil(bot.memoryOverflow || 0)) + excess;
  entries.forEach((entry) => markPassiveEntryTriggered(entry));
}

function applyMemoryOverflowDamage() {
  const entries = orderedPassiveEffectEntries("p127");
  state.bots.forEach((bot) => {
    const overflow = Math.max(0, Math.ceil(bot?.memoryOverflow || 0));
    if (!bot || overflow <= 0) return;
    bot.memoryOverflow = 0;
    if (bot.eliminated || bot.hp <= 0) return;
    entries.forEach((entry) => {
      if (bot.eliminated) return;
      const damage = overflow * sitriExcessMemoryDamage(entry);
      if (damage <= 0) return;
      markPassiveEntryTriggered(entry);
      damageBot(
        bot,
        damage,
        `${ITEMS.p127.name} removed ${overflow} excess MEMORY from ${bot.name} and dealt ${damage} damage.`,
        ITEMS.p127.name
      );
    });
  });
}

// Seal of Zilon: share of a BOSS BOUNTY that turns into regular BOUNTY (the rest is spread among the DAMNED)
function zilonConversionPercent(idOrItem) {
  return 40 + 5 * eliteLevels(idOrItem);
}

function addBotMemory(bot, count, reason = "", options = {}) {
  if (!bot || bot.eliminated || count <= 0) return 0;
  const baseRequested = Math.ceil(count);
  const bathinEntries = options.triggerBathinMemory !== false ? orderedPassiveEffectEntries("p15") : [];
  const bonusRequested = bathinEntries.length;
  const requested = baseRequested + bonusRequested;
  trimBotMemoryToLimit(bot);
  const beforeMemory = bot.memory?.length || 0;
  const allowed = Math.max(0, botMemoryLimit(bot) - beforeMemory);
  const added = Math.min(requested, allowed);
  const excess = Math.max(0, requested - added);
  const entry = options.entry || memoryEntryForBot(bot);
  for (let index = 0; index < added; index += 1) {
    bot.memory.push({ ...entry });
  }
  const actualIncrease = Math.max(0, (bot.memory?.length || 0) - beforeMemory);
  const baseIncrease = Math.min(baseRequested, actualIncrease);
  const bathinIncrease = Math.max(0, actualIncrease - baseIncrease);
  recordBotMemorySource(bot, baseIncrease, options.source || sourceLabelFromReason(reason, "Memory"));
  recordBotMemorySource(bot, bathinIncrease, ITEMS.p15?.name || "Seal of Bathin");
  applyMemoryToBountyMirror(bot, actualIncrease, options);
  applyExcessMemoryDamage(bot, excess);
  applyBathinMemoryDamage(bot, bathinEntries);
  if (reason) state.roundState?.roundEvents.push(reason);
  applySelfStackingMemoryOverTen(bot, beforeMemory, bot.memory?.length || 0);
  checkBalamMemoryBountyEliminations();
  return actualIncrease;
}

function initialMemoryEntries(count) {
  const targetModifier = state.roundState?.targetModifier ?? currentTargetModifier();
  const targetOffset = state.roundState?.targetOffset ?? 0;
  const target = state.previousTarget ?? Math.ceil(50 * targetModifier + targetOffset);
  const tableAverage = targetModifier ? (target - targetOffset) / targetModifier : 50;
  return Array.from({ length: count }, () => ({
    ownGuess: 50,
    playerGuess: 50,
    target,
    targetModifier,
    targetOffset,
    tableAverage,
    botAverage: tableAverage
  }));
}

function seedNewBotMemoryFromVassago(bot) {
  if (!bot || bot.isBoss) return;
  if (bot.memory?.length) return;
  const entries = orderedPassiveEffectEntries("p1");
  if (!entries.length) return;
  const seedCount = Math.min(3, botMemoryLimit(bot));
  bot.memory = initialMemoryEntries(seedCount);
  recordBotMemorySource(bot, bot.memory.length, ITEMS.p1?.name || "Seal of Vassago");
  entries.forEach((entry) => markPassiveEntryTriggered(entry));
}

function applyBotSinLossDamage(bot, lost, extraDamagePerSin = 0, extraSource = "") {
  const amount = Math.max(0, Math.ceil(lost));
  if (!bot || bot.eliminated || amount <= 0) return;

  if (extraDamagePerSin > 0) {
    const damage = Math.ceil(amount * extraDamagePerSin);
    if (damage > 0) queueEndOfRoundBotDamage(bot, damage, `${extraSource} dealt ${damage} damage to ${bot.name}.`, extraSource || "SIN loss");
  }

  orderedPassiveEffectEntries("p43").forEach((entry) => {
    const damage = passiveEntryFlatDamage(entry, 20);
    if (damage <= 0 || bot.eliminated) return;
    markPassiveEntryTriggered(entry);
    queueEndOfRoundBotDamage(bot, damage, `Seal of Raum dealt ${damage} damage to ${bot.name} for losing SIN.`, "Seal of Raum");
  });
}

function agaresDamagePerSin(entry) {
  return flatDamageValue(entry, 5);
}

function applyBotSinGainDamage(bot, gained) {
  return 0;
}

function stubbornArtifactChance(idOrItem) {
  const stack = simpleStackCount(idOrItem);
  if (!stack) return 0;
  return Math.min(1, 0.5 + Math.max(0, stack - 1) * 0.1);
}

function balamCollapseTargets(sourceBot) {
  const bosses = activeBots().filter((bot) => bot.id !== sourceBot?.id && bot.isBoss);
  if (bosses.length) return bosses;
  return activeBots().filter((bot) => bot.id !== sourceBot?.id);
}

function checkBalamMemoryBountyEliminations() {
  const round = state.roundState;
  const entries = orderedPassiveEffectEntries("p57");
  if (!round || round.balamResolving || !entries.length) return;
  round.balamResolving = true;
  try {
    let target = activeBots().find((bot) => !bot.isBoss && !bot.immortal && (bot.memory?.length || 0) >= 10 && botRegularBounty(bot) >= 10);
    while (target) {
      entries.forEach((entry) => markPassiveEntryTriggered(entry));
      const damagePool = passiveEntryFlatDamage(entries[0], target.maxHp || 0);
      target.hp = 0;
      target.deathCause = "memory-bounty";
      target.deathNotice = "BALAM";
      round.roundEvents.push(`Seal of Balam eliminated ${target.name} for reaching 10 memory and 10 bounty.`);

      const damageTargets = balamCollapseTargets(target);
      if (damagePool > 0 && damageTargets.length) {
        const allocations = randomDamageSpread(damagePool, damageTargets);
        damageBots(
          damageTargets,
          (bot) => allocations.get(bot.id) || 0,
          (bot, damage) => `Seal of Balam dealt ${damage} collapse damage to ${bot.name}.`,
          "Seal of Balam"
        );
      }

      resolveEliminatedBots([target]);
      target = activeBots().find((bot) => !bot.isBoss && !bot.immortal && (bot.memory?.length || 0) >= 10 && botRegularBounty(bot) >= 10);
    }
  } finally {
    round.balamResolving = false;
  }
}

function changeBotSin(bot, delta, reason = "", options = {}) {
  if (!bot || bot.eliminated) return { changed: 0, lost: 0, gained: 0 };
  const before = botSin(bot);
  const next = Math.max(0, Math.ceil(before + delta));
  bot.reward = next;
  const changed = next - before;
  if (!changed) return { changed: 0, lost: 0, gained: 0 };
  const lost = Math.max(0, -changed);
  const gained = Math.max(0, changed);
  const fallbackSource = changed > 0 ? "SIN gain" : "SIN loss";
  const source = options.source || sourceLabelFromReason(reason, fallbackSource);
  bot.lastSinDelta = (bot.lastSinDelta || 0) + changed;
  recordBotSinSource(bot, changed, source);
  if (reason) state.roundState?.roundEvents.push(reason);
  if (lost > 0 && options.triggerLossDamage !== false) {
    applyBotSinLossDamage(bot, lost, options.extraDamagePerSin || 0, options.extraDamageSource || "");
  }
  if (gained > 0) {
    applyBountyToMemoryMirror(bot, gained, options);
    applyBountyPoison(bot);
  }
  checkBalamMemoryBountyEliminations();
  return { changed, lost, gained };
}

function setBotSin(bot, value, reason = "", options = {}) {
  return changeBotSin(bot, Math.ceil(value) - botSin(bot), reason, options);
}

function increaseAllBotSin(amount, reasonFactory) {
  const increase = Math.max(0, Math.ceil(amount));
  if (increase <= 0) return 0;
  let total = 0;
  activeBots().forEach((bot) => {
    const result = changeBotSin(bot, increase, typeof reasonFactory === "function" ? reasonFactory(bot, increase) : "", {
      triggerLossDamage: false
    });
    total += result.gained;
  });
  return total;
}

function applyTargetedItemSinGain(item, targets) {
  const uniqueTargets = Array.from(new Set((targets || []).filter((bot) => bot && !bot.eliminated)));
  if (!item || !uniqueTargets.length) return;
  if (state.roundState?.artifactTargetCountsByBotId) {
    uniqueTargets.forEach((bot) => {
      const previous = state.roundState.artifactTargetCountsByBotId.get(bot.id) || 0;
      state.roundState.artifactTargetCountsByBotId.set(bot.id, previous + 1);
    });
  }
  orderedPassiveEffectEntries("p82").forEach((entry) => {
    const chance = Math.min(1, 0.5 + Math.max(0, (entry.stack || 1) - 1) * 0.1);
    let revealed = 0;
    uniqueTargets.forEach((bot) => {
      if (Math.random() < chance && revealBotGuess(bot, "Seal of Marked Offering", entry)) revealed += 1;
    });
    if (revealed > 0) state.roundState?.roundEvents.push(`Seal of Marked Offering revealed ${revealed} targeted DAMNED.`);
  });
  orderedPassiveEffectEntries("p105").forEach((entry) => {
    const chance = stubbornArtifactChance(entry);
    let changed = 0;
    uniqueTargets.forEach((bot) => {
      if (Math.random() < chance && setBotPersonality(bot, "Stubborn", passiveName("p105", "Seal of Andras"), { markEntry: entry })) {
        changed += 1;
      }
    });
    if (changed > 0) state.roundState?.roundEvents.push(`${passiveName("p105", "Seal of Andras")} made ${changed} ARTIFACT target${changed === 1 ? "" : "s"} STUBBORN.`);
  });
  const entries = orderedPassiveEffectEntries("p49");
  if (!entries.length) return;
  entries.forEach((entry) => {
    const amount = passiveEntryScaledValue(entry, 3);
    if (amount <= 0) return;
    markPassiveEntryTriggered(entry);
    uniqueTargets.forEach((bot) => {
      changeBotSin(bot, amount, `Seal of Phenex gave ${bot.name} +${amount} SIN because ${item.name} targeted them.`, {
        triggerLossDamage: false
      });
    });
  });
}

