function romanNumeral(value) {
  const parts = [[100, "C"], [90, "XC"], [50, "L"], [40, "XL"], [10, "X"], [9, "IX"], [5, "V"], [4, "IV"], [1, "I"]];
  let left = Math.max(0, Math.floor(value));
  return parts.reduce((text, [size, mark]) => {
    while (left >= size) {
      text += mark;
      left -= size;
    }
    return text;
  }, "");
}

