function sealBuilds(id) {
  return SEAL_BUILD_TAGS[id] || ["general"];
}

function collectionFilter() {
  const key = state.collectionFilter;
  return SEAL_BUILDS.some((build) => build.key === key) ? key : "all";
}

function sealMatchesCollectionFilter(id, filter = collectionFilter()) {
  return filter === "all" || sealBuilds(id).includes(filter);
}

/* ---- search: one box on each tab, matched as you type ----
   SEALS match by name, text and build; demons by number (9 or IX) and, once defeated, by name (other
   spellings too: "morax", "gamigin"), their SEAL's name and "bound". Every word typed has to match. */
const collectionSearch = { seals: "", goetia: "", angels: "" };

function collectionSearchText(value) {
  return String(value || "")
    .replace(/<[^>]*>/g, " ")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

function collectionSearchWords(query) {
  const text = collectionSearchText(query);
  return text ? text.split(" ") : [];
}

function sealMatchesSearch(id, query = collectionSearch.seals) {
  const words = collectionSearchWords(query);
  if (!words.length) return true;
  const item = ITEMS[id];
  if (!item) return false;
  const builds = sealBuilds(id).map((key) => SEAL_BUILDS.find((build) => build.key === key)?.label || "");
  const haystack = collectionSearchText([item.name, item.description, ...builds].join(" "));
  return words.every((word) => haystack.includes(word));
}

function collectionSealVisible(id) {
  return sealMatchesCollectionFilter(id) && sealMatchesSearch(id);
}

function demonMatchesSearch(key, query) {
  if (ARCHANGEL_BY_KEY[key]) return archangelMatchesSearch(key, query ?? collectionSearch.angels);
  const words = collectionSearchWords(query ?? collectionSearch.goetia);
  if (!words.length) return true;
  const index = GOETIC_BOSS_KEYS.indexOf(key);
  const spec = GOETIC_BOSS_SPECS[index];
  if (!spec) return false;
  const numbers = [String(index + 1), romanNumeral(index + 1).toLowerCase()];
  if (words.length === 1 && numbers.includes(words[0])) return true;
  // a demon not defeated yet has no name to find
  if (!isDemonSlain(key)) return false;
  const seal = spec.passiveId && ITEMS[spec.passiveId] ? ITEMS[spec.passiveId].name : "";
  const haystack = collectionSearchText(
    [spec.name, spec.image.replace(/^\d+-|\.png$/gi, ""), seal, collectionBoundDemon() === key ? "bound" : ""].join(" ")
  );
  return words.every((word) => haystack.includes(word));
}

function archangelMatchesSearch(key, query = collectionSearch.angels) {
  const words = collectionSearchWords(query);
  if (!words.length) return true;
  const spec = ARCHANGEL_BY_KEY[key];
  if (!spec) return false;
  const known = [spec.planet, "archangel"];
  if (isArchangelDefeated(key)) known.push(spec.name, ITEMS[spec.sealId]?.name || "", spec.build, collectionBoundDemon() === key ? "bound" : "");
  const haystack = collectionSearchText(known.join(" "));
  return words.every((word) => haystack.includes(word));
}

function collectionSearchHtml(tab) {
  const value = collectionSearch[tab] || "";
  const label = tab === "goetia" ? "Search demons" : tab === "angels" ? "Search Archangels" : "Search SEALS";
  return `
    <label class="collection-search${value ? " has-value" : ""}">
      <img class="collection-search-icon" src="assets/ui/search-eye.png" alt="" aria-hidden="true" draggable="false" />
      <input class="collection-search-input" type="text" data-collection-search="${tab}" value="${escapeAttr(value)}" placeholder="Search" aria-label="${label}" autocomplete="off" autocapitalize="off" spellcheck="false" enterkeyhint="search" />
      <button type="button" class="collection-search-clear" data-collection-search-clear="${tab}" aria-label="Clear the search">&times;</button>
    </label>`;
}

function collectionEmptyHtml(tab) {
  return `<div class="collection-empty" data-collection-empty="${tab}" hidden>Nothing matches your search.</div>`;
}

// shows and hides SEALS, sections and demons in place for the build filter and both searches
function applyCollectionVisibility(screen) {
  if (!screen) return;
  screen.querySelectorAll(".collection-seal").forEach((button) => {
    button.hidden = !collectionSealVisible(button.dataset.collectionSeal);
  });
  screen.querySelectorAll(".collection-section").forEach((section) => {
    section.hidden = !section.querySelector(".collection-seal:not([hidden])");
  });
  screen.querySelectorAll(".collection-demon").forEach((button) => {
    button.hidden = !demonMatchesSearch(button.dataset.collectionDemon);
  });
  const sealsEmpty = screen.querySelector('[data-collection-empty="seals"]');
  if (sealsEmpty) sealsEmpty.hidden = Boolean(screen.querySelector(".collection-seal:not([hidden])"));
  ["goetia", "angels"].forEach((tab) => {
    const empty = screen.querySelector(`[data-collection-empty="${tab}"]`);
    const panel = screen.querySelector(`[data-collection-panel="${tab}"]`);
    if (empty && panel) empty.hidden = Boolean(panel.querySelector(".collection-demon:not([hidden])"));
  });
  screen.querySelectorAll(".collection-search").forEach((label) => {
    const input = label.querySelector("[data-collection-search]");
    label.classList.toggle("has-value", Boolean(input?.value));
  });
}

function applyCollectionSearch(screen, tab, value) {
  collectionSearch[tab] = value;
  if (!screen) return;
  screen.querySelectorAll(COLLECTION_SELECTED).forEach((el) => el.classList.remove("selected"));
  hideCollectionInfo(screen);
  applyCollectionVisibility(screen);
  const body = screen.querySelector(`[data-collection-panel="${tab}"] .collection-body`);
  if (body) body.scrollTop = 0;
}

/* ---- stored progress ---- */
let collectionProgressCache = null;

function defaultCollectionProgress() {
  return {
    version: 2,
    unlocked: [],
    discovered: [],
    // the Goetic BOSSES slain at least once (GOETIC_BOSS_SPECS keys): the Ars Goetia tab
    slain: [],
    // the Archangel BOSSES defeated at least once (ARCHANGEL_BOSS_SPECS keys): the Archangels tab
    archangels: [],
    // the demon or Archangel bound for the next run (a defeated one), or null
    boundDemon: null,
    // testing only (DEV button in the Ars Goetia): every demon counts as defeated while it is on
    devAllDemons: false,
    // testing only (DEV button on Jesus' Gifts): KARMA never runs out while it is on
    devInfiniteKarma: false,
    // KARMA, the currency kept between runs (see the KARMA section at the end of this file)
    karma: 0,
    stats: Object.fromEntries(Object.keys(COLLECTION_STAT_LABELS).map((key) => [key, 0])),
    best: Object.fromEntries(Object.keys(COLLECTION_BEST_LABELS).map((key) => [key, 0])),
    flags: {},
    // SEAL records, by SEAL id (see normalizeSealRecord)
    seals: {}
  };
}

function loadCollectionProgress() {
  if (collectionProgressCache) return collectionProgressCache;
  const progress = defaultCollectionProgress();
  try {
    const raw = window.localStorage?.getItem(COLLECTION_STORAGE_KEY);
    if (raw) {
      const saved = JSON.parse(raw);
      if (Array.isArray(saved.unlocked)) progress.unlocked = saved.unlocked.filter((id) => typeof id === "string");
      if (Array.isArray(saved.discovered)) progress.discovered = saved.discovered.filter((id) => typeof id === "string");
      if (Array.isArray(saved.slain)) progress.slain = saved.slain.filter((key) => typeof key === "string" && GOETIC_BOSS_BY_KEY[key]);
      progress.devAllDemons = saved.devAllDemons === true;
      progress.devInfiniteKarma = saved.devInfiniteKarma === true;
      if (Array.isArray(saved.archangels)) progress.archangels = saved.archangels.filter((key) => typeof key === "string" && ARCHANGEL_BY_KEY[key]);
      if (typeof saved.boundDemon === "string" && (GOETIC_BOSS_BY_KEY[saved.boundDemon] || ARCHANGEL_BY_KEY[saved.boundDemon])) progress.boundDemon = saved.boundDemon;
      if (saved.flags && typeof saved.flags === "object") progress.flags = { ...saved.flags };
      progress.karma = Math.max(0, Math.floor(Number(saved.karma) || 0));
      if (saved.seals && typeof saved.seals === "object") {
        Object.entries(saved.seals).forEach(([id, record]) => {
          if (typeof id === "string" && record && typeof record === "object") progress.seals[id] = normalizeSealRecord(record);
        });
      }
      for (const group of ["stats", "best"]) {
        const source = saved[group] && typeof saved[group] === "object" ? saved[group] : {};
        Object.keys(progress[group]).forEach((key) => {
          progress[group][key] = Math.max(0, Math.floor(Number(source[key]) || 0));
        });
      }
    } else {
      // the first version had other achievements: keep only what was discovered
      COLLECTION_OLD_STORAGE_KEYS.forEach((key) => {
        const old = JSON.parse(window.localStorage?.getItem(key) || "null");
        if (Array.isArray(old?.discovered)) progress.discovered = old.discovered.filter((id) => typeof id === "string");
      });
    }
  } catch (error) {}
  collectionProgressCache = progress;
  return progress;
}

function saveCollectionProgress() {
  if (!collectionProgressCache) return;
  try {
    window.localStorage?.setItem(COLLECTION_STORAGE_KEY, JSON.stringify(collectionProgressCache));
  } catch (error) {}
}

/* ---- queries ---- */
function collectibleSealIds() {
  return PASSIVE_IDS.filter((id) => ITEMS[id] && !REMOVED_PASSIVE_IDS.has(id));
}

function isUnlockableSeal(id) {
  return Boolean(SEAL_UNLOCKS[id]);
}

function isSealUnlocked(id) {
  if (!isUnlockableSeal(id)) return true;
  // Pause > Unlock (testing): every SEAL counts as unlocked for the rest of this run
  if (state.devUnlockAllSeals && state.mode !== "menu") return true;
  return loadCollectionProgress().unlocked.includes(id);
}

function isSealLocked(id) {
  return !isSealUnlocked(id);
}

function isSealDiscovered(id) {
  return loadCollectionProgress().discovered.includes(id);
}

function sealUnlockProgress(id) {
  const rule = SEAL_UNLOCKS[id];
  if (!rule) return null;
  const progress = loadCollectionProgress();
  if (rule.stat) return { value: progress.stats[rule.stat] || 0, goal: rule.goal };
  if (rule.best) return { value: progress.best[rule.best] || 0, goal: rule.goal };
  if (rule.flag) return { value: progress.flags[rule.flag] ? 1 : 0, goal: 1 };
  return null;
}

function sealUnlockMet(id) {
  const result = sealUnlockProgress(id);
  return Boolean(result && result.value >= result.goal);
}

/* ---- recording (called from the game) ---- */
function collectionCounts() {
  // only real arcade runs count: not PvP, not the story's tutorial rounds, not infinite-SIN testing
  if (state.mode !== "arcade") return false;
  if (typeof introBlocksRunSave === "function" && introBlocksRunSave()) return false;
  if (typeof playtestMoneyModeActive === "function" && playtestMoneyModeActive()) return false;
  return true;
}

let collectionDirty = false;
const collectionToastQueue = [];
let collectionToastBusy = false;

function collectionBump(stat, amount = 1) {
  if (!collectionCounts() || !(stat in COLLECTION_STAT_LABELS)) return;
  const progress = loadCollectionProgress();
  progress.stats[stat] = (progress.stats[stat] || 0) + amount;
  collectionDirty = true;
}

function collectionRaise(key, value) {
  if (!collectionCounts() || !(key in COLLECTION_BEST_LABELS)) return;
  const best = loadCollectionProgress().best;
  const next = Math.max(0, Math.floor(Number(value) || 0));
  if (next <= (best[key] || 0)) return;
  best[key] = next;
  collectionDirty = true;
}

function collectionFlag(key) {
  if (!collectionCounts() || !(key in COLLECTION_FLAG_LABELS)) return;
  const flags = loadCollectionProgress().flags;
  if (flags[key]) return;
  flags[key] = true;
  collectionDirty = true;
}

// per-run counters (saved with the run)
function collectionRun() {
  const defaults = { uniqueKills: [], beaten: false, zilonBuyouts: 0, buyoutCounted: false, critStreak: 0, pentakillStreak: 0, noKoStreak: 0, roundSpent: 0, roundProcessed: 0, sealRound: null, beatenRound: 0, karma: 0, karmaRolled: 0 };
  if (!state.collectionRun || typeof state.collectionRun !== "object") state.collectionRun = defaults;
  else Object.keys(defaults).forEach((key) => { if (!(key in state.collectionRun)) state.collectionRun[key] = defaults[key]; });
  return state.collectionRun;
}

function resetCollectionRun() {
  state.collectionRun = null;
  collectionRun();
}

// a unique BOSS (alive or knocked out this round) is on the table
function collectionBossPresent(key, aliveOnly = false) {
  return (state.bots || []).some((bot) => bot?.isBoss && bot.uniqueKey === key && (!aliveOnly || (!bot.eliminated && bot.hp > 0)));
}

function collectionBeginRound() {
  if (state.mode !== "arcade") return;
  collectionRun().roundSpent = 0;
  // BOSSES at full SOUL when the round starts: knocking one out this round counts as a one-shot
  (state.bots || []).forEach((bot) => {
    if (bot?.isBoss) bot.fullHealthAtRoundStart = !bot.immortal && bot.hp >= bot.maxHp;
  });
}

function collectionNoteSpend(cost) {
  if (!collectionCounts() || !(cost > 0)) return;
  const run = collectionRun();
  run.roundSpent += cost;
  collectionRaise("roundSpent", run.roundSpent);
}

function collectionNoteElimination(bot) {
  if (bot?.isBoss && bot.goeticKey) collectionSlayDemon(bot.goeticKey);
  if (bot?.isBoss && bot.archangelKey) collectionDefeatArchangel(bot.archangelKey);
  if (!collectionCounts() || !bot) return;
  collectionBump("eliminations");
  if (/^Yannis\b/i.test(bot.name || "")) collectionBump("yannisKills");
  if (state.player.hp >= 100) collectionFlag("fullHealthKill");
  if (!bot.isBoss) return;
  if (bot.goeticKey) collectionBump("goeticKills");
  if (bot.fullHealthAtRoundStart) collectionFlag("fullHealthBossKill");
  if (bot.pyrosGifted && bot.uniqueKey !== "pyros") collectionFlag("pyrosGiftBossKill");
  if (bot.uniqueKey) {
    const run = collectionRun();
    if (!run.uniqueKills.includes(bot.uniqueKey)) run.uniqueKills.push(bot.uniqueKey);
    // beating the game = all 8 unique BOSSES defeated in one run (Petros and Pavlos both)
    const needed = [...UNIQUE_BOSS_KEYS, "pavlos"];
    if (!run.beaten && needed.every((key) => run.uniqueKills.includes(key))) {
      run.beaten = true;
      run.beatenRound = state.round;
      collectionBump("gamesBeaten");
      collectionNoteSealWins();
      if (!(state.totalArtifactsUsed > 0)) collectionFlag("beatNoArtifacts");
      karmaGain(KARMA_GAME_BEATEN, "Beating the game");
    }
  }
  collectionNoteKarmaDrop(bot);
}

function collectionNotePentakill() {
  if (!collectionCounts()) return;
  if (state.roundState) state.roundState.collectionPentakill = true;
  if (collectionBossPresent("dantre")) collectionFlag("dantrePentakill");
}

function collectionNoteArtifactUse() {
  if (!collectionCounts() || !state.roundState) return;
  if ((state.roundState.activeUses || 0) >= 4 && collectionBossPresent("threon", true)) collectionFlag("threonArtifacts");
}

function collectionNoteShopBuy() {
  if (!collectionCounts()) return;
  const run = collectionRun();
  const shop = state.shop || [];
  if (!shop.length || run.buyoutCounted || !shop.every((slot) => slot?.sold)) return;
  run.buyoutCounted = true;
  if (!collectionBossPresent("zilon", true)) return;
  run.zilonBuyouts += 1;
  if (run.zilonBuyouts >= 3) collectionFlag("zilonBuyouts");
}

function collectionNoteShopReroll() {
  if (state.mode === "arcade") collectionRun().buyoutCounted = false;
}

function collectionNoteSerafimEntry(bot, stolen) {
  if (bot?.uniqueKey === "serafim" && !(stolen > 0)) collectionFlag("serafimNoSteal");
}

// a SEAL triggered: it is discovered for good
function collectionDiscover(id) {
  if (state.mode !== "arcade" || !id || !ITEMS[id]) return;
  const progress = loadCollectionProgress();
  if (progress.discovered.includes(id)) return;
  progress.discovered.push(id);
  saveCollectionProgress();
}

/* ---- SEAL records: lifetime numbers for each SEAL, shown in the Collection while Shift is held ----
     wins      games beaten (the 8 unique BOSSES) with the SEAL in a slot at the moment of the win;
               a SEAL you have won with turns deep red in the Collection, like a SEAL that triggers
     elite     the highest ELITE level it reached (not kept for SEALS that cannot be upgraded)
     triggers  every activation, in all runs
     total / run / round   for every amount the SEAL produces (the state.sealStats kinds below):
               the lifetime sum, the most in one run, the most in one round
   Only real arcade runs count (collectionCounts). */
const SEAL_RECORD_KINDS = [
  { key: "damage", label: "Damage dealt" },
  { key: "healing", label: "Healing done" },
  { key: "saved", label: "Damage negated" },
  { key: "credits", label: "SIN gained" },
  { key: "memory", label: "MEMORY added" },
  { key: "bounty", label: "BOUNTY added" },
  { key: "bountyRemoved", label: "BOUNTY removed" },
  { key: "personality", label: "Personalities changed" }
];

function normalizeSealRecord(source = {}) {
  const count = (value) => Math.max(0, Math.floor(Number(value) || 0));
  const amounts = (group) =>
    Object.fromEntries(
      SEAL_RECORD_KINDS.map(({ key }) => [key, count(group && typeof group === "object" ? group[key] : 0)]).filter(([, value]) => value > 0)
    );
  return {
    wins: count(source.wins),
    elite: count(source.elite),
    triggers: count(source.triggers),
    total: amounts(source.total),
    run: amounts(source.run),
    round: amounts(source.round)
  };
}

function sealRecord(id, create = false) {
  const seals = loadCollectionProgress().seals;
  if (!seals[id] && create) seals[id] = normalizeSealRecord();
  return seals[id] || null;
}

function sealRecordShowsElite(id) {
  return !NON_UPGRADABLE_SEAL_IDS.has(id) && !SELF_STACKING_SEAL_IDS.has(id);
}

function isSealBeaten(id) {
  return (sealRecord(id)?.wins || 0) > 0;
}

// recordSealStat (03) calls this with the amount just added and the SEAL's total for this run
function collectionNoteSealStat(id, kind, value, runTotal) {
  if (!collectionCounts() || !ITEMS[id] || !(value > 0) || !SEAL_RECORD_KINDS.some((entry) => entry.key === kind)) return;
  const record = sealRecord(id, true);
  record.total[kind] = (record.total[kind] || 0) + value;
  record.run[kind] = Math.max(record.run[kind] || 0, runTotal || 0);
  const run = collectionRun();
  if (!run.sealRound || run.sealRound.round !== state.round) run.sealRound = { round: state.round, values: {} };
  const key = `${id}:${kind}`;
  run.sealRound.values[key] = (run.sealRound.values[key] || 0) + value;
  record.round[kind] = Math.max(record.round[kind] || 0, run.sealRound.values[key]);
  collectionDirty = true;
}

function collectionNoteSealTrigger(id) {
  if (!collectionCounts() || !ITEMS[id]) return;
  sealRecord(id, true).triggers += 1;
  collectionDirty = true;
}

// the game was just beaten: every SEAL in a slot right now gets the win
function collectionNoteSealWins() {
  const ids = [...new Set((state.player.passives || []).map((item) => item?.id).filter((id) => id && ITEMS[id] && !REMOVED_PASSIVE_IDS.has(id)))];
  ids.forEach((id) => {
    sealRecord(id, true).wins += 1;
    collectionDiscover(id);
  });
  if (ids.length) collectionDirty = true;
}

function collectionNoteSealElite() {
  (state.player.passives || []).forEach((item) => {
    if (!item || !ITEMS[item.id] || !sealRecordShowsElite(item.id)) return;
    const level = Math.max(0, (item.stack || 1) - 1);
    if (level <= 0 || level <= (sealRecord(item.id)?.elite || 0)) return;
    sealRecord(item.id, true).elite = level;
    collectionDirty = true;
  });
}

// the beaten mark: one small hand-drawn symbol next to the status, no word
const COLLECTION_BEATEN_MARKS = {
  pentagram: `<circle cx="12" cy="12" r="10.4"/><path d="M12 21.3 6.53 4.48 20.85 14.87H3.16L17.47 4.48Z"/>`,
  skull: `<path d="M12 2.6C6.9 2.6 4.1 6 4.1 10.2c0 2.5 1.1 4.2 2.6 5.2V18h2.2v2.4h6.2V18h2.2v-2.6c1.5-1 2.6-2.7 2.6-5.2 0-4.2-2.8-7.6-7.9-7.6Z"/><circle cx="8.9" cy="10.9" r="1.9" fill="currentColor"/><circle cx="15.1" cy="10.9" r="1.9" fill="currentColor"/><path d="M12 13.7 10.9 15.7h2.2ZM10.9 18v2.4M13.1 18v2.4"/>`,
  trophy: `<path d="M7 3.4h10v4.6c0 3-2.2 5.5-5 5.5S7 11 7 8Z"/><path d="M7 5.4H4.4c0 2.6 1.3 4.1 3.3 4.4M17 5.4h2.6c0 2.6-1.3 4.1-3.3 4.4M12 13.5v3.4M9.4 16.9h5.2v3.6H9.4ZM8 20.5h8"/>`
};
const COLLECTION_BEATEN_MARK = "pentagram";

function collectionBeatenMarkHtml(mark = COLLECTION_BEATEN_MARK) {
  const shape = COLLECTION_BEATEN_MARKS[mark] || COLLECTION_BEATEN_MARKS.pentagram;
  return `<svg class="collection-beaten-mark" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" role="img" aria-label="Game beaten with this SEAL"><title>Game beaten with this SEAL</title>${shape}</svg>`;
}

// the records block: wins / ELITE / triggers, then a small table with total, best run and best round
function sealRecordsHtml(id) {
  const record = sealRecord(id) || normalizeSealRecord();
  const row = (label, value, shown = value, extraClass = "") =>
    `<div class="collection-record-row"><span>${escapeHtml(label)}</span><span class="collection-record-lead"></span><span class="collection-record-value${value > 0 ? "" : " zero"}${extraClass}">${escapeHtml(shown)}</span></div>`;
  const rows = [
    row("Games beaten", record.wins, formatNumber(record.wins)),
    sealRecordShowsElite(id) ? row("Highest ELITE", record.elite, record.elite > 0 ? romanNumeral(record.elite) : "-", " roman") : "",
    row("Times triggered", record.triggers, formatNumber(record.triggers))
  ].join("");
  const kinds = SEAL_RECORD_KINDS.filter(({ key }) => (record.total[key] || 0) > 0);
  const table = kinds.length
    ? `<table class="collection-record-table">
        <thead><tr><th></th><th>Total</th><th>Best run</th><th>Best round</th></tr></thead>
        <tbody>${kinds
          .map(({ key, label }) => `<tr><th>${escapeHtml(label)}</th><td>${formatNumber(record.total[key] || 0)}</td><td>${formatNumber(record.run[key] || 0)}</td><td>${formatNumber(record.round[key] || 0)}</td></tr>`)
          .join("")}</tbody>
      </table>`
    : "";
  return `<div class="collection-info-records">${rows}${table}</div>`;
}

/* ---- the Ars Goetia: the 72 Goetic BOSSES ----
   A demon is discovered the first time its BOSS is slain in a run (like a SEAL the first time it triggers).
   The Collection lists them on its second tab in the order of the book; the ones not slain yet stay dark
   and nameless. */
let collectionTab = "seals";

function isDemonSlain(key) {
  const progress = loadCollectionProgress();
  return Boolean(GOETIC_BOSS_BY_KEY[key]) && (progress.devAllDemons || progress.slain.includes(key));
}

// DEV (testing): every demon counts as defeated, so any of them can be bound; off again shows the real progress
function toggleDevAllDemons() {
  const progress = loadCollectionProgress();
  progress.devAllDemons = !progress.devAllDemons;
  saveCollectionProgress();
}

function isArchangelDefeated(key) {
  const progress = loadCollectionProgress();
  return Boolean(ARCHANGEL_BY_KEY[key]) && (progress.devAllDemons || progress.archangels.includes(key));
}

// a demon or an Archangel that can be bound
function isBossEntryDefeated(key) {
  return isDemonSlain(key) || isArchangelDefeated(key);
}

function collectionDefeatArchangel(key) {
  if (state.mode !== "arcade" || !ARCHANGEL_BY_KEY[key]) return;
  const progress = loadCollectionProgress();
  if (progress.archangels.includes(key)) return;
  progress.archangels.push(key);
  saveCollectionProgress();
}

function collectionSlayDemon(key) {
  if (state.mode !== "arcade" || !GOETIC_BOSS_BY_KEY[key]) return;
  const progress = loadCollectionProgress();
  if (progress.slain.includes(key)) return;
  progress.slain.push(key);
  saveCollectionProgress();
}

/* binding: one defeated demon can be bound. A run takes the one bound when it starts (state.boundDemon)
   and keeps it to the end: its SEAL is free in Devil's Offerings and YOU comes instead of it. */
function collectionBoundDemon() {
  const key = loadCollectionProgress().boundDemon;
  return key && isBossEntryDefeated(key) ? key : null;
}

function boundDemonForNewRun() {
  return collectionBoundDemon();
}

function toggleBoundDemon(key) {
  if (!isBossEntryDefeated(key)) return;
  const progress = loadCollectionProgress();
  progress.boundDemon = progress.boundDemon === key ? null : key;
  saveCollectionProgress();
}

// the header line and the marks on the grid, updated in place after a bind
function collectionBoundLine() {
  const key = collectionBoundDemon();
  const runKey = state.mode === "arcade" ? state.boundDemon : null;
  const name = (demonKey) => (demonKey ? (GOETIC_BOSS_BY_KEY[demonKey] || ARCHANGEL_BY_KEY[demonKey])?.name || "none" : "none");
  const runNote = state.mode === "arcade" && runKey !== key ? `<span>this run: <strong>${escapeHtml(name(runKey))}</strong></span>` : "";
  return `<span>bound: <strong>${escapeHtml(name(key))}</strong></span>${runNote}`;
}

function refreshCollectionBinding(screen) {
  if (!screen) return;
  const key = collectionBoundDemon();
  screen.querySelectorAll("[data-collection-demon]").forEach((button) => {
    button.classList.toggle("bound", button.dataset.collectionDemon === key);
  });
  screen.querySelectorAll(".collection-bound-line").forEach((line) => {
    line.innerHTML = collectionBoundLine();
  });
  const pinned = screen.querySelector(".collection-demon.selected");
  if (pinned) showCollectionInfo(pinned, true);
}

// small copies of the BOSS art (the full images are 1254px)
function demonThumbPath(spec) {
  return `${GOETIC_BOSS_IMAGE_ROOT}/thumbs/${spec.image.replace(/\.png$/i, ".webp")}`;
}

function collectionDemonsHtml() {
  const bound = collectionBoundDemon();
  const cells = GOETIC_BOSS_SPECS.map((spec, index) => {
    const slain = isDemonSlain(spec.key);
    const number = romanNumeral(index + 1);
    return `
      <button class="collection-demon ${slain ? "slain" : "unslain"}${spec.key === bound ? " bound" : ""}" type="button"${demonMatchesSearch(spec.key) ? "" : " hidden"} data-collection-demon="${escapeAttr(spec.key)}" aria-label="${escapeAttr(slain ? spec.name : `${number}, not defeated`)}">
        <img class="collection-demon-art" src="${escapeAttr(demonThumbPath(spec))}" alt="" loading="lazy" draggable="false" />
        <span class="collection-demon-number">${number}${slain ? `<span class="collection-demon-bound"> · Bound</span>` : ""}</span>
        <span class="collection-demon-name">${slain ? escapeHtml(spec.name) : "???"}</span>
      </button>`;
  });
  return `<div class="collection-demon-grid">${cells.join("")}</div>${collectionEmptyHtml("goetia")}`;
}

function archangelThumbPath(spec) {
  return `${ARCHANGEL_BOSS_IMAGE_ROOT}/thumbs/${spec.image.replace(/\.png$/i, ".webp")}`;
}

// the Archangels tab: the seven, in weekday order (Sun to Saturn); the line under each names its planet
function collectionArchangelsHtml() {
  const bound = collectionBoundDemon();
  const cells = ARCHANGEL_BOSS_SPECS.map((spec) => {
    const defeated = isArchangelDefeated(spec.key);
    const planet = spec.planet.replace(/^the /, "");
    return `
      <button class="collection-demon collection-angel ${defeated ? "slain" : "unslain"}${spec.key === bound ? " bound" : ""}" type="button"${demonMatchesSearch(spec.key) ? "" : " hidden"} data-collection-demon="${escapeAttr(spec.key)}" aria-label="${escapeAttr(defeated ? spec.name : `Archangel of ${spec.planet}, not defeated`)}">
        <img class="collection-demon-art" src="${escapeAttr(archangelThumbPath(spec))}" alt="" loading="lazy" draggable="false" />
        <span class="collection-demon-number">${escapeHtml(planet)}${defeated ? `<span class="collection-demon-bound"> · Bound</span>` : ""}</span>
        <span class="collection-demon-name">${defeated ? escapeHtml(spec.name) : "???"}</span>
      </button>`;
  });
  return `<div class="collection-demon-grid collection-angel-grid">${cells.join("")}</div>${collectionEmptyHtml("angels")}`;
}

function collectionArchangelInfoHtml(key, pinned = false) {
  const spec = ARCHANGEL_BY_KEY[key];
  if (!spec) return "";
  if (!isArchangelDefeated(key)) {
    return `
      <div class="collection-info-status unslain">Not defeated</div>
      <div class="collection-info-name">???</div>
      <div class="collection-info-number">Archangel of ${escapeHtml(spec.planet)}</div>
      <div class="collection-info-note">Not discovered yet: defeat this Archangel in a run.</div>`;
  }
  const seal = ITEMS[spec.sealId]?.name || "";
  return `
    <div class="collection-info-status slain">Defeated</div>
    <div class="collection-info-name">${escapeHtml(spec.name)}</div>
    <div class="collection-info-number">Archangel of ${escapeHtml(spec.planet)}</div>
    <div class="collection-info-text">${descriptionHtml(ARCHANGEL_ABILITY_TEXT[key])}</div>
    ${collectionDemonBindHtml(key, seal, pinned)}`;
}

function collectionDemonInfoHtml(key, pinned = false) {
  if (ARCHANGEL_BY_KEY[key]) return collectionArchangelInfoHtml(key, pinned);
  const index = GOETIC_BOSS_KEYS.indexOf(key);
  const spec = GOETIC_BOSS_SPECS[index];
  if (!spec) return "";
  const number = romanNumeral(index + 1);
  if (!isDemonSlain(key)) {
    return `
      <div class="collection-info-status unslain">Not defeated</div>
      <div class="collection-info-name">???</div>
      <div class="collection-info-number">Spirit ${number} of the Ars Goetia</div>
      <div class="collection-info-note">Not discovered yet: slay this BOSS in a run, or find it in one of Jesus' Gifts.</div>`;
  }
  const seal = spec.passiveId && ITEMS[spec.passiveId] && !REMOVED_PASSIVE_IDS.has(spec.passiveId) ? ITEMS[spec.passiveId].name : "";
  return `
    <div class="collection-info-status slain">Defeated</div>
    <div class="collection-info-name">${escapeHtml(spec.name)}</div>
    <div class="collection-info-number">Spirit ${number} of the Ars Goetia</div>
    ${seal ? `<div class="collection-info-text">While it lives, ${escapeHtml(seal)} is silenced.</div>` : ""}
    ${collectionDemonBindHtml(key, seal, pinned)}`;
}

function collectionDemonBindHtml(key, seal, pinned) {
  const bound = collectionBoundDemon() === key;
  const archangel = Boolean(ARCHANGEL_BY_KEY[key]);
  const sealName = seal ? escapeHtml(seal) : "its SEAL";
  const sealText = archangel ? `you start with ${sealName}` : `${sealName} costs nothing in Devil's Offerings`;
  const text = bound
    ? `Bound. From your next run, ${sealText}, and you will face yourself in its place.`
    : `Bind it, and from your next run ${sealText}, and you will face yourself in its place.`;
  const runNote = state.mode === "arcade" && state.boundDemon === key ? `<div class="collection-info-note">Bound in this run.</div>` : "";
  const control = pinned
    ? `<button type="button" class="collection-bind-button" data-collection-bind="${escapeAttr(key)}">${bound ? "Unbind" : "Bind"}</button>`
    : `<div class="collection-info-note">Click to ${bound ? "unbind" : "bind"}.</div>`;
  return `
    <div class="collection-info-bind">
      <div class="collection-info-text">${text}</div>
      ${runNote}
      ${control}
    </div>`;
}

// switches tabs in place, so the screen does not replay its entrance
function applyCollectionTab(screen, tab) {
  collectionTab = ["goetia", "angels"].includes(tab) ? tab : "seals";
  if (!screen) return;
  screen.querySelectorAll("[data-collection-tab]").forEach((button) => {
    const active = button.dataset.collectionTab === collectionTab;
    button.classList.toggle("active", active);
    button.setAttribute("aria-selected", String(active));
  });
  screen.querySelectorAll("[data-collection-panel], [data-collection-for]").forEach((el) => {
    el.hidden = (el.dataset.collectionPanel || el.dataset.collectionFor) !== collectionTab;
  });
  screen.querySelectorAll(COLLECTION_SELECTED).forEach((el) => el.classList.remove("selected"));
  hideCollectionInfo(screen);
}

const COLLECTION_SELECTED = ".collection-seal.selected, .collection-demon.selected";

// after every render of a run: moment checks, end-of-round streaks, then unlock what is earned
function collectionAfterRender() {
  if (!collectionCounts()) return;
  recordsNoteSlots();
  const run = collectionRun();
  if (state.player.hp === 1) collectionFlag("oneHealth");
  collectionRaise("sinHeld", state.player.credits);
  collectionRaise("bossesAtOnce", (state.bots || []).filter((bot) => bot?.isBoss && !bot.eliminated && bot.hp > 0).length);
  collectionRaise("eliteLevel", Math.max(0, ...(state.player.passives || []).map((item) => (item?.stack || 1) - 1)));
  collectionNoteSealElite();
  const eliteSeals = (state.player.passives || []).filter((item) => item && (item.stack || 1) >= 2).length;
  if (eliteSeals >= 6) collectionFlag("sixEliteSeals");
  // once per round, when it is resolved
  const round = state.roundState;
  if (state.stage === "summary" && round && !roundRevealAnimationActive() && run.roundProcessed !== state.round) {
    run.roundProcessed = state.round;
    run.critStreak = round.criticalHitKeys?.has?.("player") ? run.critStreak + 1 : 0;
    run.pentakillStreak = round.collectionPentakill ? run.pentakillStreak + 1 : 0;
    run.noKoStreak = (round.eliminationsThisRound || 0) === 0 ? run.noKoStreak + 1 : 0;
    collectionRaise("critStreak", run.critStreak);
    collectionRaise("pentakillStreak", run.pentakillStreak);
    collectionRaise("noKoStreak", run.noKoStreak);
  }
  if (!collectionDirty) return;
  collectionDirty = false;
  evaluateSealUnlocks(true);
  saveCollectionProgress();
}

function evaluateSealUnlocks(announce) {
  const progress = loadCollectionProgress();
  Object.keys(SEAL_UNLOCKS).forEach((id) => {
    if (progress.unlocked.includes(id) || !ITEMS[id] || !sealUnlockMet(id)) return;
    progress.unlocked.push(id);
    if (announce) collectionToastQueue.push(id);
  });
  if (announce) showNextCollectionToast();
}

/* ---- "SEAL UNLOCKED" toast: lives outside #app so renders never touch it ---- */
function showNextCollectionToast() {
  if (collectionToastBusy || !collectionToastQueue.length) return;
  if (typeof document === "undefined" || typeof document.createElement !== "function") return; // headless (tests)
  const id = collectionToastQueue.shift();
  collectionToastBusy = true;
  const toast = document.createElement("div");
  toast.className = "collection-toast";
  toast.setAttribute("role", "status");
  // a KARMA drop ({ kind: "karma" }) or a SEAL whose achievement was met (its id)
  const item = id && typeof id === "object" ? id : null;
  toast.innerHTML = item?.kind === "karma"
    ? `
    <span class="collection-toast-karma" aria-hidden="true">+${escapeHtml(String(item.karma))}${KARMA_MARK}</span>
    <span class="collection-toast-text">
      <span class="collection-toast-kicker">Karma</span>
      <span class="collection-toast-name">${escapeHtml(item.source || "")}</span>
    </span>`
    : `
    <img class="collection-toast-sigil" src="${escapeAttr(sealSigilPath(id))}" alt="" />
    <span class="collection-toast-text">
      <span class="collection-toast-kicker">Seal unlocked</span>
      <span class="collection-toast-name">${escapeHtml(ITEMS[id]?.name || "Seal")}</span>
    </span>`;
  document.body.appendChild(toast);
  playGameSfx(item?.kind === "karma" ? "karmaGain" : "sealUnlock");
  setTimeout(() => {
    toast.classList.add("leaving");
    setTimeout(() => {
      toast.remove();
      collectionToastBusy = false;
      showNextCollectionToast();
    }, 600);
  }, 3600);
}

/* ---- the collection screen ---- */
function collectionOpen() {
  return state.mode === "menu" ? Boolean(state.menuCollectionOpen) : Boolean(state.pauseOpen && state.pauseScreen === "collection");
}

function collectionSealState(id) {
  if (isSealLocked(id)) return "locked";
  return isSealDiscovered(id) ? "discovered" : "undiscovered";
}

function collectionSections() {
  const all = collectibleSealIds();
  const listed = new Set(COLLECTION_SECTIONS.flatMap((section) => section.ids || []));
  return COLLECTION_SECTIONS.map((section) => ({
    ...section,
    ids: (section.ids || all.filter((id) => !listed.has(id))).filter((id) => all.includes(id))
  })).filter((section) => section.ids.length);
}

function collectionInfoHtml(id, pinned = false) {
  const item = ITEMS[id];
  const status = collectionSealState(id);
  if (status === "locked") {
    const rule = SEAL_UNLOCKS[id];
    const result = sealUnlockProgress(id);
    const progressText = result && result.goal > 1 ? `<div class="collection-info-progress">${formatNumber(Math.min(result.value, result.goal))} / ${formatNumber(result.goal)}</div>` : "";
    return `
      <div class="collection-info-status locked">Locked</div>
      <div class="collection-info-name">${escapeHtml(item.name)}</div>
      ${collectionBuildsHtml(id)}
      <div class="collection-info-text">${descriptionHtml(rule.text)}</div>
      ${progressText}
      ${rule.gift ? "" : `<div class="collection-info-note">Or find it in one of Jesus' Gifts.</div>`}`;
  }
  const note = status === "undiscovered" ? `<div class="collection-info-note">Not discovered yet: make it trigger in a run.</div>` : "";
  // hold Shift for the ELITE rule and the SEAL's records, like an equipped SEAL's tooltip
  const elite = splitEliteDescription(item.description || "").elite;
  const records = status === "discovered" ? sealRecordsHtml(id) : "";
  const more = elite || records;
  return `
    <div class="collection-info-top">
      <div class="collection-info-status ${status}">${status === "discovered" ? "Discovered" : "Undiscovered"}${isSealBeaten(id) ? collectionBeatenMarkHtml() : ""}</div>
      ${more ? `<div class="collection-info-shift-hint">press shift for more</div><button type="button" class="tooltip-more-button" data-tooltip-more><span class="more-label">More</span><span class="less-label">Less</span></button>` : ""}
    </div>
    <div class="collection-info-name">${escapeHtml(item.name)}</div>
    ${collectionBuildsHtml(id)}
    <div class="collection-info-text">${descriptionHtml(collectionDescription(item))}</div>
    ${elite ? `<div class="collection-info-elite">${descriptionHtml(elite)}</div>` : ""}
    ${records}
    ${note}`;
}

function collectionBuildsHtml(id) {
  const labels = sealBuilds(id).map((key) => SEAL_BUILDS.find((build) => build.key === key)?.label).filter(Boolean);
  return `<div class="collection-info-builds">${labels.map((label) => `<span>${escapeHtml(label)}</span>`).join("")}</div>`;
}

function collectionFiltersHtml(all) {
  const filter = collectionFilter();
  const tabs = [{ key: "all", label: "All" }, ...SEAL_BUILDS].map((build) => {
    const count = build.key === "all" ? all.length : all.filter((id) => sealBuilds(id).includes(build.key)).length;
    const active = build.key === filter;
    return `<button class="collection-filter${active ? " active" : ""}" type="button" data-collection-filter="${build.key}" aria-pressed="${active}">${escapeHtml(build.label)}<span class="collection-filter-count">${count}</span></button>`;
  });
  return `<nav class="collection-filters" aria-label="Filter SEALS by build">${tabs.join("")}</nav>`;
}

// filters in place, so the screen does not replay its entrance
function applyCollectionFilter(screen, filter) {
  state.collectionFilter = filter;
  if (!screen) return;
  screen.querySelectorAll("[data-collection-filter]").forEach((button) => {
    const active = button.dataset.collectionFilter === filter;
    button.classList.toggle("active", active);
    button.setAttribute("aria-pressed", String(active));
  });
  applyCollectionVisibility(screen);
  screen.querySelectorAll(COLLECTION_SELECTED).forEach((el) => el.classList.remove("selected"));
  hideCollectionInfo(screen);
  const body = screen.querySelector(".collection-body");
  if (body) body.scrollTop = 0;
}

function collectionDescription(item) {
  try {
    return descriptionWithoutElite(itemDescription(item) || item.description || "");
  } catch (error) {
    return descriptionWithoutElite(item.description || "");
  }
}

function renderCollectionScreen(from) {
  const all = collectibleSealIds();
  const unlocked = all.filter((id) => isSealUnlocked(id)).length;
  const discovered = all.filter((id) => isSealUnlocked(id) && isSealDiscovered(id)).length;
  const filter = collectionFilter();
  const slain = GOETIC_BOSS_KEYS.filter((key) => isDemonSlain(key)).length;
  const goetia = collectionTab === "goetia";
  const angels = collectionTab === "angels";
  const angelsDefeated = ARCHANGEL_KEYS.filter((key) => isArchangelDefeated(key)).length;
  const devButton = () =>
    `<button type="button" class="collection-dev-button${loadCollectionProgress().devAllDemons ? " active" : ""}" data-collection-dev-demons data-tooltip="Testing: every demon and Archangel counts as defeated, so any of them can be bound">${loadCollectionProgress().devAllDemons ? "DEV: all unlocked" : "DEV: unlock all"}</button>`;
  const tabs = [
    { key: "seals", label: "Seals" },
    { key: "goetia", label: "Ars Goetia" },
    { key: "angels", label: "Archangels" }
  ].map((tab) => {
    const active = tab.key === collectionTab;
    return `<button class="collection-tab${active ? " active" : ""}" type="button" role="tab" data-collection-tab="${tab.key}" aria-selected="${active}">${escapeHtml(tab.label)}</button>`;
  });
  const sections = collectionSections()
    .map(
      (section) => `
        <section class="collection-section collection-section-${section.key}"${section.ids.some((id) => collectionSealVisible(id)) ? "" : " hidden"}>
          <h2 class="collection-section-title">${escapeHtml(section.title)}</h2>
          <div class="collection-grid">
            ${section.ids
              .map((id) => {
                const status = collectionSealState(id);
                const wide = SATAN_SEAL_IDS.has(id) ? " wide" : "";
                const beaten = status !== "locked" && isSealBeaten(id) ? " beaten" : "";
                return `
                  <button class="collection-seal ${status}${wide}${beaten}" type="button" data-collection-seal="${id}"${collectionSealVisible(id) ? "" : " hidden"} aria-label="${escapeAttr(status === "locked" ? `Locked SEAL` : ITEMS[id].name)}">
                    <img class="collection-sigil" src="${escapeAttr(sealSigilPath(id))}" alt="" loading="lazy" draggable="false" />
                    ${status === "locked" ? `<span class="collection-lock" aria-hidden="true"></span>` : ""}
                  </button>`;
              })
              .join("")}
          </div>
        </section>`
    )
    .join("");
  return `
    <div class="collection-screen collection-from-${from}" role="dialog" aria-label="Collection">
      <header class="collection-header">
        <button class="collection-back" type="button" data-collection-back="${from}">Back</button>
        <nav class="collection-tabs" role="tablist" aria-label="Collection">${tabs.join("")}</nav>
        <div class="collection-counts" data-collection-for="seals"${goetia || angels ? " hidden" : ""}>
          <span><strong>${discovered}</strong> / ${all.length} discovered</span>
          <span><strong data-collection-count="unlocked">${unlocked}</strong> / ${all.length} unlocked</span>
        </div>
        <div class="collection-counts" data-collection-for="goetia"${goetia ? "" : " hidden"}>
          <span><strong data-collection-count="slain">${slain}</strong> / ${GOETIC_BOSS_TOTAL} defeated</span>
          <span class="collection-bound-line">${collectionBoundLine()}</span>
        </div>
        <div class="collection-counts" data-collection-for="angels"${angels ? "" : " hidden"}>
          <span><strong>${angelsDefeated}</strong> / ${ARCHANGEL_KEYS.length} defeated</span>
          <span class="collection-bound-line">${collectionBoundLine()}</span>
        </div>
      </header>
      <div class="collection-panel" data-collection-panel="seals"${goetia || angels ? " hidden" : ""}>
        ${collectionFiltersHtml(all)}
        <div class="collection-legend">
          ${collectionSearchHtml("seals")}
          ${collectionKarmaLine()}
          <span class="legend discovered" aria-hidden="true">discovered</span>
          <span class="legend undiscovered" aria-hidden="true">undiscovered</span>
          <span class="legend locked" aria-hidden="true">locked</span>
        </div>
        <div class="collection-body">${sections}${collectionEmptyHtml("seals")}</div>
      </div>
      <div class="collection-panel" data-collection-panel="goetia"${goetia ? "" : " hidden"}>
        <div class="collection-legend">
          ${collectionSearchHtml("goetia")}
          ${collectionKarmaLine()}
          <span class="legend slain" aria-hidden="true">defeated</span>
          <span class="legend unslain" aria-hidden="true">not defeated</span>
          ${devButton()}
        </div>
        <div class="collection-body">${collectionDemonsHtml()}</div>
      </div>
      <div class="collection-panel" data-collection-panel="angels"${angels ? "" : " hidden"}>
        <div class="collection-legend">
          ${collectionSearchHtml("angels")}
          ${collectionKarmaLine()}
          <span class="legend slain" aria-hidden="true">defeated</span>
          <span class="legend unslain" aria-hidden="true">not defeated</span>
          ${devButton()}
        </div>
        <div class="collection-body">${collectionArchangelsHtml()}</div>
      </div>
      <div class="collection-info" aria-live="polite"></div>
    </div>`;
}

function showCollectionInfo(button, pinned) {
  const screen = button.closest(".collection-screen");
  const info = screen?.querySelector(".collection-info");
  if (!info) return;
  const id = button.dataset.collectionSeal;
  const demon = button.dataset.collectionDemon;
  if (touchTooltipMode()) setShiftTooltipMore(false); // on the phone every SEAL opens short (More shows the rest)
  info.innerHTML = demon ? collectionDemonInfoHtml(demon, pinned) : collectionInfoHtml(id, pinned);
  info.className = `collection-info visible ${demon ? (isBossEntryDefeated(demon) ? "slain" : "unslain") : collectionSealState(id)}`;
  // a clicked, defeated demon's box holds the Bind button
  if (demon && pinned && isBossEntryDefeated(demon)) info.classList.add("interactive");
  screen.querySelectorAll(COLLECTION_SELECTED).forEach((el) => el.classList.remove("selected"));
  if (pinned) button.classList.add("selected");
  collectionInfoAnchor = button;
  positionCollectionInfo(info, button);
}

let collectionInfoAnchor = null;

// Shift shows the ELITE line, which changes the box height: keep it beside its SEAL and on screen
function repositionCollectionInfo() {
  const info = document.querySelector(".collection-screen .collection-info.visible");
  if (!info || !collectionInfoAnchor?.isConnected) return;
  positionCollectionInfo(info, collectionInfoAnchor);
}

function positionCollectionInfo(info, button) {
  // beside the seal, kept on screen
  const rect = button.getBoundingClientRect();
  const width = info.offsetWidth;
  const height = info.offsetHeight;
  let left = rect.right + 12;
  if (left + width > window.innerWidth - 8) left = rect.left - width - 12;
  left = Math.max(8, Math.min(left, window.innerWidth - width - 8));
  let top = rect.top + rect.height / 2 - height / 2;
  top = Math.max(8, Math.min(top, window.innerHeight - height - 8));
  info.style.left = `${Math.round(left)}px`;
  info.style.top = `${Math.round(top)}px`;
}

function hideCollectionInfo(screen) {
  const info = screen?.querySelector(".collection-info");
  if (info && !screen.querySelector(COLLECTION_SELECTED)) info.classList.remove("visible");
}

function closeCollection(from) {
  if (from === "menu") state.menuCollectionOpen = false;
  else state.pauseScreen = "main";
  render();
}

function bindCollectionEvents() {
  document.querySelectorAll("[data-collection-back]").forEach((button) => {
    bindOn(button, "click", () => closeCollection(button.dataset.collectionBack));
  });
  document.querySelectorAll("[data-collection-filter]").forEach((button) => {
    bindOn(button, "click", (event) => {
      event.stopPropagation();
      applyCollectionFilter(button.closest(".collection-screen"), button.dataset.collectionFilter);
    });
  });
  document.querySelectorAll("[data-collection-search]").forEach((input) => {
    const screen = input.closest(".collection-screen");
    bindOn(input, "input", () => applyCollectionSearch(screen, input.dataset.collectionSearch, input.value));
    bindOn(input, "click", (event) => event.stopPropagation());
    // typing never reaches the game's keys; Esc clears the search first, then closes the collection
    bindOn(input, "keydown", (event) => {
      if (event.key === "Escape" && !input.value) {
        input.blur();
        return;
      }
      event.stopPropagation();
      if (event.key === "Escape") {
        event.preventDefault();
        input.value = "";
        applyCollectionSearch(screen, input.dataset.collectionSearch, "");
      } else if (event.key === "Enter") {
        event.preventDefault();
        input.blur();
      }
    });
  });
  document.querySelectorAll("[data-collection-search-clear]").forEach((button) => {
    bindOn(button, "click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const tab = button.dataset.collectionSearchClear;
      const screen = button.closest(".collection-screen");
      const input = screen?.querySelector(`[data-collection-search="${tab}"]`);
      if (input) input.value = "";
      applyCollectionSearch(screen, tab, "");
      input?.focus();
    });
  });
  document.querySelectorAll("[data-collection-dev-demons]").forEach((button) => {
    bindOn(button, "click", (event) => {
      event.stopPropagation();
      toggleDevAllDemons();
      const screen = button.closest(".collection-screen");
      const body = screen?.querySelector('[data-collection-panel="goetia"] .collection-body');
      if (body) body.innerHTML = collectionDemonsHtml();
      const angelBody = screen?.querySelector('[data-collection-panel="angels"] .collection-body');
      if (angelBody) angelBody.innerHTML = collectionArchangelsHtml();
      applyCollectionVisibility(screen);
      const count = screen?.querySelector('[data-collection-for="goetia"] strong');
      if (count) count.textContent = String(GOETIC_BOSS_KEYS.filter((key) => isDemonSlain(key)).length);
      const angelCount = screen?.querySelector('[data-collection-for="angels"] strong');
      if (angelCount) angelCount.textContent = String(ARCHANGEL_KEYS.filter((key) => isArchangelDefeated(key)).length);
      screen?.querySelectorAll("[data-collection-dev-demons]").forEach((other) => {
        other.classList.toggle("active", loadCollectionProgress().devAllDemons);
        other.textContent = loadCollectionProgress().devAllDemons ? "DEV: all unlocked" : "DEV: unlock all";
      });
      hideCollectionInfo(screen);
      bindCollectionEvents();
      refreshCollectionBinding(screen);
    });
  });
  document.querySelectorAll("[data-collection-tab]").forEach((button) => {
    bindOn(button, "click", (event) => {
      event.stopPropagation();
      applyCollectionTab(button.closest(".collection-screen"), button.dataset.collectionTab);
    });
  });
  document.querySelectorAll("[data-collection-seal], [data-collection-demon]").forEach((button) => {
    bindOn(button, "pointerenter", (event) => {
      // a clicked demon keeps its box (with Bind) while the mouse travels to it
      if (button.closest(".collection-screen")?.querySelector(".collection-demon.selected")) return;
      if (event.pointerType === "mouse") showCollectionInfo(button, false);
    });
    bindOn(button, "pointerleave", (event) => {
      if (event.pointerType === "mouse") hideCollectionInfo(button.closest(".collection-screen"));
    });
    bindOn(button, "click", (event) => {
      event.stopPropagation();
      const wasSelected = button.classList.contains("selected");
      if (wasSelected) {
        button.classList.remove("selected");
        hideCollectionInfo(button.closest(".collection-screen"));
      } else {
        showCollectionInfo(button, true);
      }
    });
  });
  const screen = document.querySelector(".collection-screen");
  applyCollectionVisibility(screen);
  const info = screen?.querySelector(".collection-info");
  if (info) {
    bindOn(info, "click", (event) => {
      if (!info.classList.contains("interactive")) return;
      event.stopPropagation();
      const bind = event.target.closest?.("[data-collection-bind]");
      if (!bind) return;
      toggleBoundDemon(bind.dataset.collectionBind);
      // the pact sound from the story when a demon is bound; the SEAL ghost when it is let go
      playGameSfx(collectionBoundDemon() ? "introEvil" : "sealSellGhost");
      refreshCollectionBinding(screen);
    });
  }
  if (screen) {
    bindOn(screen, "click", () => {
      screen.querySelectorAll(COLLECTION_SELECTED).forEach((el) => el.classList.remove("selected"));
      hideCollectionInfo(screen);
    });
    screen.querySelectorAll(".collection-body").forEach((body) => {
      bindOn(body, "scroll", () => {
        screen.querySelectorAll(COLLECTION_SELECTED).forEach((el) => el.classList.remove("selected"));
        hideCollectionInfo(screen);
      });
    });
  }
}

// Esc closes the collection
document.addEventListener("keydown", (event) => {
  if (event.key !== "Escape" || !collectionOpen()) return;
  event.preventDefault();
  closeCollection(state.mode === "menu" ? "menu" : "pause");
});

/* ---- main menu: Satan opens the collection ----
   His eyes flare, a dark red bloom swells out of them over the screen, and the collection
   surfaces from it. */
function triggerMenuSatan() {
  const fig = document.querySelector(".menu-fig-satan");
  if (!fig) return;
  menuFigureTrigger.busy = true;
  setMenuFigureLit("satan");
  fig.classList.add("eyes-flare");
  playGameSfx("menuSatanOpen");
  const eyes = fig.querySelector(".fig-eyes");
  const rect = (eyes || fig).getBoundingClientRect();
  const meta = MENU_FIGURES.satan.meta;
  // between his two eyes (head-image pixels 104, 123)
  const ex = eyes ? rect.left + (rect.width * 104) / meta.head.w : rect.left + rect.width * 0.4;
  const ey = eyes ? rect.top + (rect.height * 123) / meta.head.h : rect.top + rect.height * 0.12;
  const veil = document.createElement("div");
  veil.className = "menu-satan-veil";
  veil.style.setProperty("--veil-x", `${Math.round(ex)}px`);
  veil.style.setProperty("--veil-y", `${Math.round(ey)}px`);
  document.body.appendChild(veil);
  setTimeout(() => {
    fig.classList.remove("eyes-flare");
    setMenuFigureLit(null);
    menuFigureTrigger.busy = false;
    openCollectionFromMenu();
    // keep the veil above the collection while it clears
    document.body.appendChild(veil);
    veil.classList.add("clearing");
    setTimeout(() => veil.remove(), 900);
  }, 640);
}

function openCollectionFromMenu() {
  if (state.mode !== "menu") return;
  state.menuCollectionOpen = true;
  render();
}

/* ---------- KARMA: the currency kept between runs ----------
   Earned in real arcade runs (collectionCounts), kept in the collection progress (progress.karma):
     beating the game (the 8 main BOSSES)            +KARMA_GAME_BEATEN
     the nth main BOSS beaten in a run (n = 1..8)    1 KARMA at n x KARMA_MAIN_BOSS_STEP (Petros and Pavlos
                                                     are one BOSS: it rolls when both are down)
     a Goetic demon (or YOU in its place)            1 KARMA at KARMA_GOETIC_CHANCE
     an Archangel (or YOU in its place)              KARMA_ARCHANGEL_AMOUNT at KARMA_ARCHANGEL_CHANCE
     Honorable Death: dying after defeating          +KARMA_HONORABLE_DEATH
     KARMA_HONORABLE_DEATH_BOSSES or more BOSSES
   Spent on Jesus' Gifts (09-gifts.js). */
const KARMA_GAME_BEATEN = 8;
const KARMA_MAIN_BOSS_STEP = 0.1;
const KARMA_GOETIC_CHANCE = 0.9;
const KARMA_ARCHANGEL_CHANCE = 1;
const KARMA_ARCHANGEL_AMOUNT = 3;
const KARMA_HONORABLE_DEATH = 1;
const KARMA_HONORABLE_DEATH_BOSSES = 4; // any BOSSES: main ones (the twins are one), demons, Archangels

// KARMA's mark (the Spiral of Return, --karma-spiral in styles.css), drawn after a number like the SIN coin
const KARMA_MARK = `<span class="karma-mark" role="img" aria-label="KARMA"></span>`;

function karmaBalance() {
  return Math.max(0, Math.floor(Number(loadCollectionProgress().karma) || 0));
}

// DEV (testing): infinite KARMA; gifts cost nothing and the real balance is kept for when it is off
function karmaInfinite() {
  return loadCollectionProgress().devInfiniteKarma === true;
}

function karmaCanPay(price) {
  return karmaInfinite() || karmaBalance() >= price;
}

function toggleDevInfiniteKarma() {
  const progress = loadCollectionProgress();
  progress.devInfiniteKarma = !progress.devInfiniteKarma;
  saveCollectionProgress();
}

function karmaGain(amount, source) {
  const gained = Math.max(0, Math.floor(Number(amount) || 0));
  if (!gained || !collectionCounts()) return 0;
  const progress = loadCollectionProgress();
  progress.karma = karmaBalance() + gained;
  const run = collectionRun();
  run.karma = (run.karma || 0) + gained;
  saveCollectionProgress();
  addLog(`${source}: +${gained} KARMA.`);
  collectionToastQueue.push({ kind: "karma", karma: gained, source });
  showNextCollectionToast();
  return gained;
}

function karmaRoll(chance, source, amount = 1) {
  if (!collectionCounts() || !(chance > 0)) return 0;
  return Math.random() < chance ? karmaGain(amount, source) : 0;
}

// a BOSS fell (from collectionNoteElimination, real runs only)
function collectionNoteKarmaDrop(bot) {
  if (!bot?.isBoss) return;
  if (bot.uniqueKey) {
    const run = collectionRun();
    const beaten = uniqueBossesBeatenThisRun();
    if (beaten <= (run.karmaRolled || 0)) return;
    run.karmaRolled = beaten;
    karmaRoll(beaten * KARMA_MAIN_BOSS_STEP, bot.uniqueKey === "pavlos" || bot.uniqueKey === "petros" ? "Petros and Pavlos" : bot.name || "BOSS");
    return;
  }
  const angel = bot.archangelKey || (bot.shadowOf && ARCHANGEL_BY_KEY[bot.shadowOf]);
  if (angel) karmaRoll(KARMA_ARCHANGEL_CHANCE, bot.name || "Archangel", KARMA_ARCHANGEL_AMOUNT);
  else if (bot.goeticKey || bot.shadowOf) karmaRoll(KARMA_GOETIC_CHANCE, bot.name || "Demon");
}

// Honorable Death: the run ends in death after defeating KARMA_HONORABLE_DEATH_BOSSES or more BOSSES (from finishGameOverRound)
function collectionNoteHonorableDeath() {
  if (!collectionCounts()) return 0;
  const run = collectionRun();
  if (run.honorableDeath || (Number(state.bossKills) || 0) < KARMA_HONORABLE_DEATH_BOSSES) return 0;
  run.honorableDeath = true;
  return karmaGain(KARMA_HONORABLE_DEATH, "Honorable Death");
}

function collectionKarmaLine() {
  // the big counter at the right end of the search row, on every tab
  return `<div class="collection-karma-line" data-tooltip="KARMA: earned by beating BOSSES and the game, and by an Honorable Death (dying after 4 BOSSES); spent on Jesus' Gifts"><span class="collection-karma-word">Karma</span><strong>${karmaInfinite() ? "∞" : formatNumber(karmaBalance())}</strong>${KARMA_MARK}</div>`;
}
"use strict";

/* ---------- Jesus' Gifts: KARMA packs ----------
   Main menu: click Jesus (or Options > Jesus' Gifts). Three gifts, each opens into one unlockable by its
   own odds (GIFT_PACKS, in %; a pack's odds are weights, so they need not add up to exactly 100):
     a kind is drawn by the odds, then one item of that kind at random. Ars Goetia: any of the 72 demons
     (it then counts as defeated in the Collection and can be bound); the other kinds are SEALS by
     Collection section (GIFT_KINDS).
   Owned (a defeated demon, an unlocked or never-locked SEAL): a duplicate, half the price back.
   The Planetary Seals, the Trinity and Anael are locked from the start and only gifts unlock them
   (GIFT_ONLY_SEAL_IDS in 09-collection.js); the other locked SEALS can also still be earned by their
   achievement. Opening: a face-down card rises out of the vessel and turns over (see startGiftOpening). */
const GIFT_PACKS = [
  { key: "myrrh", name: "Myrrh", price: 44, odds: { goetia: 57, planet: 25, archangel: 10, boss: 4, apocalypse: 2.001, trinity: 1.333, satan: 0.666 } },
  { key: "frankincense", name: "Frankincense", price: 88, odds: { goetia: 36, planet: 35, archangel: 15, boss: 8, apocalypse: 4.001, trinity: 1.333, satan: 0.666 } },
  { key: "gold", name: "Gold", price: 166, odds: { goetia: 5, planet: 40, archangel: 25, boss: 18, apocalypse: 10, trinity: 1.333, satan: 0.666 } }
];
// heat: how red the opening is for this kind, 0 (bone white) to 1 (blood red): the rarer, the redder
const GIFT_KINDS = [
  { key: "goetia", label: "Ars Goetia demon", heat: 0 },
  { key: "planet", label: "Planetary Seal", sections: ["saturn", "artifact", "poison"], heat: 0.12 },
  { key: "archangel", label: "Archangel Seal", sections: ["archangel"], heat: 0.3 },
  { key: "boss", label: "Boss Seal", sections: ["bosses"], heat: 0.5 },
  { key: "apocalypse", label: "Apocalypse Seal", sections: ["apocalypse"], heat: 0.7 },
  { key: "trinity", label: "Trinity Seal", sections: ["trinity"], heat: 0.85 },
  { key: "satan", label: "Seal of Satan", sections: ["satan"], heat: 1 }
];
const GIFT_HEAT_COLD = [233, 227, 214]; // bone white
const GIFT_HEAT_HOT = [220, 42, 47]; // the game's red

// the opening's colours for a kind: CSS custom properties, "r, g, b" so rgba() can use them
function giftHeatStyle(kindKey) {
  const heat = Math.max(0, Math.min(1, Number(giftKind(kindKey)?.heat) || 0));
  const mix = (amount) => GIFT_HEAT_COLD.map((cold, i) => Math.round(cold + (GIFT_HEAT_HOT[i] - cold) * amount)).join(", ");
  return `--heat: ${heat}; --heat-rgb: ${mix(heat)}; --heat-text-rgb: ${mix(Math.max(0, (heat - 0.4) / 0.6))}`;
}
const GIFT_REFUND_SHARE = 0.5;
const GIFT_RARE_ODDS = 5; // odds under this show in red
// ms: the gift's own card turns face down, travels to the centre, holds (one extra pulse per rarity step), then turns over
const GIFT_OPEN_TIMING = { turn: 440, move: 560, hold: 300, beat: 380, flip: 440 };

// rarer gifts hold longer: Ars Goetia and Planetary none, up to 3 extra pulses for Trinity and Satan
function giftOpenBeats(kindKey) {
  return Math.round(Math.max(0, Math.min(1, Number(giftKind(kindKey)?.heat) || 0)) * 3);
}

function giftPack(key) {
  return GIFT_PACKS.find((pack) => pack.key === key) || null;
}

function giftKind(key) {
  return GIFT_KINDS.find((kind) => kind.key === key) || null;
}

// what one kind can give: demon keys, or SEAL ids
function giftKindItems(kindKey) {
  if (kindKey === "goetia") return GOETIC_BOSS_KEYS.slice();
  const kind = giftKind(kindKey);
  if (!kind) return [];
  return COLLECTION_SECTIONS.filter((section) => kind.sections.includes(section.key))
    .flatMap((section) => section.ids || [])
    .filter((id) => ITEMS[id] && !REMOVED_PASSIVE_IDS.has(id));
}

function giftRefund(pack) {
  return Math.floor((pack?.price || 0) * GIFT_REFUND_SHARE);
}

// a kind by the pack's odds, then one of its items
function rollGift(pack) {
  const entries = GIFT_KINDS.map((kind) => [kind.key, Math.max(0, Number(pack.odds[kind.key]) || 0)]).filter(([key, weight]) => weight > 0 && giftKindItems(key).length);
  const total = entries.reduce((sum, [, weight]) => sum + weight, 0);
  let roll = Math.random() * total;
  let kindKey = entries[entries.length - 1][0];
  for (const [key, weight] of entries) {
    if (roll < weight) { kindKey = key; break; }
    roll -= weight;
  }
  const items = giftKindItems(kindKey);
  const item = items[Math.min(items.length - 1, Math.floor(Math.random() * items.length))];
  return { kind: kindKey, item };
}

function giftAlreadyOwned(kindKey, item) {
  const progress = loadCollectionProgress();
  if (kindKey === "goetia") return progress.slain.includes(item);
  return !SEAL_UNLOCKS[item] || progress.unlocked.includes(item);
}

// buy and open a gift: pays, draws, unlocks or refunds. Returns what came out, or { error }.
function openGift(packKey) {
  const pack = giftPack(packKey);
  if (!pack) return { error: "unknown" };
  if (!karmaCanPay(pack.price)) return { error: "karma" };
  const progress = loadCollectionProgress();
  // DEV infinite KARMA: free, and the real balance is left alone
  const free = karmaInfinite();
  if (!free) progress.karma = karmaBalance() - pack.price;
  const { kind, item } = rollGift(pack);
  const duplicate = giftAlreadyOwned(kind, item);
  const refund = duplicate ? giftRefund(pack) : 0;
  if (duplicate && !free) progress.karma += refund;
  else if (kind === "goetia") progress.slain.push(item);
  else progress.unlocked.push(item);
  saveCollectionProgress();
  const spec = kind === "goetia" ? GOETIC_BOSS_BY_KEY[item] : null;
  return {
    pack: pack.key,
    kind,
    item,
    duplicate,
    refund,
    name: spec ? spec.name : ITEMS[item]?.name || item,
    image: spec ? demonThumbPath(spec) : sealSigilPath(item)
  };
}

/* ---- the screen ---- */
function giftsOpen() {
  return state.mode === "menu" && Boolean(state.menuGiftsOpen);
}

function openGiftsFromMenu() {
  if (state.mode !== "menu") return;
  state.menuGiftsOpen = true;
  render();
}

// redraw just the Gifts screen: a full menu render rebuilds the page and would fade the screen in again
function refreshGiftsScreen() {
  const screen = document.querySelector(".gifts-screen");
  if (!screen || !giftsOpen()) {
    render();
    return;
  }
  const holder = document.createElement("div");
  holder.innerHTML = renderGiftsScreen().trim();
  const next = holder.firstElementChild;
  next.classList.add("settled");
  // the element under the mouse is replaced and never fires mouseleave: drop its tooltip, bind the new ones
  hideFloatingTooltip();
  screen.replaceWith(next);
  bindGiftsEvents();
  bindFloatingTooltips(next);
}

function closeGifts() {
  state.menuGiftsOpen = false;
  render();
}

// the three gifts the Magi carried, ink drawings with red accents (assets/ui/gifts/, 640px, one shared crop
// so they sit at the same scale on the cards)
function giftVesselSvg(key) {
  return `<img class="gift-vessel" src="assets/ui/gifts/${escapeAttr(key)}.png" alt="" draggable="false" />`;
}

function giftKindIcon(kindKey) {
  if (kindKey === "goetia") return demonThumbPath(GOETIC_BOSS_SPECS[0]);
  return sealSigilPath(giftKindItems(kindKey)[0]);
}

function giftOddsHtml(pack) {
  const rows = GIFT_KINDS.map((kind) => {
    const odds = Number(pack.odds[kind.key]) || 0;
    const text = Number.isInteger(odds) ? String(odds) : String(+odds.toFixed(3));
    return `<span class="gift-odds-row${odds < GIFT_RARE_ODDS ? " rare" : ""}"><img src="${escapeAttr(giftKindIcon(kind.key))}" alt="" draggable="false" /><span>${escapeHtml(kind.label)}</span><b>${text}%</b></span>`;
  }).join("");
  return `<span class="gift-odds">${rows}</span>`;
}

// three framed cards beside Jesus: the gift, its price and all its odds in view; click a card to open it
function renderGiftsScreen() {
  const balance = karmaBalance();
  const infinite = karmaInfinite();
  const cards = GIFT_PACKS.map((pack) => {
    const can = karmaCanPay(pack.price);
    return `
      <button type="button" class="gift-card gift-${pack.key}${can ? "" : " cant"}" data-gift-open="${pack.key}" aria-label="Open ${escapeAttr(pack.name)} for ${pack.price} KARMA"${can ? "" : ' aria-disabled="true"'}>
        <span class="gift-card-art">${giftVesselSvg(pack.key)}</span>
        <span class="gift-name">${escapeHtml(pack.name)}</span>
        <span class="gift-price${can ? "" : " cant"}">${formatNumber(pack.price)}${KARMA_MARK}</span>
        ${giftOddsHtml(pack)}
        ${can ? "" : `<span class="gift-card-open">You need ${formatNumber(pack.price - balance)}${KARMA_MARK} more</span>`}
      </button>`;
  }).join("");
  return `
    <div class="gifts-screen" role="dialog" aria-label="Jesus' Gifts">
      <svg width="0" height="0" style="position:absolute" aria-hidden="true"><defs><filter id="giftRough" x="-10%" y="-10%" width="120%" height="120%"><feTurbulence type="fractalNoise" baseFrequency="0.05" numOctaves="2" seed="7"/><feDisplacementMap in="SourceGraphic" scale="2.6"/></filter></defs></svg>
      <img class="gifts-jesus" src="assets/ui/jesus.png" alt="" draggable="false" />
      <button class="collection-back gifts-back" type="button" data-gifts-back>Back</button>
      <h1 class="gifts-title">Jesus' Gifts</h1>
      <div class="gifts-karma">${collectionKarmaLine()}<button type="button" class="collection-dev-button gifts-dev${infinite ? " active" : ""}" data-gifts-dev-karma data-tooltip="Testing: KARMA never runs out and gifts cost nothing; off again shows your real KARMA">${infinite ? "DEV: ∞ Karma on" : "DEV: ∞ Karma"}</button></div>
      <div class="gifts-cards">${cards}</div>
    </div>`;
}

/* ---- opening: the gift's card turns face down (a cross on its back), travels to the centre,
   holds, and turns over to show the drop ----
   Red from the start for rare drops (the cross and the frame take the kind's heat), and rarer
   drops hold longer. The moving card is position: fixed and placed in px from the clicked card
   to a hidden slot in the centre. Lives outside the render cycle (data-morph-keep). */
let giftOpening = null;

const GIFT_CARD_CROSS = '<svg class="gift-back-cross" viewBox="0 0 60 90" aria-hidden="true"><g filter="url(#giftRough)" fill="none" stroke="currentColor" stroke-width="5" stroke-linecap="round"><path d="M30 8v74M12 30h36"/></g></svg>';

function placeGiftCard(card, rect) {
  if (!card || !rect) return;
  card.style.left = `${rect.left}px`;
  card.style.top = `${rect.top}px`;
  card.style.width = `${rect.width}px`;
  card.style.height = `${rect.height}px`;
}

function startGiftOpening(packKey) {
  if (giftOpening) return;
  const screen = document.querySelector(".gifts-screen");
  const result = openGift(packKey);
  if (result.error) {
    screen?.querySelectorAll(".gift-opening").forEach((leftover) => leftover.remove());
    return;
  }
  const pack = giftPack(packKey);
  const kind = giftKind(result.kind);
  const beats = giftOpenBeats(result.kind);
  const source = screen?.querySelector(`.gift-card[data-gift-open="${pack.key}"]`);
  const again = Boolean(screen?.querySelector(".gift-opening"));
  const overlay = document.createElement("div");
  overlay.className = `gift-opening${again ? " again" : ""}`;
  overlay.setAttribute("style", `${giftHeatStyle(result.kind)}; --beats: ${beats}; --beat: ${GIFT_OPEN_TIMING.beat}ms`);
  overlay.setAttribute("data-morph-keep", "");
  overlay.setAttribute("role", "status");
  overlay.innerHTML = `
    <div class="gift-flip">
      <div class="gift-flip-slot"></div>
      <div class="gift-reveal-actions">
        <button type="button" class="collection-bind-button" data-gift-again${karmaCanPay(pack.price) ? "" : " disabled"}>Again · ${formatNumber(pack.price)}${KARMA_MARK}</button>
        <button type="button" class="collection-bind-button" data-gift-continue>Continue</button>
      </div>
    </div>
    <div class="gift-flip-card">
      <div class="gift-face gift-shop-face"></div>
      <div class="gift-face gift-back">${GIFT_CARD_CROSS}</div>
      <div class="gift-face gift-front">
        <span class="gift-reveal-kind">${escapeHtml(kind?.label || "")}</span>
        <img class="gift-reveal-art${result.kind === "goetia" ? " demon" : ""}" src="${escapeAttr(result.image)}" alt="" draggable="false" />
        <span class="gift-reveal-name">${escapeHtml(result.name)}</span>
        <span class="gift-reveal-status${result.duplicate ? " dup" : ""}">${result.duplicate ? `Owned · +${formatNumber(result.refund)}${KARMA_MARK}` : "Unlocked"}</span>
      </div>
    </div>`;
  // Again: the new opening takes over from the old one without fading the screen in again
  screen?.querySelectorAll(".gift-opening").forEach((old) => old.remove());
  (screen || document.body).appendChild(overlay);
  screen?.querySelectorAll(".collection-karma-line").forEach((line) => { line.outerHTML = collectionKarmaLine(); });
  const card = overlay.querySelector(".gift-flip-card");
  const slot = overlay.querySelector(".gift-flip-slot");
  const toCentre = () => placeGiftCard(card, slot.getBoundingClientRect());
  const onResize = () => { if (!overlay.classList.contains("phase-turn")) toCentre(); };
  window.addEventListener("resize", onResize);
  giftOpening = { overlay, pack: pack.key, timers: [], source, onResize };
  const reduced = typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
  const set = (phase) => {
    overlay.classList.remove("phase-turn", "phase-move", "phase-hold", "phase-flip", "phase-reveal");
    overlay.classList.add(phase);
  };
  const reveal = () => {
    set("phase-reveal");
    playGameSfx(result.duplicate ? "sell" : "karmaUnlock");
  };
  const at = (ms, fn) => giftOpening.timers.push(setTimeout(fn, ms));
  const hold = GIFT_OPEN_TIMING.hold + beats * GIFT_OPEN_TIMING.beat;
  if (reduced) {
    toCentre();
    reveal();
  } else if (source) {
    // the card you clicked turns over where it stands, then travels to the centre
    const clone = source.cloneNode(true);
    clone.removeAttribute("data-gift-open");
    clone.setAttribute("tabindex", "-1");
    clone.setAttribute("aria-hidden", "true");
    overlay.querySelector(".gift-shop-face").appendChild(clone);
    placeGiftCard(card, source.getBoundingClientRect());
    source.classList.add("gift-card-away");
    set("phase-turn");
    playGameSfx("introBurn");
    at(GIFT_OPEN_TIMING.turn, () => { set("phase-move"); toCentre(); });
    at(GIFT_OPEN_TIMING.turn + GIFT_OPEN_TIMING.move, () => set("phase-hold"));
    at(GIFT_OPEN_TIMING.turn + GIFT_OPEN_TIMING.move + hold, () => set("phase-flip"));
    at(GIFT_OPEN_TIMING.turn + GIFT_OPEN_TIMING.move + hold + GIFT_OPEN_TIMING.flip, reveal);
  } else {
    toCentre();
    set("phase-hold");
    playGameSfx("introBurn");
    at(hold, () => set("phase-flip"));
    at(hold + GIFT_OPEN_TIMING.flip, reveal);
  }
  overlay.addEventListener("click", (event) => {
    event.stopPropagation();
    if (!overlay.classList.contains("phase-reveal")) return;
    if (event.target.closest("[data-gift-again]")) {
      const next = giftOpening?.pack;
      endGiftOpening(false, true);
      if (next) startGiftOpening(next);
      return;
    }
    if (event.target.closest("[data-gift-continue]")) endGiftOpening(true);
  });
}

// keepOverlay: Again leaves the dark overlay up until the next opening replaces it
function endGiftOpening(rerender, keepOverlay = false) {
  if (!giftOpening) return;
  giftOpening.timers.forEach(clearTimeout);
  window.removeEventListener("resize", giftOpening.onResize);
  giftOpening.source?.classList.remove("gift-card-away");
  if (!keepOverlay) giftOpening.overlay.remove();
  giftOpening = null;
  if (rerender) refreshGiftsScreen();
}

function bindGiftsEvents() {
  document.querySelectorAll("[data-gifts-back]").forEach((button) => bindOn(button, "click", () => closeGifts()));
  document.querySelectorAll("[data-gift-open]").forEach((button) => {
    bindOn(button, "click", () => {
      if (giftOpening || !karmaCanPay(giftPack(button.dataset.giftOpen)?.price ?? Infinity)) return;
      startGiftOpening(button.dataset.giftOpen);
    });
  });
  document.querySelectorAll("[data-gifts-dev-karma]").forEach((button) => {
    bindOn(button, "click", () => {
      if (giftOpening) return;
      toggleDevInfiniteKarma();
      refreshGiftsScreen();
    });
  });
}

// Esc: leaves the opening, then the screen
document.addEventListener("keydown", (event) => {
  if (event.key !== "Escape" || !giftsOpen()) return;
  event.preventDefault();
  if (giftOpening) {
    if (giftOpening.overlay.classList.contains("phase-reveal")) endGiftOpening(true);
    return;
  }
  closeGifts();
});
/* ---------- Satan's Pact: one deal with the Devil per run ----------
   The DEAL button under Pause (it pulses slowly to red until you open the deal once in the run, and
   fast while you are under 25% SOUL). Satan walks in like in the story (same box over the SEAL slots, same typing). You type
   what you want; he names his price; YES signs, NO throws the chance away for the rest of the run.
   Asking for something he will not give, or gibberish, does not use the chance up. If he turns down a
   SEAL, the deal stays locked until your next BOSS kill.

   WHAT HE SAYS: every line is in SATAN_DEAL_LINES and SATAN_DEAL_PRICE_TEXT right below. Edit them
   freely. The first word of each line is who speaks (satan / you). Words in {CAPS} are filled in by the
   game: {ITEM} {COUNT} {SEAL} {OTHER} {DEMON} {NAME} {N} {ASKED} {PRICE} {Q}. {SIN} draws the SIN icon.
   Each key holds a list of lines said one after another.

   The rules and prices (decided Nov 2026, see the "Satan's Pact Prices" page):
   - 1 ARTIFACT: SOUL = 0.5 x its Devil's Offerings price (at least 2), or 3 x that price in SIN, or
     only 1 ARTIFACT use a round for 3 rounds; one of the three at random among the ones you can pay.
   - 2 to 4 copies: Devil's Offerings closed for (copies) rounds, or SOUL = 0.5 x all their prices.
   - ELITE (every SEAL slot open): the SEAL you name weighs 4, every other SEAL you own weighs 1. If it
     lands on yours: next BOSS +50% SOUL, or lose a random SEAL. If it lands on another: next BOSS +30%.
   - Goetic SEAL (every SEAL slot open): 50% he says yes (80% if you have slain that demon), never while
     its BOSS lives. Price: a random SEAL of yours + SOUL = the SEAL's price + 20% of your SIN; if the
     SOUL would kill you, +50% damage taken for 3 rounds instead of the SOUL.
   - Heal up to 5: next BOSS +10% SOUL per SOUL asked.
   - N SIN: next BOSS +2N% SOUL and no BOSS BOUNTY; above 20, 1 SOUL per 3 SIN over.
   - Kill a non-boss DAMNED: no ARTIFACTS for a round, and Satan keeps its BOUNTY.
   - +1 / +2 ARTIFACT uses this round: then only 1 use a round for 2 (or 5) rounds (0 with Seal of Orobas).
   - Cheat death: back with 1 SOUL once; when it happens he takes a random SEAL, half your SIN, or the
     next BOSS comes with +50% SOUL.
   - Seal of Satan: only with every SEAL slot open and empty. Free.
   Every number is x0.8 to x1.25 (most often near x1). 4+ SEALS sharing a build with the SEAL asked
   for (ELITE / SEAL) make the price x1.5. A SOUL price never takes you below 1 SOUL.
   "This round" means the current round during guess / ARTIFACTS, the next round from the results on. */

const SATAN_DEAL_LINES = {
  // first time you open the deal in a run
  open: [
    ["satan", "Well well, look who came crawling to me. Things not going so great down there, flesh puppet?"],
    ["satan", "I'm feeling generous today. One deal, just one, so make it count. Tell me what you want and I'll tell you what it costs."]
  ],
  // every time after that, until the deal is made
  openAgain: [["satan", "Back again? Spit it out, what do you want?"]],
  // the box under his line, where you type
  askPlaceholder: "Tell him what you want...",

  // asked for something he does not understand ({Q} is what you typed)
  gibberish: [["satan", "\"{Q}\"? Is this supposed to be a joke? I don't have time for nonsense. Make a reasonable request before eternity catches up with you little puppet."]],
  // things he never gives
  angel: [["satan", "Feathers? You come to ME and ask for feathers? Go pray to your little Archangels, see how far that gets you."]],
  trinity: [["satan", "That one belongs to the big guy upstairs. Even I don't touch his toys."]],
  saturn: [["satan", "Solomon's pentacles? The trinkets he used to chain my demons? Ask me that again and I'll chain YOU."]],
  apocalypse: [["satan", "The SEALS of the end times are opened by the Lamb, not by me. Bah. Lambs."]],
  locked: [["satan", "That one isn't in my vault yet. Earn it first, then we talk."]],
  bound: [["satan", "You already have that demon on a leash, and for free. Greedy little thing, aren't you?"]],
  notDemon: [["satan", "That's not one of my demons. I only deal in what's mine."]],
  // SEAL or ELITE before every SEAL slot is open
  tooEarly: [["satan", "My demons don't serve nobodies. Open every SEAL slot you can, then come begging."]],
  sealOwned: [["satan", "You already carry {SEAL}. If you want it stronger, ask for an ELITE."]],
  eliteWhich: [["satan", "An ELITE on what? Name the SEAL, genius."]],
  eliteNotOwned: [["satan", "You can't make stronger something you don't even have."]],
  eliteCannot: [["satan", "{SEAL} can't get any stronger. Not even I can change that."]],
  demonBusy: [["satan", "{DEMON} is a little busy trying to kill you right now. Ask me later."]],
  // the 50% / 80% roll says no: the deal locks until the next BOSS kill
  sealRefused: [
    ["satan", "{DEMON} doesn't feel like serving you. Can't say I blame him."],
    ["satan", "Go kill another BOSS. Maybe I'll be in a better mood after that."]
  ],
  noRoomSeal: [["satan", "There's no room for another demon on you, and I'm not doing your tidying for you."]],
  handsFull: [["satan", "Your hands are full of junk already. Make some room before you ask for more."]],
  fullHealth: [["satan", "You're not even bleeding. Come back when it hurts."]],
  sinHowMuch: [["satan", "How much SIN{SIN}? Give me a number."]],
  killWho: [["satan", "Kill who? Give me a name."]],
  killBoss: [["satan", "BOSSES you deal with yourself. I only take the small fry."]],
  satanSealNotEmpty: [["satan", "My own SEAL? Ha! It doesn't share a home with other demons. Empty every slot, then ask me again."]],
  cheatDeathAlready: [["satan", "I already promised to drag you back once. Don't push your luck."]],

  // offers: the last line of an offer is followed by YES / NO
  artifact: [["satan", "{ITEM}? Cheap trinket. Fine, it's yours for {PRICE}."]],
  artifacts: [["satan", "{COUNT} of {ITEM}? Somebody's planning a party. That will be {PRICE}."]],
  artifactsCapped: [["satan", "Four. That's all I'll part with."]],
  elite: [["satan", "An ELITE on {SEAL}? Done. It'll cost you {PRICE}."]],
  eliteOther: [
    ["satan", "Hmm. My demons tell me it's {OTHER} that's ready to grow, not {SEAL}."],
    ["satan", "If you want it on {OTHER}, it's {PRICE}."]
  ],
  seal: [["satan", "{DEMON} agrees to serve you. For that, I take {PRICE}."]],
  heal: [["satan", "A little blood transfusion? {N} SOUL, and in return {PRICE}."]],
  healTooMuch: [
    ["satan", "{ASKED} SOUL? HAHAHA! You must be out of your mind."],
    ["satan", "I'll give you {N}, and you'll thank me for it. In return, {PRICE}."]
  ],
  sin: [["satan", "{N} SIN{SIN}, coming right up. In return, {PRICE}."]],
  sinCapped: [["satan", "That much would kill you, and a dead puppet pays nothing. {N} SIN{SIN} is all you can afford. In return, {PRICE}."]],
  kill: [["satan", "{NAME}? Never liked that one. Consider it done, but {PRICE}."]],
  uses: [["satan", "{N} more ARTIFACT use this round? Sure. Then {PRICE}."]],
  usesTwo: [["satan", "Two more ARTIFACT uses this round? Greedy. Then {PRICE}."]],
  usesTooMany: [["satan", "Two, or nothing. Don't get greedy with me."]],
  cheatDeath: [
    ["satan", "Cheating death, now that's my kind of deal. Next time you drop, I'll drag you back up."],
    ["satan", "The price? I'll pick it when you're lying on the floor."]
  ],
  satanSeal: [["satan", "My own SEAL, on an empty soul? You know what, I like you. No charge."]],
  // the question after every offer (said on the same line as the price)
  question: [["satan", "Do we have a deal, flesh puppet?"]],

  // after YES
  signed: [["satan", "Pleasure doing business with you."]],
  // after NO: the chance is gone for this run
  refused: [["satan", "Your loss. Don't come crawling back, you had your chance."]]
};

// how each part of a price reads inside {PRICE} ({N} = amount, {M} = rounds, {SEAL} = a SEAL's name)
const SATAN_DEAL_PRICE_TEXT = {
  hp: "{N} of your SOUL",
  sin: "{N} SIN{SIN}",
  useCap: "only one ARTIFACT a round for the next {M} rounds",
  useCapZero: "no ARTIFACTS at all for the next {M} rounds",
  shopClosed: "my Offerings closed to you for {M} rounds",
  bossHealth: "the next BOSS walks in with {N}% more SOUL",
  bossBounty: "its BOSS BOUNTY goes to me",
  loseSeal: "your {SEAL}",
  damageTaken: "{N}% more pain for {M} rounds",
  noArtifacts: "no ARTIFACTS for a round",
  keepBounty: "its BOUNTY goes to me",
  nothing: "nothing at all"
};

// the YES / NO buttons, and the buttons under the box where you type
const SATAN_DEAL_BUTTONS = { yes: "Yes", no: "No", ask: "Ask", leave: "Leave" };

/* ---- numbers ---- */
const SATAN_DEAL_ROLL_MIN = 0.8;
const SATAN_DEAL_ROLL_MAX = 1.25;
const SATAN_DEAL_LOW_HP = 0.25; // under this share of max SOUL the DEAL button pulses fast
const SATAN_DEAL_PULSE_MS = 6000; // one slow fade to red and back (keep equal to the pact-calling animation in styles.css)
const SATAN_DEAL_PULSE_FAST_MS = 1600; // the same under 25% SOUL (.pact-urgent in styles.css)
const SATAN_DEAL_BUILD_STACK = 4; // this many SEALS sharing a build with the SEAL asked for...
const SATAN_DEAL_BUILD_FACTOR = 1.5; // ...make the price this much higher
const SATAN_DEAL_SEAL_ACCEPT = 0.5;
const SATAN_DEAL_SEAL_ACCEPT_SLAIN = 0.8;
const SATAN_DEAL_MAX_COPIES = 4;
const SATAN_DEAL_MAX_HEAL = 5;
const SATAN_DEAL_SOURCE = "Satan's Pact";

function satanPactFresh() {
  return {
    used: false, // signed or refused: the chance is gone
    outcome: null, // "signed" | "refused"
    request: "", // what was signed, for the records
    opened: false, // opened at least once (stops the pulse)
    lockedAtBossKills: null, // a refused SEAL: locked until state.bossKills goes past this
    offer: null, // the offer waiting for YES / NO (kept in the save)
    useBonus: null, // { round, n }
    useCaps: [], // [{ from, to, cap }]
    shopClosed: null, // { from, to }
    damageTaken: null, // { from, to, pct }
    bossDebt: null, // { healthPct, zeroBounty, pairGroupId }
    cheatDeath: false
  };
}

function satanPact() {
  if (!state.pact || typeof state.pact !== "object") state.pact = satanPactFresh();
  return state.pact;
}

/* ---- availability ---- */
function satanPactLocked() {
  const pact = satanPact();
  return pact.lockedAtBossKills !== null && pact.lockedAtBossKills !== undefined && state.bossKills <= pact.lockedAtBossKills;
}

function satanPactAvailable() {
  const pact = satanPact();
  return state.mode === "arcade" && !state.gameOver && !pact.used && !satanPactLocked();
}

function satanPactCanOpenNow() {
  return satanPactAvailable() && !introActive() && !roundRevealAnimationActive() && !state.pendingActive && state.player.hp > 0;
}

// DEAL pulses slowly until you open it once in the run; under 25% SOUL it pulses fast
function satanPactPulseActive() {
  const pact = satanPact();
  return satanPactAvailable() && !pact.opened && !introActive() && state.player.hp > 0;
}

function satanPactPulseUrgent() {
  return satanPactPulseActive() && state.player.hp < playerMaxHp() * SATAN_DEAL_LOW_HP;
}

// the round "this round" means: the current one before READY, the next one from the results on
function satanPactEffectRound() {
  return ["guess", "active"].includes(state.stage) ? state.round : state.round + 1;
}

function satanPactRoll() {
  // triangular: most rolls land near x1, the ends are rare
  const lo = SATAN_DEAL_ROLL_MIN;
  const hi = SATAN_DEAL_ROLL_MAX;
  const mode = 1;
  const u = Math.random();
  const c = (mode - lo) / (hi - lo);
  return u < c ? lo + Math.sqrt(u * (hi - lo) * (mode - lo)) : hi - Math.sqrt((1 - u) * (hi - lo) * (hi - mode));
}

/* ---- effects the rest of the game asks about ---- */
function satanPactUseLimit(base) {
  const pact = state.pact;
  if (!pact || state.mode !== "arcade") return base;
  const round = state.round;
  let limit = base;
  if (pact.useBonus && pact.useBonus.round === round) limit += pact.useBonus.n;
  (pact.useCaps || []).forEach((cap) => {
    if (round >= cap.from && round <= cap.to) limit = Math.min(limit, cap.cap);
  });
  return Math.max(0, limit);
}

function satanPactShopClosed() {
  const closed = state.pact?.shopClosed;
  return Boolean(closed && state.mode === "arcade" && state.round >= closed.from && state.round <= closed.to);
}

function satanPactDamageTakenMultiplier() {
  const curse = state.pact?.damageTaken;
  if (!curse || state.mode !== "arcade" || state.round < curse.from || state.round > curse.to) return 1;
  return 1 + curse.pct / 100;
}

// a new BOSS pays the debt: more SOUL, and maybe no BOSS BOUNTY (both of a pair, Petros and Pavlos)
function satanPactApplyBossDebt(bot) {
  const pact = state.pact;
  const debt = pact?.bossDebt;
  if (!debt || !bot?.isBoss || bot.immortal || state.mode !== "arcade") return;
  if (debt.pairGroupId && bot.pairGroupId !== debt.pairGroupId) {
    pact.bossDebt = null;
    return satanPactApplyBossDebt(bot);
  }
  const factor = 1 + Math.max(0, debt.healthPct || 0) / 100;
  bot.maxHp = Math.ceil(bot.maxHp * factor);
  bot.hp = bot.maxHp;
  if (debt.zeroBounty) bot.bossBountyFactor = 0;
  if (bot.pairGroupId && !debt.pairGroupId) {
    debt.pairGroupId = bot.pairGroupId; // the twin spawns right after and pays too
  } else {
    pact.bossDebt = null;
  }
  addLog(`${SATAN_DEAL_SOURCE}: ${bot.name} came with ${debt.healthPct}% more SOUL${debt.zeroBounty ? " and no BOSS BOUNTY" : ""}.`);
}

function satanPactCheatDeathArmed() {
  return Boolean(state.pact?.cheatDeath && state.mode === "arcade");
}

// a blow that would kill you: back with 1 SOUL, and Satan collects (returns the new SOUL)
function satanPactCheatDeath() {
  const pact = satanPact();
  pact.cheatDeath = false;
  const options = [];
  const seals = satanPactOwnedSeals();
  if (seals.length) options.push("seal");
  if (Math.ceil(state.player.credits || 0) > 0) options.push("sin");
  options.push("boss");
  const pick = options[Math.floor(Math.random() * options.length)];
  let taken = "";
  if (pick === "seal") {
    const seal = seals[Math.floor(Math.random() * seals.length)];
    satanPactRemoveSeal(seal);
    taken = `your ${seal.name}`;
  } else if (pick === "sin") {
    const before = Math.max(0, Math.ceil(state.player.credits || 0));
    const lost = Math.ceil(before * 0.5);
    state.player.credits = before - lost;
    taken = `${lost} SIN`;
  } else {
    const pct = Math.round(50 * satanPactRoll());
    pact.bossDebt = { healthPct: pct, zeroBounty: false, pairGroupId: null };
    taken = `a debt: the next BOSS comes with ${pct}% more SOUL`;
  }
  const message = `Satan dragged you back from death with 1 SOUL and took ${taken}.`;
  if (state.roundState) addRoundEvent(message);
  addLog(message);
  return 1;
}

/* ---- your SEALS ---- */
function satanPactOwnedSeals() {
  return (state.player.passives || []).filter((item) => item && !REMOVED_PASSIVE_IDS.has(item.id));
}

function satanPactRemoveSeal(seal) {
  const index = state.player.passives.indexOf(seal);
  if (index >= 0) state.player.passives.splice(index, 1);
  refreshMimicTarget();
}

function satanPactBuildFactor(sealId, owned = satanPactOwnedSeals()) {
  const tags = (SEAL_BUILD_TAGS[sealId] || []).filter((tag) => tag !== "general");
  const strongest = tags.reduce((best, tag) => Math.max(best, owned.filter((item) => (SEAL_BUILD_TAGS[item.id] || []).includes(tag)).length), 0);
  return strongest >= SATAN_DEAL_BUILD_STACK ? SATAN_DEAL_BUILD_FACTOR : 1;
}

function satanPactAllSlotsOpen() {
  return passiveLimit() >= MAX_PASSIVE_LIMIT;
}

const SATAN_PACT_GOETIC_IDS = new Set(GOETIC_BOSS_SPECS.map((spec) => spec.passiveId));

function satanPactDemonForSeal(id) {
  return GOETIC_BOSS_SPECS.find((spec) => spec.passiveId === id) || null;
}

/* ---- reading what you typed ---- */
const SATAN_PACT_STOP_WORDS = new Set(["seal", "seals", "of", "the", "a", "an", "i", "want", "give", "me", "my", "your", "please", "some", "for", "to", "and", "dr", "dee", "dees", "with", "can", "get", "have", "need", "would", "like", "on", "x", "more", "copies", "copy"]);
const SATAN_PACT_NUMBER_WORDS = { one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10, couple: 2, pair: 2 };

function satanPactNormalize(text) {
  return String(text || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/['’]/g, "")
    .replace(/[^a-z0-9\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function satanPactNumber(normalized) {
  const digits = normalized.match(/\b(\d{1,4})\b/);
  if (digits) return Number(digits[1]);
  for (const word of normalized.split(" ")) if (SATAN_PACT_NUMBER_WORDS[word]) return SATAN_PACT_NUMBER_WORDS[word];
  return null;
}

function satanPactDistance(a, b) {
  const d = Array.from({ length: a.length + 1 }, (_, i) => [i]);
  for (let j = 1; j <= b.length; j += 1) d[0][j] = j;
  for (let i = 1; i <= a.length; i += 1) {
    for (let j = 1; j <= b.length; j += 1) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + cost);
      if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) d[i][j] = Math.min(d[i][j], d[i - 2][j - 2] + 1);
    }
  }
  return d[a.length][b.length];
}

function satanPactSimilarity(a, b) {
  const strip = (word) => (word.length > 4 && word.endsWith("es") ? word.slice(0, -2) : word.length > 3 && word.endsWith("s") ? word.slice(0, -1) : word);
  const x = strip(a);
  const y = strip(b);
  return 1 - satanPactDistance(x, y) / Math.max(x.length, y.length, 1);
}

function satanPactWords(normalized) {
  return normalized.split(" ").filter((word) => word.length >= 3 && !SATAN_PACT_STOP_WORDS.has(word) && !SATAN_PACT_NUMBER_WORDS[word] && !/^\d+$/.test(word));
}

// best name match among ids; returns { id, score } or null
function satanPactMatchName(normalized, ids, nameOf = (id) => ITEMS[id]?.name || "") {
  const queryWords = satanPactWords(normalized);
  let best = null;
  ids.forEach((id) => {
    const full = satanPactNormalize(nameOf(id));
    if (!full) return;
    const keyWords = satanPactWords(full);
    if (!keyWords.length) return;
    let score = 0;
    if (normalized.includes(full) || (keyWords.length > 1 && normalized.includes(keyWords.join(" ")))) score = 100;
    else {
      let hits = 0;
      let top = 0;
      keyWords.forEach((keyWord) => {
        const sim = queryWords.reduce((max, word) => Math.max(max, satanPactSimilarity(keyWord, word)), 0);
        // short words must be spelled right ("heal" is not "head"); longer ones forgive a typo or two
        const needed = keyWord.length <= 4 ? 1 : 0.75;
        if (sim >= needed) {
          hits += 1;
          top = Math.max(top, sim);
        }
      });
      if (hits) score = 50 * top + 25 * (hits / keyWords.length);
    }
    if (score >= 50 && (!best || score > best.score)) best = { id, score };
  });
  return best;
}

function satanPactRequestableArtifactIds() {
  return ACTIVE_IDS.filter((id) => !RESERVED_ARTIFACT_IDS.includes(id) && ITEMS[id]);
}

// every SEAL with a distinct name, Goetic first so a shared name means the demon's SEAL
function satanPactNamedSealIds() {
  const ids = Object.keys(ITEMS).filter((id) => ITEMS[id]?.type === "passive" && !REMOVED_PASSIVE_IDS.has(id));
  ids.sort((a, b) => (SATAN_PACT_GOETIC_IDS.has(b) ? 1 : 0) - (SATAN_PACT_GOETIC_IDS.has(a) ? 1 : 0));
  const seen = new Set();
  return ids.filter((id) => {
    const name = ITEMS[id].name;
    if (seen.has(name)) return false;
    seen.add(name);
    return true;
  });
}

function satanPactSealSection(id) {
  const section = COLLECTION_SECTIONS.find((entry) => entry.ids && entry.ids.includes(id));
  return section ? section.key : "player";
}

/* What you asked for. Returns { intent, ... } (never decides the price). */
function satanPactParse(text) {
  const normalized = satanPactNormalize(text);
  const number = satanPactNumber(normalized);
  if (!normalized) return { intent: "gibberish" };
  if (/\b(seal of satan|satans seal|your own seal|your seal|lucifer)\b/.test(normalized)) return { intent: "satanSeal" };
  const sealMatch = satanPactMatchName(normalized, satanPactNamedSealIds());
  if (/\b(elite|upgrade|stronger|level up)\b/.test(normalized)) {
    const owned = satanPactOwnedSeals().map((item) => item.id);
    const ownedMatch = satanPactMatchName(normalized, owned);
    return { intent: "elite", sealId: ownedMatch?.id || sealMatch?.id || null };
  }
  if (/\b(cheat death|revive|resurrect|second life|extra life|another life|undying|immortal|dont let me die|resurrection)\b/.test(normalized)) return { intent: "cheatDeath" };
  if (/\b(kill|murder|slay|eliminate|destroy|execute)\b/.test(normalized)) {
    const living = state.bots.filter((bot) => bot.hp > 0 && !bot.eliminated);
    const named = satanPactMatchName(normalized, living.map((bot) => bot.id), (id) => living.find((bot) => bot.id === id)?.name || "");
    return { intent: "kill", botId: named ? named.id : null };
  }
  const artifactMatch = satanPactMatchName(normalized, satanPactRequestableArtifactIds());
  if (artifactMatch && (!sealMatch || artifactMatch.score >= sealMatch.score)) {
    return { intent: "artifact", id: artifactMatch.id, count: number && number > 1 ? number : 1 };
  }
  if (sealMatch) return { intent: "seal", id: sealMatch.id };
  if (/\b(use|uses|action|actions)\b/.test(normalized)) return { intent: "uses", n: number || 1 };
  if (/\b(heal|healing|health|soul|hp|cure|life|patch)\b/.test(normalized)) return { intent: "heal", n: number };
  if (/\b(sin|sins|money|cash|gold|coins|riches|wealth)\b/.test(normalized)) return { intent: "sin", n: number };
  return { intent: "gibberish" };
}

/* ---- prices ---- */
function satanPactFill(text, vars = {}) {
  return String(text).replace(/\{([A-Z]+)\}/g, (whole, key) => (key === "SIN" ? whole : vars[key] !== undefined ? String(vars[key]) : whole));
}

function satanPactPartText(part) {
  const t = SATAN_DEAL_PRICE_TEXT;
  switch (part.type) {
    case "hp":
      return satanPactFill(t.hp, { N: part.n });
    case "sin":
      return satanPactFill(t.sin, { N: part.n });
    case "useCap":
      return satanPactFill(part.cap === 0 ? t.useCapZero : t.useCap, { M: part.rounds });
    case "shopClosed":
      return satanPactFill(t.shopClosed, { M: part.rounds });
    case "bossHealth":
      return satanPactFill(t.bossHealth, { N: part.pct }) + (part.zeroBounty ? `, and ${t.bossBounty}` : "");
    case "loseSeal":
      return satanPactFill(t.loseSeal, { SEAL: ITEMS[part.id]?.name || "SEAL" });
    case "damageTaken":
      return satanPactFill(t.damageTaken, { N: part.pct, M: part.rounds });
    case "noArtifacts":
      return t.noArtifacts;
    case "keepBounty":
      return t.keepBounty;
    default:
      return "";
  }
}

function satanPactPriceText(parts) {
  const texts = parts.map(satanPactPartText).filter(Boolean);
  if (!texts.length) return SATAN_DEAL_PRICE_TEXT.nothing;
  if (texts.length === 1) return texts[0];
  return `${texts.slice(0, -1).join(", ")} and ${texts[texts.length - 1]}`;
}

function satanPactRandomOf(options) {
  return options[Math.floor(Math.random() * options.length)];
}

// a random SEAL of yours, never the one named in except
function satanPactRandomSealToLose(exceptUid = null) {
  const seals = satanPactOwnedSeals().filter((item) => item.uid !== exceptUid || !exceptUid);
  return seals.length ? satanPactRandomOf(seals) : null;
}

function satanPactArtifactRoom() {
  return Math.max(0, activeInventoryLimit() - state.player.actives.length);
}

function satanPactBaseUseLimitWithoutPact() {
  return hasPassive("p24") ? 1 : ACTIVE_USES_PER_ROUND + baseEditionBonus("p126");
}

function satanPactArtifactOffer(id, askedCount) {
  const room = satanPactArtifactRoom();
  if (room <= 0) return { refuse: "handsFull" };
  const capped = askedCount > SATAN_DEAL_MAX_COPIES;
  const count = Math.max(1, Math.min(askedCount, SATAN_DEAL_MAX_COPIES, room));
  const item = ITEMS[id];
  const unit = Math.max(1, shopPrice({ ...item }));
  const from = satanPactEffectRound();
  const hp = state.player.hp;
  const options = [];
  if (count === 1) {
    const hpCost = Math.max(2, Math.round(0.5 * unit * satanPactRoll()));
    if (hp - hpCost >= 1) options.push([{ type: "hp", n: hpCost }]);
    const sinCost = Math.max(1, Math.round(3 * unit * satanPactRoll()));
    if (Math.ceil(state.player.credits || 0) >= sinCost) options.push([{ type: "sin", n: sinCost }]);
    const rounds = Math.max(1, Math.round(3 * satanPactRoll()));
    const cap = satanPactBaseUseLimitWithoutPact() > 1 ? 1 : 0;
    options.push([{ type: "useCap", cap, from, to: from + rounds - 1, rounds }]);
  } else {
    const rounds = Math.max(1, Math.round(count * satanPactRoll()));
    options.push([{ type: "shopClosed", from, to: from + rounds - 1, rounds }]);
    const hpCost = Math.max(2, Math.round(0.5 * unit * count * satanPactRoll()));
    if (hp - hpCost >= 1) options.push([{ type: "hp", n: hpCost }]);
  }
  const price = satanPactRandomOf(options);
  const vars = { ITEM: item.name, COUNT: count };
  const lines = [...(capped ? SATAN_DEAL_LINES.artifactsCapped : []), ...(count === 1 ? SATAN_DEAL_LINES.artifact : SATAN_DEAL_LINES.artifacts)];
  return { gain: { type: "artifact", id, count }, price, lines, vars, request: count === 1 ? item.name : `${count}x ${item.name}` };
}

function satanPactEliteOffer(sealId) {
  if (!satanPactAllSlotsOpen()) return { refuse: "tooEarly" };
  if (!sealId) return { refuse: "eliteWhich" };
  const owned = satanPactOwnedSeals();
  const requested = owned.find((item) => item.id === sealId);
  if (!requested) return { refuse: "eliteNotOwned" };
  if (isNonUpgradableSeal(sealId)) return { refuse: "eliteCannot", vars: { SEAL: ITEMS[sealId].name } };
  const pool = owned.filter((item) => !isNonUpgradableSeal(item.id));
  const weights = pool.map((item) => (item === requested ? 4 : 1));
  let roll = Math.random() * weights.reduce((sum, weight) => sum + weight, 0);
  let target = pool[pool.length - 1];
  for (let i = 0; i < pool.length; i += 1) {
    roll -= weights[i];
    if (roll <= 0) {
      target = pool[i];
      break;
    }
  }
  const factor = satanPactBuildFactor(target.id, owned);
  const vars = { SEAL: ITEMS[sealId].name, OTHER: ITEMS[target.id].name };
  if (target === requested) {
    const options = [[{ type: "bossHealth", pct: Math.round(50 * satanPactRoll() * factor) }]];
    const lose = satanPactRandomSealToLose(target.uid);
    if (lose) options.push([{ type: "loseSeal", id: lose.id, uid: lose.uid }]);
    return { gain: { type: "elite", id: target.id, uid: target.uid }, price: satanPactRandomOf(options), lines: SATAN_DEAL_LINES.elite, vars, request: `ELITE ${ITEMS[target.id].name}` };
  }
  return {
    gain: { type: "elite", id: target.id, uid: target.uid },
    price: [{ type: "bossHealth", pct: Math.round(30 * satanPactRoll() * factor) }],
    lines: SATAN_DEAL_LINES.eliteOther,
    vars,
    request: `ELITE ${ITEMS[target.id].name}`
  };
}

function satanPactSealOffer(id) {
  const section = satanPactSealSection(id);
  if (SELF_STACKING_SEAL_IDS.has(id) || section === "archangel") return { refuse: "angel" };
  if (section === "trinity") return { refuse: "trinity" };
  if (section === "saturn") return { refuse: "saturn" };
  if (section === "apocalypse") return { refuse: "apocalypse" };
  if (section === "satan") return satanPactSatanSealOffer();
  if (!SATAN_PACT_GOETIC_IDS.has(id)) return { refuse: "notDemon" };
  if (isSealLocked(id)) return { refuse: "locked" };
  if (isBoundDemonSeal(id)) return { refuse: "bound" };
  if (!satanPactAllSlotsOpen()) return { refuse: "tooEarly" };
  const demon = satanPactDemonForSeal(id);
  const vars = { SEAL: ITEMS[id].name, DEMON: demon?.name || ITEMS[id].name };
  if (directPassiveStack(id)) return { refuse: "sealOwned", vars };
  if (suppressingBossForSeal(id)) return { refuse: "demonBusy", vars };
  const owned = satanPactOwnedSeals();
  const lose = satanPactRandomSealToLose();
  const slotsAfter = ownedSealSlotCount() - (lose ? sealSlotCost(lose) : 0) + sealSlotCost(id);
  if (slotsAfter > passiveLimit()) return { refuse: "noRoomSeal", vars };
  const acceptChance = demon && isDemonSlain(demon.key) ? SATAN_DEAL_SEAL_ACCEPT_SLAIN : SATAN_DEAL_SEAL_ACCEPT;
  if (Math.random() >= acceptChance) return { refuse: "sealRefused", vars, lock: true };
  const factor = satanPactBuildFactor(id, owned);
  const price = [];
  if (lose) price.push({ type: "loseSeal", id: lose.id, uid: lose.uid });
  const hpCost = Math.max(1, Math.round(ITEMS[id].price * satanPactRoll() * factor));
  if (state.player.hp - hpCost >= 1) price.push({ type: "hp", n: hpCost });
  else {
    const from = satanPactEffectRound();
    const rounds = Math.max(1, Math.round(3 * satanPactRoll() * factor));
    price.push({ type: "damageTaken", pct: 50, from, to: from + rounds - 1, rounds });
  }
  const sinCost = Math.round(0.2 * Math.max(0, Math.ceil(state.player.credits || 0)) * satanPactRoll() * factor);
  if (sinCost > 0) price.push({ type: "sin", n: Math.min(sinCost, Math.ceil(state.player.credits || 0)) });
  return { gain: { type: "seal", id }, price, lines: SATAN_DEAL_LINES.seal, vars, request: ITEMS[id].name };
}

function satanPactSatanSealOffer() {
  if (!satanPactAllSlotsOpen()) return { refuse: "tooEarly" };
  if (satanPactOwnedSeals().length) return { refuse: "satanSealNotEmpty" };
  return { gain: { type: "seal", id: "p111" }, price: [], lines: SATAN_DEAL_LINES.satanSeal, vars: {}, request: ITEMS.p111.name };
}

function satanPactHealOffer(asked) {
  if (state.player.hp >= playerMaxHp()) return { refuse: "fullHealth" };
  const askedN = asked && asked > 0 ? asked : SATAN_DEAL_MAX_HEAL;
  const n = Math.min(askedN, SATAN_DEAL_MAX_HEAL);
  const price = [{ type: "bossHealth", pct: Math.max(1, Math.round(10 * n * satanPactRoll())) }];
  const lines = askedN > SATAN_DEAL_MAX_HEAL ? SATAN_DEAL_LINES.healTooMuch : SATAN_DEAL_LINES.heal;
  return { gain: { type: "heal", n }, price, lines, vars: { N: n, ASKED: askedN }, request: `${n} SOUL` };
}

function satanPactSinOffer(asked) {
  if (!asked || asked <= 0) return { refuse: "sinHowMuch" };
  let n = Math.floor(asked);
  const pctRoll = satanPactRoll();
  const hpRoll = satanPactRoll();
  const hpCostFor = (amount) => (amount > 20 ? Math.max(1, Math.round(Math.ceil((amount - 20) / 3) * hpRoll)) : 0);
  let capped = false;
  while (n > 20 && state.player.hp - hpCostFor(n) < 1) {
    n -= 1;
    capped = true;
  }
  const price = [{ type: "bossHealth", pct: Math.max(1, Math.round(2 * n * pctRoll)), zeroBounty: true }];
  const hpCost = hpCostFor(n);
  if (hpCost > 0) price.push({ type: "hp", n: hpCost });
  return { gain: { type: "gainSin", n }, price, lines: capped ? SATAN_DEAL_LINES.sinCapped : SATAN_DEAL_LINES.sin, vars: { N: n }, request: `${n} SIN` };
}

function satanPactKillOffer(botId) {
  if (!botId) return { refuse: "killWho" };
  const bot = state.bots.find((entry) => entry.id === botId);
  if (!bot || bot.hp <= 0 || bot.eliminated) return { refuse: "killWho" };
  if (bot.isBoss || bot.immortal) return { refuse: "killBoss" };
  const round = satanPactEffectRound();
  return {
    gain: { type: "kill", botId },
    price: [{ type: "noArtifacts", round }, { type: "keepBounty" }],
    lines: SATAN_DEAL_LINES.kill,
    vars: { NAME: bot.name },
    request: `the death of ${bot.name}`
  };
}

function satanPactUsesOffer(asked) {
  const tooMany = asked > 2;
  const n = Math.max(1, Math.min(2, asked || 1));
  const round = satanPactEffectRound();
  const rounds = Math.max(1, Math.round((n === 1 ? 2 : 5) * satanPactRoll()));
  const cap = satanPactBaseUseLimitWithoutPact() > 1 ? 1 : 0;
  const lines = [...(tooMany ? SATAN_DEAL_LINES.usesTooMany : []), ...(n === 1 ? SATAN_DEAL_LINES.uses : SATAN_DEAL_LINES.usesTwo)];
  return {
    gain: { type: "useBonus", n, round },
    price: [{ type: "useCap", cap, from: round + 1, to: round + rounds, rounds }],
    lines,
    vars: { N: n },
    request: `+${n} ARTIFACT use${n === 1 ? "" : "s"}`
  };
}

function satanPactCheatDeathOffer() {
  if (satanPact().cheatDeath) return { refuse: "cheatDeathAlready" };
  return { gain: { type: "cheatDeath" }, price: [], lines: SATAN_DEAL_LINES.cheatDeath, vars: {}, request: "a second life" };
}

// what Satan answers to a request: { refuse, vars, lock } or an offer
function satanPactAnswer(text) {
  const asked = satanPactParse(text);
  switch (asked.intent) {
    case "artifact":
      return satanPactArtifactOffer(asked.id, asked.count);
    case "elite":
      return satanPactEliteOffer(asked.sealId);
    case "seal":
      return satanPactSealOffer(asked.id);
    case "satanSeal":
      return satanPactSatanSealOffer();
    case "heal":
      return satanPactHealOffer(asked.n);
    case "sin":
      return satanPactSinOffer(asked.n);
    case "kill":
      return satanPactKillOffer(asked.botId);
    case "uses":
      return satanPactUsesOffer(asked.n);
    case "cheatDeath":
      return satanPactCheatDeathOffer();
    default:
      return { refuse: "gibberish", vars: { Q: String(text || "").trim().slice(0, 40) || "..." } };
  }
}

// the lines Satan says for an answer (offers end with the question)
function satanPactAnswerLines(answer) {
  const vars = { ...(answer.vars || {}) };
  if (answer.refuse) {
    return (SATAN_DEAL_LINES[answer.refuse] || SATAN_DEAL_LINES.gibberish).map(([speaker, text]) => [speaker, satanPactFill(text, vars)]);
  }
  vars.PRICE = satanPactPriceText(answer.price);
  const lines = answer.lines.map(([speaker, text]) => [speaker, satanPactFill(text, vars)]);
  // the question goes on the same line as the price, so YES / NO sit right under it
  const question = SATAN_DEAL_LINES.question.map(([, text]) => text).join(" ");
  const last = lines[lines.length - 1];
  lines[lines.length - 1] = [last[0], `${last[1]} ${question}`];
  return lines;
}

/* ---- YES: pay and receive ---- */
function satanPactPay(part) {
  const pact = satanPact();
  switch (part.type) {
    case "hp": {
      const cost = Math.max(0, Math.min(part.n, state.player.hp - 1));
      state.player.hp -= cost;
      if (cost > 0) {
        state.playerLastDamage = (state.playerLastDamage || 0) + cost;
        recordPlayerDamageSource(cost, SATAN_DEAL_SOURCE);
      }
      break;
    }
    case "sin": {
      const before = Math.max(0, Math.ceil(state.player.credits || 0));
      state.player.credits = before - Math.min(before, part.n);
      break;
    }
    case "useCap":
      pact.useCaps.push({ from: part.from, to: part.to, cap: part.cap });
      break;
    case "noArtifacts":
      pact.useCaps.push({ from: part.round, to: part.round, cap: 0 });
      break;
    case "shopClosed":
      pact.shopClosed = { from: part.from, to: part.to };
      syncShopSlotCount();
      break;
    case "bossHealth":
      pact.bossDebt = { healthPct: part.pct, zeroBounty: Boolean(part.zeroBounty), pairGroupId: null };
      break;
    case "loseSeal": {
      const seal = state.player.passives.find((item) => item.uid === part.uid) || state.player.passives.find((item) => item.id === part.id);
      if (seal) satanPactRemoveSeal(seal);
      break;
    }
    case "damageTaken":
      pact.damageTaken = { from: part.from, to: part.to, pct: part.pct };
      break;
    default:
      break;
  }
}

function satanPactReceive(gain) {
  const pact = satanPact();
  switch (gain.type) {
    case "artifact":
      for (let i = 0; i < gain.count && state.player.actives.length < activeInventoryLimit(); i += 1) {
        state.player.actives.push(freeActiveCopy(gain.id));
      }
      state.activeCarouselIndex = Math.max(0, state.player.actives.length - 1);
      break;
    case "elite": {
      const seal = state.player.passives.find((item) => item.uid === gain.uid) || state.player.passives.find((item) => item.id === gain.id);
      if (seal) {
        seal.stack = (seal.stack || 1) + 1;
        seal.freeStacks = (seal.freeStacks || 0) + 1;
        recordEliteLevelBought(seal.id, seal.stack);
      }
      break;
    }
    case "seal": {
      const seal = itemCopy(gain.id);
      seal.freeStacks = 1;
      state.player.passives.push(seal);
      refreshMimicTarget();
      recordPlayedSeal(gain.id);
      break;
    }
    case "heal": {
      const before = state.player.hp;
      state.player.hp = Math.min(playerMaxHp(), state.player.hp + gain.n);
      const healed = state.player.hp - before;
      if (healed > 0) {
        state.playerLastHeal = (state.playerLastHeal || 0) + healed;
        recordPlayerHealSource(healed, SATAN_DEAL_SOURCE);
      }
      break;
    }
    case "gainSin":
      gainCredits(gain.n, false, SATAN_DEAL_SOURCE);
      break;
    case "kill": {
      const bot = state.bots.find((entry) => entry.id === gain.botId);
      if (bot && bot.hp > 0 && !bot.eliminated && !bot.isBoss) {
        bot.lastDamage = (bot.lastDamage || 0) + bot.hp;
        bot.hp = 0;
        bot.skipEliminationReward = true;
        bot.deathCause = "satan";
        bot.deathNotice = "SATAN";
        if (state.roundState) {
          state.roundState.roundEvents.push(`Satan took ${bot.name}. Its BOUNTY is his.`);
          resolveEliminatedBots([bot]);
        }
      }
      break;
    }
    case "useBonus":
      pact.useBonus = { round: gain.round, n: gain.n };
      break;
    case "cheatDeath":
      pact.cheatDeath = true;
      break;
    default:
      break;
  }
}

// YES: pay everything, then receive; the chance is used
function satanPactSign() {
  const pact = satanPact();
  const offer = pact.offer;
  if (!offer) return false;
  offer.price.forEach(satanPactPay);
  satanPactReceive(offer.gain);
  pact.used = true;
  pact.outcome = "signed";
  recordPactSigned();
  pact.request = offer.request || "";
  pact.offer = null;
  addLog(`${SATAN_DEAL_SOURCE}: you got ${offer.request} for ${satanPactPriceText(offer.price).replace(/\{SIN\}/g, "")}.`);
  return true;
}

// NO: the chance is gone for this run
function satanPactRefuse() {
  const pact = satanPact();
  pact.used = true;
  pact.outcome = "refused";
  pact.offer = null;
  addLog("You refused Satan's deal. He will not offer again this run.");
}

// a request: an offer waits for YES / NO; a refusal maybe locks the deal; returns the lines to say
function satanPactRequest(text) {
  const pact = satanPact();
  const answer = satanPactAnswer(text);
  if (!answer.refuse) {
    pact.offer = { gain: answer.gain, price: answer.price, request: answer.request, lines: satanPactAnswerLines(answer) };
    return { lines: pact.offer.lines, next: "offer" };
  }
  if (answer.lock) {
    pact.lockedAtBossKills = state.bossKills;
    return { lines: satanPactAnswerLines(answer), next: "leave" };
  }
  return { lines: satanPactAnswerLines(answer), next: "ask" };
}

/* ---- the scene (uses the story's Satan box: 09-intro-story.js) ---- */
const satanDealScene = { next: "ask" };

function openSatanDeal() {
  if (!satanPactCanOpenNow()) return;
  const pact = satanPact();
  state.pauseOpen = false;
  state.pauseScreen = "main";
  render();
  let lines;
  if (pact.offer) {
    lines = pact.offer.lines;
    satanDealScene.next = "offer";
  } else {
    lines = pact.opened ? SATAN_DEAL_LINES.openAgain : SATAN_DEAL_LINES.open;
    satanDealScene.next = "ask";
  }
  pact.opened = true;
  saveArcadeRun();
  satanOpenScene("deal", lines, "satan-deal-layer");
}

// the last part of his last line is down: show what comes next (the box to type in, or YES / NO)
function satanDealAfterTalk() {
  const box = introState.box;
  if (introState.phase !== "deal" || !box || box.classList.contains("intro-choosing")) return;
  if (satanDealScene.next === "ask") satanDealShowAsk();
  else if (satanDealScene.next === "offer") satanDealShowChoice();
}

// a click after the last line
function satanDealEndOfLines() {
  if (satanDealScene.next === "leave") satanLeaveScene("deal");
  else satanDealAfterTalk();
}

function satanDealShowAsk() {
  const box = introState.box;
  introSetWaiting(false);
  box.classList.add("intro-choosing");
  const form = document.createElement("form");
  form.className = "intro-choice pact-ask";
  form.setAttribute("autocomplete", "off");
  form.innerHTML = `
    <input class="pact-ask-input" type="text" maxlength="80" spellcheck="false" aria-label="What do you want from Satan?" />
    <button class="intro-choice-button" type="submit">${escapeHtml(SATAN_DEAL_BUTTONS.ask)}</button>
    <button class="intro-choice-button pact-ask-leave" type="button">${escapeHtml(SATAN_DEAL_BUTTONS.leave)}</button>`;
  const input = form.querySelector("input");
  input.placeholder = SATAN_DEAL_LINES.askPlaceholder;
  form.addEventListener("click", (event) => event.stopPropagation());
  form.addEventListener("submit", (event) => {
    event.preventDefault();
    satanDealAsk(input.value);
  });
  input.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      event.preventDefault();
      satanDealLeaveUnused();
    }
  });
  form.querySelector(".pact-ask-leave").addEventListener("click", satanDealLeaveUnused);
  box.appendChild(form);
  introFitText();
  setTimeout(() => input.focus(), 30);
}

function satanDealClearControls() {
  const box = introState.box;
  box?.querySelector(".intro-choice")?.remove();
  box?.classList.remove("intro-choosing");
}

function satanDealAsk(text) {
  if (introState.phase !== "deal") return;
  if (!String(text || "").trim()) return;
  satanDealClearControls();
  const result = satanPactRequest(text);
  satanDealScene.next = result.next;
  saveArcadeRun();
  introState.lines = result.lines;
  introShowLine(0);
}

function satanDealShowChoice() {
  const box = introState.box;
  introSetWaiting(false);
  box.classList.add("intro-choosing");
  const choice = document.createElement("div");
  choice.className = "intro-choice";
  choice.innerHTML = `
    <button class="intro-choice-button" type="button" data-choice="yes">${escapeHtml(SATAN_DEAL_BUTTONS.yes)}</button>
    <button class="intro-choice-button" type="button" data-choice="no">${escapeHtml(SATAN_DEAL_BUTTONS.no)}</button>`;
  choice.addEventListener("click", (event) => {
    event.stopPropagation();
    const button = event.target.closest("[data-choice]");
    if (button) satanDealChoose(button.dataset.choice === "yes");
  });
  box.appendChild(choice);
  introFitText();
}

function satanDealChoose(yes) {
  const box = introState.box;
  if (introState.phase !== "deal" || !box?.classList.contains("intro-choosing") || !satanPact().offer) return;
  satanDealClearControls();
  if (!yes) {
    satanPactRefuse();
    saveArcadeRun();
    render();
    satanDealScene.next = "leave";
    introState.lines = SATAN_DEAL_LINES.refused;
    introShowLine(0);
    return;
  }
  satanPactSign();
  satanDealScene.next = "leave";
  if (state.player.hp <= 0) finishGameOverRound();
  saveArcadeRun();
  // the pact sound and the red pulse, as when the story's pact was sealed
  box.classList.add("intro-box-hush", "intro-box-pulse");
  introState.glyphs = [];
  introState.shown = 0;
  introDrawText();
  introPlaySfx("introEvil");
  render();
  introLater(() => {
    if (introState.phase !== "deal") return;
    introState.box?.classList.remove("intro-box-pulse", "intro-box-hush");
    satanDealScene.next = "leave";
    introState.lines = SATAN_DEAL_LINES.signed;
    introShowLine(0);
  }, 2000);
}

// Leave / Esc while typing: he goes, the chance stays
function satanDealLeaveUnused() {
  if (introState.phase !== "deal") return;
  satanDealClearControls();
  satanLeaveScene("deal");
}

// skip: straight to the end of what he is saying (an offer to its YES / NO)
function satanDealSkip() {
  if (introState.box?.classList.contains("intro-choosing")) {
    if (satanDealScene.next === "ask") satanDealLeaveUnused();
    return;
  }
  if (satanDealScene.next === "leave") {
    satanLeaveScene("deal");
    return;
  }
  const last = introState.lines.length - 1;
  if (introState.lineIndex !== last) introShowLine(last);
  clearInterval(introState.typeTimer);
  introState.typeTimer = null;
  introState.typing = false;
  introState.chunk = introState.ends.length - 1;
  introState.shown = introState.glyphs.length;
  introDrawText();
  introPartTyped();
}

// on a short screen (the phone) the SEAL slots are too small for a conversation: the box grows upward
function satanDealBoxRect(rect) {
  if (!rect || typeof window === "undefined" || window.innerHeight >= 600) return rect;
  const bottom = rect.top + rect.height;
  const height = Math.max(rect.height, Math.round(window.innerHeight * 0.5));
  const width = Math.max(rect.width, Math.round(window.innerWidth * 0.55));
  return { left: rect.left, top: Math.max(4, bottom - height), width: Math.min(width, window.innerWidth - rect.left - 4), height: Math.min(height, bottom - 4) };
}

/* ---- the DEAL button, under the Pause button ---- */
// hidden in the story's tutorial; greyed out once the deal is made, refused or locked
function satanDealButtonHtml() {
  if (state.mode !== "arcade") return "";
  if (["black", "judgement", "booting", "tutorial", "pact", "reveal"].includes(introState.phase)) return "";
  const pact = satanPact();
  let tooltip = "Make a deal with Satan. Once per run.";
  if (pact.used) {
    tooltip = pact.outcome === "signed" ? `Deal signed: ${pact.request}.` : "You refused Satan. He will not offer again this run.";
  } else if (satanPactLocked()) {
    tooltip = "Satan is not listening. Kill another BOSS.";
  } else if (!satanPactCanOpenNow()) {
    tooltip = "Not right now.";
  }
  const disabled = !satanPactCanOpenNow() ? "disabled" : "";
  const urgent = satanPactPulseUrgent();
  const pulse = satanPactPulseActive() ? `pact-calling${urgent ? " pact-urgent" : ""}` : "";
  // every render rebuilds the button: the delay keeps the pulse running from where it was
  const period = urgent ? SATAN_DEAL_PULSE_FAST_MS : SATAN_DEAL_PULSE_MS;
  const phase = pulse ? ` style="animation-delay: -${Date.now() % period}ms"` : "";
  return `<button class="pause-button deal-button ${pulse}" id="dealButton" aria-label="Make a deal with Satan" data-tooltip="${escapeAttr(tooltip)}"${phase} ${disabled}>DEAL</button>`;
}
function bindPvpEvents() {
  if (state.mode !== "pvp" || !state.pvp) return;

  const start = document.querySelector("#pvpReadyLobby");
  if (start) bindOn(start, "click", pvpFillBotsAndStart);

  const addSlot = document.querySelector("#pvpAddSlot");
  if (addSlot) bindOn(addSlot, "click", pvpAddEmptySlot);

  const removeSlot = document.querySelector("#pvpRemoveSlot");
  if (removeSlot) bindOn(removeSlot, "click", pvpRemoveEmptySlot);

  document.querySelectorAll("[data-pvp-remove-slot]").forEach((button) => {
    bindOn(button, "click", () => pvpRemoveLobbySlot(Number(button.dataset.pvpRemoveSlot)));
  });

  const nextRound = document.querySelector("#pvpNextRound");
  if (nextRound) {
    bindOn(nextRound, "click", () => {
      playNextRoundSfx();
      pvpNextRound();
    });
  }

  const restart = document.querySelector("#pvpRestart");
  if (restart) bindOn(restart, "click", restartPvpMode);
}

// Pause > DEV SEAL search: suggestions update in place while typing (no full render, so the box keeps focus).
// The list floats over the menu like a search engine's, so the box never moves while typing.
function refreshDevSealSuggestions() {
  const list = document.querySelector("#devSealSuggestions");
  const input = document.querySelector("#devSealSearch");
  if (!list) return;
  list.innerHTML = renderDevSealSuggestions(state.devSealQuery || "");
  list.querySelectorAll("[data-dev-seal-pick]").forEach((button) => {
    // keep the focus in the search box while picking
    bindOn(button, "mousedown", (event) => event.preventDefault());
    bindOn(button, "click", () => pickDevSealSuggestion(button.dataset.devSealPick));
  });
  const open = Boolean(input) && document.activeElement === input && !state.devSealListClosed && list.children.length > 0;
  list.classList.toggle("open", open);
  if (open) placeDevSealSuggestions(input, list);
}

// opens below the box when it fits, otherwise on the side with more room, never past the screen
function placeDevSealSuggestions(input, list) {
  const row = input.closest(".dev-seal-search-row") || input;
  const rect = row.getBoundingClientRect();
  const viewport = window.visualViewport;
  const top = viewport ? viewport.offsetTop : 0;
  const bottom = viewport ? viewport.offsetTop + viewport.height : window.innerHeight;
  const below = bottom - rect.bottom - 12;
  const above = rect.top - top - 12;
  list.style.maxHeight = "none";
  const needed = list.scrollHeight + 2;
  const up = needed > below && above > below;
  list.classList.toggle("above", up);
  list.style.maxHeight = `${Math.max(64, Math.floor(up ? above : below))}px`;
  list.querySelector(".highlighted")?.scrollIntoView({ block: "nearest" });
}

function setDevSealListClosed(closed) {
  state.devSealListClosed = closed;
  refreshDevSealSuggestions();
}

function setDevSealNote(note, ok = false) {
  state.devSealNote = note;
  state.devSealNoteOk = ok;
  const element = document.querySelector("#devSealNote");
  if (element) {
    element.textContent = note;
    element.classList.toggle("ok", ok);
  }
}

// a suggestion fills the search box with that SEAL's name
function pickDevSealSuggestion(id) {
  const input = document.querySelector("#devSealSearch");
  if (!ITEMS[id]) return;
  state.devSealQuery = ITEMS[id].name;
  state.devSealHighlight = -1;
  state.devSealListClosed = true;
  if (input) {
    input.value = state.devSealQuery;
    input.focus({ preventScroll: true });
  }
  setDevSealNote("");
  refreshDevSealSuggestions();
}

// the pentagram: give the SEAL (empty slot) or upgrade it once (already owned)
function useDevSealSearch() {
  // what the box shows (it can hold a suggestion picked with the arrow keys)
  const input = document.querySelector("#devSealSearch");
  if (input) state.devSealQuery = input.value;
  const resolved = devResolveSealQuery(state.devSealQuery || "");
  if (!resolved.id) {
    setDevSealNote(resolved.note);
    // several matches: show them so one can be picked
    setDevSealListClosed(!devSealSuggestions(state.devSealQuery || "").length);
    return;
  }
  const result = devGrantSeal(resolved.id);
  state.devSealQuery = ITEMS[resolved.id].name;
  state.devSealHighlight = -1;
  state.devSealListClosed = true;
  state.devSealNote = result.note;
  state.devSealNoteOk = result.ok;
  render();
}

function bindDevSealSearch() {
  const input = document.querySelector("#devSealSearch");
  const give = document.querySelector("#devSealGive");
  if (give) bindOn(give, "click", useDevSealSearch);
  if (!input) return;
  refreshDevSealSuggestions();
  bindOn(input, "input", () => {
    state.devSealQuery = input.value;
    state.devSealHighlight = -1;
    state.devSealListClosed = false;
    setDevSealNote("");
    refreshDevSealSuggestions();
  });
  bindOn(input, "focus", () => setDevSealListClosed(false));
  // hide the list once the box is left (a moment later, so a tapped suggestion still counts)
  bindOn(input, "blur", () => setTimeout(refreshDevSealSuggestions, 150));
  bindOn(input, "keydown", (event) => {
    const options = devSealSuggestions(state.devSealQuery || "");
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      if (!options.length) return;
      event.preventDefault();
      if (state.devSealListClosed) setDevSealListClosed(false);
      const step = event.key === "ArrowDown" ? 1 : -1;
      const current = Number.isInteger(state.devSealHighlight) ? state.devSealHighlight : -1;
      state.devSealHighlight = (current + step + options.length) % options.length;
      // like a search engine, the highlighted suggestion's name goes into the box
      const list = document.querySelector("#devSealSuggestions");
      list?.querySelectorAll("[data-dev-seal-pick]").forEach((button, index) => button.classList.toggle("highlighted", index === state.devSealHighlight));
      list?.querySelector(".highlighted")?.scrollIntoView({ block: "nearest" });
      input.value = ITEMS[options[state.devSealHighlight]].name;
      return;
    }
    if (event.key === "Tab" && options.length && devSealSearchText(input.value) !== devSealSearchText(ITEMS[options[0]].name)) {
      event.preventDefault();
      pickDevSealSuggestion(options[Math.max(0, state.devSealHighlight ?? 0)] || options[0]);
      return;
    }
    if (event.key === "Enter") {
      event.preventDefault();
      state.devSealQuery = input.value;
      useDevSealSearch();
      return;
    }
    if (event.key === "Escape" && document.activeElement === input) {
      // first Esc closes the suggestions and leaves the box; the next one closes Pause as usual
      event.preventDefault();
      setDevSealListClosed(true);
      input.blur();
    }
  });
}

function bindEvents() {
  document.querySelectorAll("[data-menu-action]").forEach((button) => {
    bindOn(button, "click", () => handleMenuAction(button.dataset.menuAction));
  });

  document.querySelectorAll("[data-run-slot-id]").forEach((button) => {
    bindOn(button, "click", () => {
      if (loadArcadeRun(button.dataset.runSlotId)) {
        resumeSoundtrack();
        render();
      } else {
        startGame();
      }
    });
  });

  document.querySelectorAll("[data-new-run]").forEach((button) => {
    bindOn(button, "click", () => startGame());
  });

  document.querySelectorAll("[data-remove-run-slot-id]").forEach((button) => {
    bindOn(button, "click", () => requestRunRemoval(button.dataset.removeRunSlotId));
  });

  document.querySelectorAll("[data-confirm-remove-run]").forEach((button) => {
    bindOn(button, "click", () => confirmRunRemoval(button.dataset.confirmRemoveRun));
  });

  document.querySelectorAll("[data-cancel-remove-run]").forEach((button) => {
    bindOn(button, "click", cancelRunRemoval);
  });

  document.querySelectorAll("[data-display-setting]").forEach((control) => {
    bindOn(control, "input", () => updateDisplaySetting(control.dataset.displaySetting, control.value));
  });

  document.querySelectorAll("[data-settings-tab]").forEach((button) => {
    bindOn(button, "click", () => {
      state.settingsTab = button.dataset.settingsTab;
      render();
    });
  });

  document.querySelectorAll("[data-setting-choice]").forEach((button) => {
    bindOn(button, "click", () => updateSettingChoice(button.dataset.settingChoice, Number(button.dataset.step) || 1));
  });

  document.querySelectorAll("[data-settings-reset]").forEach((button) => {
    bindOn(button, "click", resetSettings);
  });

  document.querySelectorAll("[data-settings-replay-story]").forEach((button) => {
    bindOn(button, "click", () => startIntroSequence({ fromMenu: true }));
  });

  document.querySelectorAll("[data-sound-setting]").forEach((control) => {
    const key = control.dataset.soundSetting;
    if (control.type === "checkbox") {
      bindOn(control, "change", () => updateSoundSetting(key, control.checked));
      return;
    }
    bindOn(control, "input", () => {
      updateSoundSetting(key, control.value, false);
      document.querySelectorAll(`[data-sound-value="${key}"]`).forEach((valueLabel) => {
        valueLabel.textContent = `${control.value}%`;
      });
    });
  });

  const pauseButton = document.querySelector("#pauseButton");
  if (pauseButton) bindOn(pauseButton, "click", openPauseMenu);

  const dealButton = document.querySelector("#dealButton");
  if (dealButton) bindOn(dealButton, "click", openSatanDeal);

  const playtestMoney = document.querySelector("#playtestMoney");
  if (playtestMoney) bindOn(playtestMoney, "click", togglePlaytestMoneyMode);

  const skipProgression = document.querySelector("#skipProgression");
  if (skipProgression) bindOn(skipProgression, "click", skipArcadeProgression);

  const mobileOfferingsToggle = document.querySelector("#mobileOfferingsToggle");
  if (mobileOfferingsToggle) {
    bindOn(mobileOfferingsToggle, "click", () => {
      state.mobileOfferingsOpen = true;
      render();
    });
  }

  const mobileOfferingsClose = document.querySelector("#mobileOfferingsClose");
  if (mobileOfferingsClose) {
    bindOn(mobileOfferingsClose, "click", () => {
      state.mobileOfferingsOpen = false;
      render();
    });
  }

  const mobileOfferingsBackdrop = document.querySelector("#mobileOfferingsBackdrop");
  if (mobileOfferingsBackdrop) {
    bindOn(mobileOfferingsBackdrop, "click", () => {
      state.mobileOfferingsOpen = false;
      render();
    });
  }

  document.querySelectorAll("[data-pause-action]").forEach((button) => {
    bindOn(button, "click", () => handlePauseAction(button.dataset.pauseAction));
  });

  bindPvpEvents();
  bindCollectionEvents();
  bindGiftsEvents();
  bindDevSealSearch();

  const mainAction = document.querySelector("#mainAction");
  if (mainAction) {
    bindOn(mainAction, "click", performMainAction);
  }

  const guessInput = document.querySelector("#guessInput");
  if (guessInput) {
    bindOn(guessInput, "keydown", (event) => {
      if (event.key === "Enter") {
        event.preventDefault();
        performMainAction();
      }
    });
  }

  document.querySelectorAll("[data-numpad-key]").forEach((button) => {
    bindOn(button, "click", () => {
      handleMobileNumpadKey(button.dataset.numpadKey);
      button.blur();
    });
  });

  document.querySelectorAll("[data-buy]").forEach((button) => {
    bindOn(button, "click", () => buyShopItem(Number(button.dataset.buy)));
  });

  document.querySelectorAll("[data-sell-passive]").forEach((button) => {
    bindOn(button, "click", () => sellPassive(Number(button.dataset.sellPassive)));
  });

  document.querySelectorAll("[data-sell-active]").forEach((button) => {
    bindOn(button, "click", () => sellActive(Number(button.dataset.sellActive)));
  });

  document.querySelectorAll("[data-use-active]").forEach((button) => {
    bindOn(button, "click", () => useActive(Number(button.dataset.useActive)));
  });

  document.querySelectorAll("[data-active-prev]").forEach((button) => {
    bindOn(button, "click", () => moveActiveCarousel(-1));
  });

  document.querySelectorAll("[data-active-next]").forEach((button) => {
    bindOn(button, "click", () => moveActiveCarousel(1));
  });

  const cancelActive = document.querySelector("#cancelPendingActive");
  if (cancelActive) bindOn(cancelActive, "click", cancelPendingActive);

  bindFloatingTooltips();

  document.querySelectorAll("[data-pick-bot]").forEach((button) => {
    bindOn(button, "click", () => chooseBot(Number(button.dataset.pickBot)));
  });

  const rerollButton = document.querySelector("#rerollShop");
  if (rerollButton) bindOn(rerollButton, "click", rerollShopClick);

  const restartButton = document.querySelector("#restartGame");
  if (restartButton) bindOn(restartButton, "click", startGame);

  const gameOverMenuButton = document.querySelector("#gameOverMenu");
  if (gameOverMenuButton) bindOn(gameOverMenuButton, "click", () => showMainMenu());

  const inspectButton = document.querySelector("#inspectGame");
  if (inspectButton) {
    bindOn(inspectButton, "click", () => {
      state.inspectingGameOver = true;
      render();
    });
  }
}

// hover tooltips (data-tooltip / data-tooltip-html) for everything under root; also used by screens that
// redraw themselves without a full render (Jesus' Gifts)
function bindFloatingTooltips(root = document) {
  const floatingTooltip = document.querySelector("#floatingTooltip");
  if (floatingTooltip) {
    root.querySelectorAll("[data-tooltip], [data-tooltip-html]").forEach((element) => {
      bindOn(element, "mouseenter", (event) => {
        if (touchTooltipMode()) setShiftTooltipMore(false); // on the phone every tooltip opens short
        floatingTooltipOwner = element;
        if (element.dataset.tooltipHtml) {
          floatingTooltip.innerHTML = element.dataset.tooltipHtml;
        } else {
          floatingTooltip.innerHTML = descriptionHtml(element.dataset.tooltip);
        }
        floatingTooltip.classList.add("visible");
        positionFloatingTooltip(event, floatingTooltip);
      });
      bindOn(element, "mousemove", (event) => {
        positionFloatingTooltip(event, floatingTooltip);
      });
      bindOn(element, "mouseleave", () => {
        // phone: tapping More inside the tooltip moves the "hover" off the SEAL; keep it open
        if (touchTooltipMode() && Date.now() - floatingTooltipTouchedAt < 1000) return;
        hideFloatingTooltip();
      });
    });
  }
}

function openPauseMenu() {
  state.pauseOpen = true;
  state.pauseScreen = "main";
  if (state.mode === "pvp") pvpSetHostPaused(true);
  render();
}

// Esc: opens Pause during a run; inside Pause it goes back one screen, then resumes.
// While an ARTIFACT is waiting for its target, Esc cancels that first.
// The intro and the collection handle their own Esc (they mark the event as handled).
function installPauseEscapeShortcut() {
  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape" || event.defaultPrevented || event.repeat) return;
    if (state.mode !== "arcade" && state.mode !== "pvp") return;
    if (introCapturesInput()) return;
    if (state.gameOver && !state.inspectingGameOver && !state.pauseOpen) return;
    event.preventDefault();
    if (state.pauseOpen) {
      handlePauseAction(state.pauseScreen && state.pauseScreen !== "main" ? "back" : "resume");
      return;
    }
    if (state.pendingActive) {
      cancelPendingActive();
      return;
    }
    if (state.mobileOfferingsOpen) {
      state.mobileOfferingsOpen = false;
      render();
      return;
    }
    openPauseMenu();
  });
}

function saveArcadeRunForNativeExit() {
  markNativeArcadeResumeOnForeground();
  saveArcadeRun();
}

// No text/image selection highlight anywhere (double-click or Ctrl+A turned the screen blue).
// Typing fields and the PvP join link stay selectable. The phone and desktop (Electron) apps
// also block the right-click menu and dragging images out; the browser keeps them for dev work.
const SELECTABLE_TARGETS = "input, textarea, [contenteditable], .pvp-join-url";

function nativeSelectionGuardsWanted() {
  return isNativeArcadeApp() || Boolean(desktopApp());
}

function blockSelection(event) {
  const target = event.target?.nodeType === 3 ? event.target.parentElement : event.target;
  if (target?.closest?.(SELECTABLE_TARGETS)) return;
  event.preventDefault();
}

function blockNativeSelection(event) {
  if (nativeSelectionGuardsWanted()) event.preventDefault();
}

// Tab does nothing anywhere: no jumping between buttons and no focus outline on them.
function installTabBlock() {
  document.addEventListener(
    "keydown",
    (event) => {
      if (event.key === "Tab") event.preventDefault();
    },
    { capture: true }
  );
}

function installNativeSelectionGuards() {
  document.addEventListener("selectstart", blockSelection, { passive: false });
  if (!nativeSelectionGuardsWanted()) return;
  document.addEventListener("contextmenu", blockNativeSelection, { passive: false });
  document.addEventListener("dragstart", blockNativeSelection, { passive: false });
}

window.addEventListener("resize", updateFullscreenLayoutClass);
window.addEventListener("pagehide", saveArcadeRunForNativeExit);
window.addEventListener("beforeunload", saveArcadeRunForNativeExit);
document.addEventListener("fullscreenchange", updateFullscreenLayoutClass);
document.addEventListener("visibilitychange", () => {
  if (document.visibilityState === "hidden") {
    saveArcadeRunForNativeExit();
    if (muteWhenInBackground()) pauseGameAudioForBackground();
    return;
  }
  if (isNativeArcadeApp() && state.mode === "menu") resumeNativeArcadeOnForeground();
  if (muteWhenInBackground()) resumeGameAudioAfterForeground();
});
// Settings > Audio > Mute in background (always on in the phone app)
function muteWhenInBackground() {
  return isNativeArcadeApp() || state.sound.muteInBackground !== false;
}

window.addEventListener("blur", () => {
  if (muteWhenInBackground()) pauseGameAudioForBackground();
});
window.addEventListener("focus", () => {
  if (muteWhenInBackground()) resumeGameAudioAfterForeground();
});
function refreshFullscreenSettingLabels() {
  document.querySelectorAll('[data-setting-value="fullscreen"]').forEach((label) => {
    label.textContent = isGameFullscreen() ? "Fullscreen" : "Windowed";
  });
}
document.addEventListener("fullscreenchange", refreshFullscreenSettingLabels);
// Desktop app: F11, Alt+Enter and Settings > Display > Window all change the Electron window.
desktopApp()?.onFullscreenChange?.(() => {
  refreshFullscreenSettingLabels();
  updateFullscreenLayoutClass();
});

loadSoundSettings();
loadDisplaySettings();
installAnimationSpeed();
installSoundtrack();
installArcadeEnterShortcut();
installPauseEscapeShortcut();
installShiftTooltipMore();
installNativeSelectionGuards();
installTabBlock();
updateFullscreenLayoutClass();
if (!resumeNativeArcadeOnForeground()) {
  if (pvpShouldAutoStartFromHash()) {
    if (window.history?.replaceState) window.history.replaceState(null, "", `${location.pathname}${location.search}`);
    startPvpMode();
  } else if (shouldPlayIntroOnLaunch()) {
    startIntroSequence();
  } else {
    showMainMenu();
  }
}
